  ["_CeladonGymBattleText6"] = "Non\nportare POKéMON\vInsetto o Fuoco\nqui dentro!",
  ["_CeladonGymBattleText7"] = "\nPiacere di\vconoscerti. Il mio\nhobby é\vl'allenamento\nPOKéMON.",
  ["_CeladonGymBattleText8"] = "\nBenvenuto nella\vPALESTRA DI\nAZZURROPOLI!\vFaresti meglio a\nnon sottovalutare\vle ragazze!",
