  ["_CeladonGymEndBattleText7"] = "Oh!\nSplendido!",
  ["_CeladonGymEndBattleText8"] = "Oh!\nBattuta!",
  ["_CeladonGymErikaPostBattleAdviceText"] = "\nCataloghi i\vPOKéMON? Devo dire\nche sono\vimpressionata. Non\ncollezionerei mai\vPOKéMON poco\nattraenti.",
  ["_CeladonGymErikaPreBattleText"] = "\nSalve. Che bel\vtempo, vero? é\ncosi' piacevole.\v...Oh cielo... Mi\nsono appisolata.\vBenvenuto. Mi\nchiamo ERIKA.\vSono la\nCAPOPALESTRA di\vAZZURROPOLI.\nInsegno l'arte\vdell'ikebana. I\nmiei POKéMON sono\vdi tipo Erba. Oh,\nperdona, non\vsapevo volessi\nsfidarmi. Va\vbene, ma non\nterro' testa\vbassa.",
  ["_CeladonGymErikaReceivedRainbowBadgeText"] = "Oh!\nAmmetto la\vsconfitta. Sei\ndavvero molto\vforte. Devo\nconferirti il\vMEDAGLIA\nARCOBALENO.",
  ["_CeladonGymRainbowBadgeInfoText"] = "Il\nMEDAGLIA\vARCOBALENO fara'\nubbidire i\vPOKéMON fino al\nLv. 50. Permette\vanche di usare\nFORZA dentro e\vfuori la lotta.\nPrendi anche\vquesto con te.",
