  ["_CeladonGymTM21NoRoomText"] = "\nDovresti fare\vspazio per questo.",
  ["_CeladonHotelBeautyText"] = "Sono in vacanza\ncon mio fratello\ve il mio ragazzo.\nAZZURROPOLI é una\vcitta' cosi'\ncarina!",
  ["_CeladonHotelGrannyText"] = "POKéMON? No,\nquesto é un hotel\vper persone. Siamo\nal completo.",
