  ["_CeladonMansion1FManagersSuiteSignText"] = "VILLA AZZURROPOLI\nSuite del Manager",
  ["_CeladonMansion1FMeowthText"] = "MEOWTH: Miau!",
  ["_CeladonMansion1FNidoranFText"] = "NIDORAN: Kya\nkyaoo!",
