  ["_CeladonMansion3FGraphicArtistText"] = "Sono il grafico!\nTi ho disegnato\vio!",
  ["_CeladonMansion3FPlayingGamePCText"] = "Qualcuno sta\ngiocando invece\vdi lavorare!",
  ["_CeladonMansion3FProgrammerText"] = "Io? Sono il\nprogrammatore!",
  ["_CeladonMansion3FWriterText"] = "Ho scritto la\nstoria! Non é\vcarina ERIKA? Mi\npiace molto anche\vMISTY! Oh, e\nSABRINA, lei mi\vpiace!",
