  ["_CeladonMart3FFightingGameText"] = "Un picchiaduro!\nSembra difficile!",
  ["_CeladonMart3FGameBoyKid1Text"] = "I POKéMON\ncatturati\vregistrano un Num.\nID e AO, il nome\vdell'Allenatore\nOriginale che li\vha catturati!",
  ["_CeladonMart3FGameBoyKid2Text"] = "Bene! Il mio amico\nmi scambia il suo\vKANGASKHAN per il\nmio GRAVELER!",
  ["_CeladonMart3FGameBoyKid3Text"] = "Forza GRAVELER!\nAdoro GRAVELER!\vLi colleziono! Eh?\nGRAVELER si é\vtrasformato in un\naltro POKéMON!",
  ["_CeladonMart3FLittleBoyText"] = "Puoi identificare\ni POKéMON presi\vnegli scambi dal\nloro Numero ID!",
  ["_CeladonMart3FPokemonPosterText"] = "Rosso e Blu! Sono\nentrambi POKéMON!",
  ["_CeladonMart3FPuzzleGameText"] = "Un puzzle game!\nCrea dipendenza!",
  ["_CeladonMart3FRPGText"] = "Un GdR! Non c'é\ntempo per quello!",
  ["_CeladonMart3FSNESText"] = "é un Super NES!",
  ["_CeladonMart3FSportsGameText"] = "Un gioco di sport!\nAl babbo\vpiacera'!",
  ["_CeladonMart4FCurrentFloorSignText"] = "Esprimiti con i\nregali! 4P:\vREGALI SAGGI\nSpeciale\vEvoluzione! PIETRE\nelementari in\vofferta!",
  ["_CeladonMart4FSuperNerdText"] = "Prendo una\nBAMBOLAPOKé per\vla mia ragazza!",
  ["_CeladonMart4FYoungsterText"] = "Ho sentito una\ncosa utile. Puoi\vfuggire dai\nPOKéMON selvatici\vdistraendoli con\nuna BAMBOLA POKé!",
  ["_CeladonMart5FCurrentFloorSignText"] = "5P: ERBORISTERIA",
  ["_CeladonMart5FGentlemanText"] = "I potenziatori di\nstatistiche si\vcomprano solo qui.\nUsa CALCIO per\vaumentare le\nabilita'\vSPECIALI. Usa\nCARBURANTE per\vaumentare la\nVELOCITA'.",
  ["_CeladonMart5FSailorText"] = "Sono qui per i\npotenziatori!\vPROTEINA aumenta\nil Attacco. FERRO\vaumenta la DIFESA!",
  ["_CeladonMartRoofCurrentFloorSignText"] = "REPARTO SUL TETTO:\nDISTRIBUTORI",
  ["_CeladonMartRoofLittleGirlGiveHerADrinkText"] = "Ho sete! Voglio\nqualcosa da bere!\vLe dai da bere?",
  ["_CeladonMartRoofLittleGirlGiveHerWhichDrinkText"] = "Quale bibita le\ndai?",
  ["_CeladonMartRoofLittleGirlImNotThirstyText"] = "No, grazie! Alla\nfine non ho piu'\vsete!",
  ["_CeladonMartRoofLittleGirlImThirstyText"] = "Ho sete! Voglio\nqualcosa da bere!",
  ["_CeladonMartRoofLittleGirlNoRoomText"] = "Non hai spazio per\nquesto!",
  ["_CeladonMartRoofLittleGirlReceivedTM13Text"] = "{PLAYER} ha\nricevuto\v{RAM:wStringBuffer}!",
  ["_CeladonMartRoofLittleGirlReceivedTM48Text"] = "{PLAYER} ha\nricevuto\v{RAM:wStringBuffer}!",
  ["_CeladonMartRoofLittleGirlReceivedTM49Text"] = "{PLAYER} ha\nricevuto MT49!",
  ["_CeladonMartRoofLittleGirlTM13ExplanationText"] = "{RAM:wStringBuffer}\ncontiene\vGELOPUNTO! A volte\npuo' congelare il\vbersaglio!",
  ["_CeladonMartRoofLittleGirlTM48ExplanationText"] = "{RAM:wStringBuffer}\ncontiene FRANA! A\vvolte puo'\nspaventare il\vbersaglio!",
  ["_CeladonMartRoofLittleGirlTM49ExplanationText"] = "La MT49 contiene\nTRIPLICE ATTACCO!",
  ["_CeladonMartRoofLittleGirlYayFreshWaterText"] = "Evviva! ACQUA\nFRESCA! Grazie!\vPuoi prendere\nquesto da parte\vmia!",
  ["_CeladonMartRoofLittleGirlYayLemonadeText"] = "Evviva! LIMONATA!\nGrazie! Puoi\vprendere questo da\nparte mia!",
  ["_CeladonMartRoofLittleGirlYaySodaPopText"] = "Evviva! BIBITA!\nGrazie! Puoi\vprendere questo da\nparte mia!",
  ["_CeladonMartRoofSuperNerdText"] = "Mia sorella é\nun'allenatrice ci\vcredi o no. Ma é\ncosi' immatura\vche mi fa\nimpazzire!",
  ["_CeladonPokecenterBeautyText"] = "Ho pedalato in\nsalita sulla\vPISTA CICLABILE da\nFUCSIAPOLI!",
  ["_CeladonPokecenterGentlemanText"] = "Il FLAUTO POKé\nsveglia i POKéMON\vcon un suono che\nsentono solo\vloro!",
  ["_CeruleanBadgeHouseBoulderBadgeText"] = "L'ATTACCO di tutti\ni POKéMON aumenta\vun pochino.\nPermette anche di\vusare FLASH ogni\nvolta che lo\vdesideri.",
  ["_CeruleanBadgeHouseCascadeBadgeText"] = "I POKéMON fino al\nLv. 30\vubbidiranno. Piu'\nalti,\vdiventeranno\ninsoffrenti!\vPermette anche di\nusare TAGLIO\vfuori dallotta.",
  ["_CeruleanBadgeHouseEarthBadgeText"] = "Tutti i POKéMON ti\nubbidiranno!",
  ["_CeruleanBadgeHouseMarshBadgeText"] = "I POKéMON fino al\nLv. 70\vubbidiranno. Piu'\nalti,\vdiventeranno\ninsoffrenti!",
  ["_CeruleanBadgeHouseMiddleAgedManText"] = "Le MEDAGLIE\nPOKéMON sono\vpossedute solo da\nesperti. Vedo che\vne hai almeno una.\nQuelle medaglie\vhanno segreti\nincredibili!",
  ["_CeruleanBadgeHouseMiddleAgedManVisitAnyTimeText"] = "Vieni a trovarmi\nquando vuoi.",
  ["_CeruleanBadgeHouseMiddleAgedManWhichBadgeText"] = "Dunque... Quale\ndelle 8 medaglie\vdevo descrivere?",
  ["_CeruleanBadgeHouseRainbowBadgeText"] = "I POKéMON fino al\nLv. 50\vubbidiranno. Piu'\nalti,\vdiventeranno\ninsoffrenti!\vPermette anche di\nusare FORZA fuori\vdalla lotta.",
  ["_CeruleanBadgeHouseSoulBadgeText"] = "La DIFESA di tutti\ni POKéMON aumenta\vun pochino.\nPermette anche di\vusare SURF fuori\ndalla lotta.",
  ["_CeruleanBadgeHouseThunderBadgeText"] = "La VELOCITA' di\ntutti i POKéMON\vaumenta un\npochino. Permette\vanche di usare\nVOLO fuori dalla\vlotta.",
  ["_CeruleanBadgeHouseVolcanoBadgeText"] = "Le abilita'\nSPECIALI dei tuoi\vPOKéMON aumentano\nun po'.",
  ["_CeruleanCityBikeShopSign"] = "Erba e grotte\naffrontate\vfacili! NEGOZIO\nBICI",
  ["_CeruleanCityCooltrainerF1SlowbroPunchText"] = "Pugno SLOWBRO! No!\nHai sbagliato di\vnuovo!",
  ["_CeruleanCityCooltrainerF1SlowbroUseSonicboomText"] = "Ok! SLOWBRO! Usa\nSONICBOOM! Forza,\vSLOWBRO presta\nattenzione!",
  ["_CeruleanCityCooltrainerF1SlowbroWithdrawText"] = "SLOWBRO, RITIRATA!\nNo! é sbagliato!\vé cosi' difficile\ncontrollare i\vPOKéMON!\nL'ubbidienza\vdipende 膵dalle tue\nabilita' di\vallenatore!",
  ["_CeruleanCityCooltrainerF2Text"] = "Voglio una\nBICICLETTA rosso\vfuoco! La terro'\nin casa cosi' non\vsi sporca!",
  ["_CeruleanCityCooltrainerMText"] = "Sei un allenatore\nanche tu?\vCollezionare e\nlottare é dura.",
  ["_CeruleanCityGuardText"] = "La gente qui é\nstata rapinata. é\vovvio che il TEAM\nROCKET é dietro\vquesto efferato\ncrimine! Anche la\vPOLIZIA ha\nproblemi con i\vROCKET!",
  ["_CeruleanCityGymSign"] = "PALESTRA POKéMON\nDI CELESTOPOLI\vCAPOPALESTRA:\nMISTY La\vSirenetta\nmaschiaccio",
  ["_CeruleanCityRivalDefeatedText"] = "Ehi!\nCalma! Hai gia'\vvinto!",
  ["_CeruleanCityRivalIWentToBillsText"] = "{RIVAL}: Ehi,\nsapevi? Sono\vandato da BILL e\nmi ha fatto\vvedere i suoi rari\nPOKéMON! Ha\vaggiunto molte\npagine al mio\vPOKéDEX!\nD'altronde, BILL\vé famoso nel mondo\ncome POKéMANIAC!\vHa inventato il\nSistema Memoria\vPOKéMON su PC!\nVisto che usi il\vsuo sistema,\nringrazialo! Beh,\vdevo filare! Ci\nbecchiamo!",
  ["_CeruleanCityRivalPreBattleText"] = "{RIVAL}: Ehi!\n{PLAYER}! Te la\vstrascichi ancora\nqui dietro? Io me\vla cavo alla\ngrande! Ho\vcatturato un bel\npo' di POKéMON\vforti e\nintelligenti!\vEcco, fammi vedere\ncosa hai\vcatturato,\n{PLAYER}!",
  ["_CeruleanCityRivalVictoryText"] = "Heh! Non\nsei alla altezza\vdel mio genio!",
  ["_CeruleanCityRocketIBetterGetMovingText"] = "Devo proprio\nmuovermi! Ciao!",
  ["_CeruleanCityRocketIGiveUpText"] = "Fermati! Mi\narrendo! Me ne\vvado quatto\nquatto!",
  ["_CeruleanCityRocketIllReturnTheTMText"] = "Ok! Resituiro' la\nMT che ho rubato!",
  ["_CeruleanCityRocketReceivedTM28Text"] = "{PLAYER} ha\nrecuperato la\vMT28!",
  ["_CeruleanCityRocketTM28NoRoomText"] = "Fai spazio per\nquesto! Non posso\vmuovermi finché\nnon te la do!",
  ["_CeruleanCityRocketText"] = "Ehi! Fuori! Não é\nil tuo cortile!\vEh? Io? Sono un\ninnocente\vpassante! Non mi\ncredi?",
  ["_CeruleanCitySignText"] = "CELESTOPOLI\nUn'aura blu e\vmisteriosa la\ncirconda",
  ["_CeruleanCitySlowbroIgnoredOrdersText"] = "SLOWBRO ha\nignorato gli\vordini...",
  ["_CeruleanCitySlowbroIsLoafingAroundText"] = "SLOWBRO ciondola\nin giro...",
  ["_CeruleanCitySlowbroTookASnoozeText"] = "SLOWBRO si é fatto\nun sonnellino...",
  ["_CeruleanCitySlowbroTurnedAwayText"] = "SLOWBRO si é\ngirato dall'altra\vparte...",
  ["_CeruleanCitySuperNerd1Text"] = "Quel cespuglio\ndavanti al\vnegozio é\nd'intralcio.\vForse c'é una via\nalternativa.",
  ["_CeruleanCitySuperNerd2Text"] = "Stai facendo un\nenciclopedia sui\vPOKéMON?\nInteressante.",
  ["_CeruleanCitySuperNerd3Text"] = "Questa é la GROTTA\nCELESTE! Ci\vvivono POKéMON\nfortissimi! Solo\vil campione della\nLEGA POKéMON puo'\ventrare!",
  ["_CeruleanCityTrainerTipsText"] = "CONSIGLI UTILI\nPremere il\vpulsante B durante\nl'evoluzione\vannulla l'intero\nprocesso.",
  ["_CeruleanGymAfterBattleText1"] = "Devi\naffrontare altri\vallenatori per\nscoprire quanto\vvali davvero.",
  ["_CeruleanGymAfterBattleText2"] = "MISTY\ncontinuera' a\vmigliorare! Non\nperdera' con uno\vcome te!",
  ["_CeruleanGymBattleText1"] = "Valgo\nmolto piu' di te!\vMISTY puo'\naspettare!",
  ["_CeruleanGymBattleText2"] = "Splash!\nSono il primo!\vFacciamolo!",
  ["_CeruleanGymEndBattleText1"] = "Mi hai\nsopraffatto!",
  ["_CeruleanGymEndBattleText2"] = "Non puo'\nessere!",
  ["_CeruleanGymGymGuideBeatMistyText"] = "Hai\nbattuto MISTY!\vChe ti avevo\ndetto? Io e te,\vragazzo, siamo una\nbella squadra!",
  ["_CeruleanGymGymGuideChampInMakingText"] = "Ehi!\nFuturo campione!\vEcco il mio\nconsiglio! La\vCAPOPALESTRA MISTY\né un asso dei\vPOKéMON Acqua!\nPuoi prosciugarli\vcon i POKéMON\nPianta! O\vfulminarli con\nl'elettricita'!",
  ["_CeruleanGymMistyCascadeBadgeInfoText"] = "La\nMEDAGLIA CASCATA\vfa ubbidire i\nPOKéMON fino al\vLv. 30! Inclusi\nquelli scambiati!\vC'é di piu': ora\npuoi usare\vTAGLIO! Puoi\ntagliare i\vpiccoli cespugli\nper aprire vie!\vPrendi anche la mi\nMT preferita!",
  ["_CeruleanGymMistyPreBattleText"] = "Ciao, sei\nuna faccia nuova!\vGli allenatori che\nvogliono\vdiventare pro\ndevono avere una\vpolitica sui\nPOKéMON! Qual é\vil tuo approccio\nquando catturi i\vPOKéMON? La mia\npolitica é\vun'offensiva\ntotale con\vPOKéMON Acqua!",
  ["_CeruleanGymMistyReceivedCascadeBadgeText"] = "\nAcciderboli! Ci\vsai fare! Va bene!\nPrendi la\vMEDAGLIA CASCATA.\nper dimostrare\vche mi hai\nbattuta!",
  ["_CeruleanGymMistyReceivedTM11Text"] = "{PLAYER}\nha ricevuto la\vMT11!",
  ["_CeruleanGymMistyTM11ExplanationText"] = "La MT11\ninsegna\vBOLLARAGGIO! Usala\nsu un POKéMON\vacquatico!",
  ["_CeruleanGymMistyTM11NoRoomText"] = "Faresti\nmeglio a fare\vspazio!",
  ["_CeruleanMartCooltrainerFText"] = "Hai visto qualche\nCARAM. RARA?\vDovrebbe far\nsalire i POKéMON\vdi un livello!",
  ["_CeruleanMartCooltrainerMText"] = "Usa REPELLENTE per\ntenere insetti e\vPOKéM. deboli alla\nlarga. Metti il\vtuo POKéMON piu'\nforte in cima\valla lista per\nrisultati\vottimali!",
  ["_CeruleanPokecenterGentlemanText"] = "Hai sentito\nparlare di BILL?\vTutti lo chiamano\nPOKéMANIAC! Penso\vche la gente sia\nsolo gelosa di\vBILL. Chi non\nvorrebbe vantarsi\vdei propri\nPOKéMON?",
  ["_CeruleanPokecenterGuyText"] = "BILL ha un sacco\ndi POKéMON!\vColleziona anche\nquelli rari!",
  ["_CeruleanPokecenterSuperNerdText"] = "Quel BILL! Ho\nsentito che fara'\vdi tutto per avere\nPOKéMON rari!",
  ["_CeruleanTradeHouseGrannyText"] = "A mio marito\npiacciono\vscambiare POKéMON.\nSe sei un\vcollezionista, ti\nandrebbe di\vscambiare con lui?",
  ["_CeruleanTrashedHouseFishingGuruTheyStoleATMText"] = "Miserabili ROCKET!\nGuarda che cosa\vhanno combinato!\nHanno rubato una\vMT per insegnare a\nscavare a un\vPOKéMON! Mi é\ncostata un occhio\vdella testa!",
  ["_CeruleanTrashedHouseFishingGuruWhatsLostIsLostText"] = "Quel che é perso,\né perso! Ho\vdeciso di\ninsegnare a\vDIGLETT a scavare\nsenza MT!",
  ["_CeruleanTrashedHouseGirlText"] = "Il TEAM ROCKET\nstara' cercando\vdi scavarsi un\nvarco!",
  ["_CeruleanTrashedHouseWallHoleText"] = "Il TEAM ROCKET ha\nlasciato una via\vd'uscita!",
  ["_ChampionsRoomOakComeWithMeText"] = "OAK: {PLAYER}!\nCapisci che la\vtua vittoria non é\ndovuta solo a te!\vIl legame con i\ntuo POKéMON é\vmeraviglioso!\n{PLAYER}! Vieni\vcon me!",
  ["_ChampionsRoomOakCongratulatesPlayerText"] = "OAK: Hai vinto!\nComplimenti! Sei\vil nuovo campione\ndella LEGA\vPOKéMON! Sei\ncresciuto molto\vda quando sei\npartito con\v{RAM:wNameBuffer}!\n{PLAYER}, sei\vdiventato grande!",
  ["_ChampionsRoomOakDisappointedWithRivalText"] = "OAK: {RIVAL}! Sono\ndeluso! Sono\vvenuto quando ho\nsaputo che avevi\vbattuto i\nSUPERQUATTRO! Ma\vquando sono\narrivato, avevi\vgia' perso!\n{RIVAL}! Capisci\vperché hai perso?\nHai dimenticato\vdi tratte i tuoi\nPOKéMON con amore\ve fiducia! Senza\ndi essi, non\vdiventerai mai un\ncampione!",
  ["_ChampionsRoomOakText"] = "OAK: {PLAYER}!",
  ["_ChampionsRoomRivalAfterBattleText"] = "Perché?\nPerché ho perso?\vNon ho mai\ncommesso errori\vcrescendo i miei\nPOKéMON...\vDannazione! Sei tu\nil nuovo campione\vdella LEGA\nPOKéMON! Anche se\vfaccio fatica ad\nammetterlo.",
  ["_ChampionsRoomRivalIntroText"] = "{RIVAL}: Ehi! Non\nvedevo l'ora di\vvederti, {PLAYER}!\nIl mio rivale\vdeve essere forte!\nMentre completavo\vil POKéDEX, ho\ncercato ovunque\vPOKéMON forti! Non\nsolo, ho creato\vsquadre in grado\ndi battere ogni\vtipo! Ed ora! Sono\nil campione della\vLEGA POKéMON!\n{PLAYER}! Sai cosa\vsignifica? Te lo\ndico io! Sono\vl'allenatore piu'\nforte del mondo!",
  ["_ChargeMoveEffectText"] = "{USER}",
  ["_ChooseABoxText"] = "Scegli un BOX\nPOKéMON.",
  ["_CinnabarGymBlainePostBattleAdviceText"] = "FUOCOBOMBA é\nl'ultima tecnica\vdi fuoco! Non\nsprecarla sui\vPOKéMON Acqua!",
  ["_CinnabarGymBlainePreBattleText"] = "Ah! Sono BLAINE!\nSono il\vCAPOPALESTRA di\nISOLA CANNELLA! I\vmiei POKéMON di\nfuoco\vinceneriranno gli\nsfidanti! Ha!\vFaresti meglio\navere\vANTISCOTTATURA!",
  ["_CinnabarGymBlaineReceivedTM38Text"] = "{PLAYER} ha\nricevuto\v{RAM:wStringBuffer}!",
  ["_CinnabarGymBlaineReceivedVolcanoBadgeText"] = "Sono esaurito! Hai\nconquistato la\vMEDAGLIA VULCANO!",
  ["_CinnabarGymBlaineTM38ExplanationText"] = "La MT38 contiene\nFUOCOBOMBA!\vInsegnala ai\nPOKéMON di tipo\vFuoco! CHARMELEON\no PONYTA sono\vottime scelte!",
  ["_CinnabarGymBlaineTM38NoRoomText"] = "Fai spazio per il\nmio regalo!",
  ["_CinnabarGymBlaineVolcanoBadgeInfoText"] = "Ah! La MEDAGLIA\nVULCANO accresce\vle abilita'\nSPECIALI dei\vPOKéMON! Tieni,\npuoi avere anche\vquesto!",
  ["_CinnabarGymGymGuideBeatBlaineText"] = "{PLAYER}! Hai\nbattuto quel\vtestardo!",
  ["_CinnabarGymGymGuideChampInMakingText"] = "Ehi! Futuro\ncampione!\vL'irascibile\nBLAINE é un\vesperto di POKéM.\nFuoco! Spenta il\vsuo spirito con\nl'acqua! Meglio\vprendere delle\nANTISCOTTATURA!",
  ["_CinnabarGymQuizCorrectText"] = "Risposta esatta!\nAvanti, passa\vpure!",
  ["_CinnabarGymQuizIncorrectText"] = "Spiacente!\nSbagliato!",
  ["_CinnabarGymQuizIntroText"] = "Quiz sui POKéMON!\nRispondi bene e\vla porta si\naprira'! Sbaglia\ve dovrai\naffrontare un\vallenatore! Se\nvuoi conservare i\vtuoi POKéMON per\nil\vCAPOPALESTRA...\nRispondi bene! Si\vcomincia!",
  ["_CinnabarGymSuperNerd1AfterBattleText"] = "Il fuoco, o per\nessere precisi,\vla combustione...\nBlah, blah, blah,\vblah...",
  ["_CinnabarGymSuperNerd1BattleText"] = "Sai quanto puo'\nscaldarsi il\vfuoco di un\nPOKéMON?",
  ["_CinnabarGymSuperNerd1EndBattleText"] = "Urca!\nChe calore!",
  ["_CinnabarGymSuperNerd2AfterBattleText"] = "Non riesco a fare\na meno di rubare\vi POKéMON altrui!",
  ["_CinnabarGymSuperNerd2BattleText"] = "Ero un ladro, ma\nho messo la testa\va posto come\nallenatore!",
  ["_CinnabarGymSuperNerd2EndBattleText"] = "Mi\narrendo!",
  ["_CinnabarGymSuperNerd3AfterBattleText"] = "Le mie teorie sono\ntroppo complesse\vper te!",
  ["_CinnabarGymSuperNerd3BattleText"] = "Non puoi vincere!\nHo studiato i\vPOKéMON a fondo!",
  ["_CinnabarGymSuperNerd3EndBattleText"] = "Waaa! I\nmiei studi!",
  ["_CinnabarGymSuperNerd4AfterBattleText"] = "Vorrei tanto che\nesistesse un\vPOKéMON ladro! Lo\nuserei!",
  ["_CinnabarGymSuperNerd4BattleText"] = "Adoro usare i\nPOKéMON di fuoco!",
  ["_CinnabarGymSuperNerd4EndBattleText"] = "Troppo\ncaldo da gestire!",
  ["_CinnabarGymSuperNerd5AfterBattleText"] = "BLAINE si era\nperso tra i monti\vquando apparve un\nPOKéMON volatile\vinfuocato. La sua\nluce aiuto'\vBLAINE a trovare\nla via d'uscita!",
  ["_CinnabarGymSuperNerd5BattleText"] = "So perché BLAINE é\ndiventato\vallenatore!",
  ["_CinnabarGymSuperNerd5EndBattleText"] = "Ahi!",
  ["_CinnabarGymSuperNerd6AfterBattleText"] = "A noi fan dei\nPOKéM. Fuoco\vpiacciono PONYTA e\nNINETALES!",
  ["_CinnabarGymSuperNerd6BattleText"] = "Sono stato in\nmolte PALESTRE,\vma questa é la mia\npreferita!",
  ["_CinnabarGymSuperNerd6EndBattleText"] = "Urca!\nTroppo caldo!",
  ["_CinnabarGymSuperNerd7AfterBattleText"] = "L'acqua batte il\nfuoco! Ma il\vfuoco scioglie il\nghiaccio!",
  ["_CinnabarGymSuperNerd7BattleText"] = "Il fuoco é debole\ncontro l'H2O!",
  ["_CinnabarGymSuperNerd7EndBattleText"] = "Oh!\nFiamma spenta!",
  ["_CinnabarIslandDoorIsLockedText"] = "La porta é chiusa\na chiave...",
  ["_CinnabarIslandGamblerText"] = "Gli scienziati\nfanno esperimenti\vnell'edificio\nbruciato.",
  ["_CinnabarIslandGirlText"] = "BLAINE della PAL.\ndi ISOLA CANNELLA\vé un tipo strano\nche vive qui da\vdecenni.",
  ["_CinnabarIslandGymSignText"] = "PALESTRA POKéMON\nDELL' ISOLA\vCANNELLA\nCAPOPALESTRA:\vBLAINE Il maestro\ndel fuoco focoso!",
  ["_CinnabarIslandPokemonLabSignText"] = "LABORATORIO\nPOKéMON",
  ["_CinnabarIslandSignText"] = "ISOLA CANNELLA La\ncitta' ardente di\vpassione",
  ["_CinnabarLabFishingGuruText"] = "Qui studiamo a\nfondo i POKéMON.\vSpesso ci portano\nrari esemplari da\vesaminare.",
  ["_CinnabarLabFossilRoomScientist1ComeAgainText"] = "Aiyah! Sei\ntornato!",
  ["_CinnabarLabFossilRoomScientist1FossilIsBackToLifeText"] = "Dov'eri? Il tuo\nfossile é tornato\vin vita! Era\n{RAM:wStringBuffer} come\vpensavo!",
  ["_CinnabarLabFossilRoomScientist1GoForAWalkText"] = "Ci metto un po'!\nFatti una\vpasseggiata per un\npo'!",
  ["_CinnabarLabFossilRoomScientist1GoForAWalkText2"] = "Ci metto un po'!\nFatti una\vpasseggiata per un\npo'!",
  ["_CinnabarLabFossilRoomScientist1NoFossilsText"] = "No! Che peccato!",
  ["_CinnabarLabFossilRoomScientist1SeesFossilText"] = "Oh! Quello é\n{RAM:wNameBuffer}! é il\vfossile di\n{RAM:wStringBuffer}, un\vPOKéMON estinto!\nLa mia Macchina\vdella Resurrezione\nlo fara'\vrivivere!",
  ["_CinnabarLabFossilRoomScientist1TakesFossilText"] = "Allora sbrigati a\ndarmelo! {PLAYER}\vha consegnato\n{RAM:wNameBuffer}!",
