  ["_CinnabarLabMetronomeRoomAmberPipeText"] = "Un tubo d'ambra!",
  ["_CinnabarLabMetronomeRoomPCText"] = "C'é un messaggio\ne-mail! ... I 3\vuccelli POKéM.\nleggendari sono\vARTICUNO, ZAPDOS e\nMOLTRES. La loro\vposizione é\nsconosciuta.\vEsploreremo la\ngrotta vicina a\vCELESTOPOLI. Da:\nTEAM RICERCA\vPOKéMON ...",
  ["_CinnabarLabMetronomeRoomScientist1ReceivedTM35Text"] = "{PLAYER} ha\nricevuto\v{RAM:wStringBuffer}!",
  ["_CinnabarLabMetronomeRoomScientist1TM35ExplanationText"] = "Tch-tch-tch! é il\nsuono del\vMETRONOMO!\nStuzzica il\vcervello del\nPOKéMON\vfacendogli usare\nmosse che non\vconosce!",
  ["_CinnabarLabMetronomeRoomScientist1TM35NoRoomText"] = "Lo zaino é pieno\nzeppo!",
  ["_CinnabarLabMetronomeRoomScientist1Text"] = "Tch-tch-tch! Ho\ncreato una MT\vfiga! Puo'\nscatenare ogni\vgenere di\ndivertimento!",
  ["_CinnabarLabMetronomeRoomScientist2Text"] = "EEVEE puo'\nevolversi in 1 di\v3 specie di\nPOKéMON.",
  ["_CinnabarLabPhotoText"] = "Una foto del\nfondatore del\vLAB., DR. FUJI!",
  ["_CinnabarLabRAndDSignText"] = "LABORATORIO\nPOKéMON Sala\vRicerca e Sviluppo",
  ["_CinnabarLabTestingRoomSignText"] = "LABORATORIO\nPOKéMON Sala Test",
  ["_CinnabarLabTradeRoomSuperNerdText"] = "Ho trovato questo\nstrano fossile\vsul MONTE LUNA!\nPenso sia un raro\vPOKéMON\npreistorico!",
