  ["_CinnabarPokecenterGentlemanText"] = "Hai amici? I\nPOKéMON ricevuti\vnegli scambi\ncrescono molto in\vfretta. Penso ne\nvalga la pena!",
  ["_CinnabarPokecenterGuyText"] = "I POKéMON possono\nancora imparare\vtecniche dopo aver\nannullato\vl'evoluzione.\nL'evoluzione puo'\vattendere nuove\nmosse.",
