  ["_CopycatsHouse1FMiddleAgedWomanText"] = "Mia figlia é cosi'\negotica. Ha solo\vpochi amici.",
  ["_CopycatsHouse2FCopycatDoYouLikePokemonText"] = "{PLAYER}: Ciao! Ti\npiacciono i\vPOKéMON? {PLAYER}:\nAh no, te l'ho\vappena chiesto.\n{PLAYER}: Eh? Sei\vstrana! MIMICA:\nMm? Smettere di\vimitare? Ma é il\nmio hobby\vpreferito!",
