  ["_CopycatsHouse2FCopycatTM31Explanation1Text"] = "La MT31 contiene\nla mia preferita,\vMIMICA! Usala su\nun buon POKéMON!",
  ["_CopycatsHouse2FCopycatTM31Explanation2Text"] = "{PLAYER}: Ciao!\nGrazie per la\vMT31! {PLAYER}:\nCome? {PLAYER}: é\vcosi' divertente\nimitare ogni mia\vmossa? MIMICA:\nGia'! é uno\vspasso!",
