  ["_FuchsiaBillsGrandpasHouseBillsGrandpaText"] = "Mh? Hai incontrato\nBILL? é mio\vnipote! Gli é\nsempre piaciuto\vcollezionare cose\nfin da piccolo!",
  ["_FuchsiaBillsGrandpasHouseMiddleAgedWomanText"] = "Il GUARDIANO é\nvecchio,\vma\arzillo! Ha\ntutti i denti\vfinti pero'.",
  ["_FuchsiaBillsGrandpasHouseYoungsterText"] = "BILL archivia i\nsuoi dati POKéMON\vsul suo PC! Te li\nha mostrati?",
  ["_FuchsiaCityChanseySignText"] = "Nome: CHANSEY\nCatturarne uno é\vsolo questione di\nfortuna.",
  ["_FuchsiaCityErikText"] = "ERIK: Dov'é SARA?\nHo detto che\vl'avrei incontrata\nqui.",
  ["_FuchsiaCityFossilSignKabutoText"] = "Nome: KABUTO Un\nPOKéMON\vresuscitato da un\nfossile.",
  ["_FuchsiaCityFossilSignOmanyteText"] = "Nome: OMANYTE Un\nPOKéMON\vresuscitato da un\nfossile.",
  ["_FuchsiaCityFossilSignUndeterminedText"] = "...",
  ["_FuchsiaCityGamblerText"] = "La ZONA SAFARI ha\nuno zoo\vall'ingresso. Sul\nretro c'é il\vGIOCO SAFARI per\ncatturare\vPOKéMON.",
  ["_FuchsiaCityGymSignText"] = "PALESTRA POKéMON\nDI FUCSIAPOLI\vCAPOPALESTRA: KOGA\nIl maestro dei\vPokémon velenosi!",
  ["_FuchsiaCityKangaskhanSignText"] = "Nome: KANGASKHAN\nUn POKéMON\vmaterno che alleva\ni piccoli nel\vmarsupio sul\nventre.",
  ["_FuchsiaCityLaprasSignText"] = "Nome: LAPRAS Il re\ndei mari.",
  ["_FuchsiaCityPokecenterGuyText"] = "Se studi i\nPOKéMON, visita\vla ZONA SAFARI. Ci\nsono ogni sorta\vdi POKéMON rari.",
  ["_FuchsiaCityPokemonText"] = "!",
  ["_FuchsiaCitySafariGameSignText"] = "GIOCO SAFARI\nCATTURA-POKéMON!",
  ["_FuchsiaCitySafariZoneSignText"] = "PARADISO POKéMON\nZONA SAFARI",
  ["_FuchsiaCitySignText"] = "FUCSIAPOLI Ecco il\nrosa passione!",
  ["_FuchsiaCitySlowpokeSignText"] = "Nome: SLOWPOKE\nAmichevole e\vmolto lento nei\nmovimenti.",
  ["_FuchsiaCityVoltorbSignText"] = "Nome: VOLTORB\nL'esatta immagine\vdi una POKé BALL.",
  ["_FuchsiaCityWardensHomeSignText"] = "ZONA SAFARI CASA\nDEL GUARDIA",
  ["_FuchsiaCityYoungster1Text"] = "Hai provato il\nGIOCO SAFARI?\vAlcuni POKéMON si\ntrovano solo li'.",
  ["_FuchsiaCityYoungster2Text"] = "Quella POKé BALL\nper terra é in\vrealta' un\nPOKéMON.",
  ["_FuchsiaGoodRodHouseFishingGuruHowAreTheFishText"] = "Salve, {PLAYER}!\nCome abboccano i\vpesci?",
  ["_FuchsiaGoodRodHouseFishingGuruNoRoomText"] = "Oh no! Non hai\nspazio per il mio\vregalo!",
  ["_FuchsiaGoodRodHouseFishingGuruReceivedGoodRodText"] = "Ottimo! Mi piace\nil tuo stile!\vPrendi questo e\npesca,\vgiovanotto!\n{PLAYER} ha\vricevuto un\n{RAM:wStringBuffer}!",
  ["_FuchsiaGoodRodHouseFishingGuruText"] = "Sono il fratello\nmaggiore del GURU\vPESCATORE! Adoro\nletteralmente\vpescare! Ti piace\npescare?",
  ["_FuchsiaGoodRodHouseFishingGuruThatsSoDisappointingText"] = "Oh... Che\ndelusione...",
  ["_FuchsiaGymGymGuideBeatKogaText"] = "é incredibile come\ni ninja\vterrorizzino\nancora oggi!",
  ["_FuchsiaGymGymGuideChampInMakingText"] = "Ehi! Futuro\ncampione! La\vPALESTRA DI\nFUCSIAPOLI é un\vlabirinto di muri\ninvisibili! KOGA\vsembra vicino, ma\né bloccato! Devi\vtrovare i varchi\nnei muri per\vraggiungerlo!",
  ["_FuchsiaGymKogaBeforeBattleText"] = "KOGA: Fwahahaha!\nUn semplice\vbambino come te\nosa sfidarmi?\vMolto bene, ti\nmostrero' il\vterrore di un\nmaestro ninja!\vProverai la\ndisperazione di\vveleno e sonno!",
  ["_FuchsiaGymKogaPostBattleAdviceText"] = "Se colpiti da\nTOSSINA, i\vPOKéMON soffrono\nsempre piu' con\vl'avanzare della\nlotta!\vTerrorizzera' di\ncerto i nemici!",
  ["_FuchsiaGymKogaReceivedSoulBadgeText"] = "Uhm! Hai\ndimostrato il tuo\vvalore! Tieni!\nPrendi la\vMEDAGLIA ANIMA!",
  ["_FuchsiaGymKogaReceivedTM06Text"] = "{PLAYER} ha\nricevuto\v{RAM:wStringBuffer}!",
  ["_FuchsiaGymKogaSoulBadgeInfoText"] = "Ora che possiedi\nla MEDAGLIA\vANIMA, la DIFESA\ndei tuoi POKéMON\vaumenta! Ti\npermette anche di\vusare SURF fuori\ndallotta! Ah,\vprendi anche\nquesto!",
  ["_FuchsiaGymKogaTM06ExplanationText"] = "La MT06 contiene\nTOSSINA! é una\vtecnica segreta\nvecchia di oltre\v400 anni!",
  ["_FuchsiaGymKogaTM06NoRoomText"] = "Fa' spazio per\nquesto, ragazzo!",
  ["_FuchsiaGymRocker1AfterBattleText"] = "Quindi unisci la\nforza\vall'ingegno? Buona\nstrategia!",
  ["_FuchsiaGymRocker1BattleText"] = "La forza non é il\nfattore chiave\vper i POKéMON! é\nla strategia! Ti\vmostrero' come\nbattere la forza\vbruta!",
  ["_FuchsiaGymRocker1EndBattleText"] = "Cosa?\nStraordinario!",
  ["_FuchsiaGymRocker2AfterBattleText"] = "Continuero' ad\nallenarmi sotto\vKOGA, il mio\nmaestro ninja!",
  ["_FuchsiaGymRocker2BattleText"] = "Volevo diventare\nun ninja, cosi'\vsono entrato in\nPALESTRA!",
  ["_FuchsiaGymRocker2EndBattleText"] = "Sono\nfritto!",
  ["_FuchsiaGymRocker3AfterBattleText"] = "Adoro veleno e\ntecniche di\vsonno, perché\npersistono dopo\vla lotta!",
  ["_FuchsiaGymRocker3BattleText"] = "Vediamo se batti\nle mie tecniche\vspeciali!",
  ["_FuchsiaGymRocker3EndBattleText"] = "Mi hai\ningannato!",
