  ["_FuchsiaGymRocker5AfterBattleText"] = "Ho ancora molto da\nimparare!",
  ["_FuchsiaGymRocker5BattleText"] = "Studio la via dei\nninja col maestro\vKOGA! I ninja\nusano gli animali\vda sempre!",
  ["_FuchsiaGymRocker5EndBattleText"] = "Awoo!",
  ["_FuchsiaGymRocker6AfterBattleText"] = "Dove c'é luce, c'é\nombra! Luce e\vombra! Quale\nscegli?",
