  ["_FuchsiaMartCooltrainerFText"] = "Hai provato\nVELOCITA' X?\vAccelera un\nPOKéMON in lotta!",
  ["_FuchsiaMartMiddleAgedManText"] = "Hai una bandiera\ndella ZONA\vSAFARI? E carte o\ncalendari?",
  ["_FuchsiaMeetingRoomSafariZoneWorker1"] = "Soprannominammo il\nGUARDIA SLOWPOKE.\vLui e il GUARDIA\nsembrano svagati!",
  ["_FuchsiaMeetingRoomSafariZoneWorker2"] = "Il GUARDIA sa\nmoltissimo sui\vPOKéMON! Ha\npersino fossili\vdi rari POKéMON\nestinti!",
  ["_FuchsiaMeetingRoomSafariZoneWorker3"] = "Il GUARDIA é\nentrato, ma non\vsi capiva. Credo\nabbia un problema\vdi parlato!",
  ["_FuchsiaPokecenterCooltrainerFText"] = "C'é uno stretto\nsentiero a ovest\vdi SMERALDOPOLI.\nPorta al quartier\vgenerale della\nLEGA. Il Q.G.\vgoverna tutti gli\nallenatori.",
  ["_FuchsiaPokecenterRockerText"] = "Non puoi vincere\ncon un solo\vPOKéMON forte. é\ndura, ma devi\vcrescerli in modo\nequilibrato.",
