  ["_GainedText"] = "{RAM:wNameBuffer} ha\nguadagnato",
  ["_GameCornerBeauty1Text"] = "Benvenuto! Puoi\nscambiare i\vgettoni per\nfavolosi premi\vnella porta\naccanto.",
  ["_GameCornerBeauty2Text"] = "Penso che queste\nmacchine abbiano\vprobabilita'\ndiverse.",
