  ["_GameCornerClerk1CoinCaseIsFullText"] = "Ops! Il\nSALVADANAIO é\vpieno.",
  ["_GameCornerClerk1DoYouNeedSomeGameCoinsText"] = "Benvenuto alla\nSALA GETTONI\vROCKET! Ti servono\ngettoni? Il costo\vé di ¥1000 per 50\ngettoni. Vuoi\vacquistarli?",
