  ["_HallOfFameOakText"] = "OAK: Ekhm!\nCongratulazioni\v{PLAYER}! Questo\npiano é la SALA\vD'ONORE POKéMON! I\ncampioni della\vLEGA POKéMON\nvengono onorati\vqui per le loro\nimprese! Anche i\vloro POKéMON sono\nregistrati nella\vSALA MAGNA!\n{PLAYER}! Hai\vlottato duro per\ndiventare il\vnuovo campione!\nCongratulazioni,\v{PLAYER}, tu e i\ntuoi POKéMON\ventrate nella\nSALA!",
