  ["_IndigoPlateauHQText"] = "Altopiano INDACO\nSEDE LEGA POKéMON",
  ["_IndigoPlateauLobbyCooltrainerFText"] = "Da qui in poi,\naffronterai i\vSUPER QUATTRO uno\na uno! Se vinci,\vsi apre la porta\nper il\vsuccessivo! Buona\nfortuna!",
  ["_IndigoPlateauLobbyGymGuideText"] = "Ehila'! Campione\nin erba! Alla\vLEGA POKéMON devi\naffrontare i\vSUPER QUATTRO. Se\nperdi, ricominci\vda capo! Ci siamo!\nDacci dentro!",
  ["_IndigoPlateauStatuesText1"] = "ALTOPIANO INDACO",
  ["_IndigoPlateauStatuesText2"] = "L'obiettivo degli\nallenatori! SEDE\vLEGA POKéMON",
