  ["_ItemWasStoredText"] = "{RAM:wNameBuffer} é stato\ndepositato via\vPC.",
  ["_ItemfinderFoundItemText"] = "Si'! Il\nCERCASTRUMENTI\vindica che c'é uno\nstrumento vicino.",
  ["_ItemfinderFoundNothingText"] = "No! Il\nCERCASTRUMENTI\vnon risponde.",
  ["_ItemsCantBeUsedHereText"] = "Non si possono\nusare strumenti\vqui.",
  ["_ItsABiteText"] = "Oh! Abboccano!",
  ["_JustAMomentText"] = "Un momento.",
  ["_KabutopsFossilText"] = "Fossile KABUTOPS\nUn POKéMON\vprimitivo e raro.",
  ["_KeptGoingAndCrashedText"] = "{USER}\ncontinua e si\vschianta!",
  ["_LancesRoomLanceAfterBattleText"] = "Non posso ancora\ncredere che i\vmiei draghi\nabbiano perso,\v{PLAYER}! Ora sei\ntu il campione\vdella LEGA\nPOKéMON! O\vmeglio, lo saresti\nse non avessi un\vultimo ostacolo.\nDevi affrontare\vun altro\nallenatore! Il\vsuo nome é...\n{RIVAL}! Ha\vbattuto i SUPER\nQUATTRO prima di\vte! é lui il vero\ncampione della\vLEGA POKéMON!",
  ["_LancesRoomLanceBeforeBattleText"] = "Ah! Ho sentito\nparlare di te! Io\vsono il capo dei\nSUPER QUATTRO! Mi\vchiamo LANCE e\naddestro draghi!\vSai che i draghi\nsono POKéMON\vmitologici! Sono\ndifficili da\vcatturare, ma la\nloro potenza é\vsuperiore! Sono\npraticamente\vindistruttibili!\nBene, pronto a\vperdere? La tua\nsfida finisce\vqui, {PLAYER}!",
  ["_LancesRoomLanceEndBattleText"] = "Basta! Odio\nammetterlo, ma\vsei un maestro di\nPOKéMON!",
  ["_LavenderCuboneHouseBrunetteGirlGhostIsGoneText"] = "Il FANTASMA della\nTORRE POKéMON é\vsparito! Qualcuno\ndeve aver placato\vla sua anima\nirrequieta!",
  ["_LavenderCuboneHouseBrunetteGirlPoorCubonesMotherText"] = "Odio quei orribili\nROCKET! La madre\vdi quel povero\nCUBONE... é stata\vuccisa cercando di\nfuggire dal TEAM!",
  ["_LavenderCuboneHouseCuboneText"] = "CUBONE: Kyarugoo!",
  ["_LavenderMartBaldingGuyText"] = "Cerco strumenti\nche aumentano le\vabilita' dei\nPOKéMON durante\vuna lotta. ATTACCO\nX, DIFESA X,\vVELOCITA' X e\nSPECIAL X. Sai\vdove trovarli?",
  ["_LavenderMartCooltrainerMNuggetText"] = "Ho trovato una\nPEPITA sui monti.\vPensavo fosse\ninutile, ma l'ho\vvenduta a ¥5000!",
  ["_LavenderMartCooltrainerMReviveText"] = "Conosci\nREVITALIZ.?\vRivitalizza\nqualsiasi POKéMON\vesausto!",
  ["_LavenderPokecenterGentlemanText"] = "Il TEAM ROCKET\nfarebbe di tutto\vper il denaro!",
  ["_LavenderPokecenterGuyText"] = "I CUBONE portano i\nteschi, vero? La\vgente li paga\nmolto!",
  ["_LavenderPokecenterLittleGirlText"] = "Ho visto la madre\ndi CUBONE morire\vsfuggendo al TEAM\nROCKET!",
  ["_LavenderTownCooltrainerMText"] = "Questa citta' é\nnota come il\vcimitero dei\nPOKéMON. Si\vtengono\ncommemorazioni\vnella TORRE.",
  ["_LavenderTownLittleGirlDoYouBelieveInGhostsText"] = "Credi nei\nFANTASMI?",
  ["_LavenderTownLittleGirlHaHaGuessNotText"] = "Ahahah, immagino\ndi no. Quella\vmano bianca sulla\ntua spalla, non é\vvera.",
  ["_LavenderTownLittleGirlSoThereAreBelieversText"] = "Davvero? Quindi ci\nsono credenti...",
  ["_LavenderTownPokemonHouseSignText"] = "CASA POKéMON\nVOLONTARI DI\vLAVANDONIA",
  ["_LavenderTownPokemonTowerSignText"] = "Che le anime dei\nPOKéMON riposino\vTORRE POKéMON",
  ["_LavenderTownSignText"] = "LAVANDONIA La\nnobile citta'\vviolacea",
  ["_LavenderTownSilphScopeSignText"] = "Nuovo\nSPETTROSONDA!\vRendi l'invisibile\nvisibile agli\vocchi! SILPH\nS.P.A.",
  ["_LavenderTownSuperNerdText"] = "I FANTASMI sono\napparsi nella\vTORRE. Credo siano\ngli spiriti dei\vPOKéMON uccisi dai\nROCKET.",
