  ["_LinkCableInfoText1"] = "Collegato un GAME\nBOY a un altro,\vparla con\nl'addetto a\vdestra in\nqualsiasi CENTRO\vPOKéMON.",
  ["_LinkCableInfoText2"] = "Il COLOSSEO ti\npermette di\vlottare contro un\namico.",
