  ["_LoafingAroundText"] = "{RAM:wBattleMonNick}\nbighellona.",
  ["_LoreleisRoomLoreleiAfterBattleText"] = "Sei meglio di\nquanto pensassi!\vAvanti! Hai solo\nassaggiato la\vpotenza della\nLEGA!",
  ["_LoreleisRoomLoreleiBeforeBattleText"] = "Benvenuto alla\nLEGA POKéMON! Io\vsono LORELEI dei\nSUPER QUATTRO!\vNessuno mi batte\ncon i POKéMON di\vghiaccio! Le mosse\ngelide sono\vpotenti! I tuoi\nPOKéMON saranno\valla mia\nmisericordia!\vAhahah! Sei\npronto?",
