  ["_MrFujisHouseLittleGirlThisIsMrFujisHouseText"] = "Questa é la casa\ndi MR. FUJI. é\vmolto gentile!\nCura i POKéMON\vabbandonati e\norfani!",
  ["_MrFujisHouseMrFujiHasMyFluteHelpedYouText"] = "MR. FUJI: Ti é\nutile il mio\vFLAUTO?",
  ["_MrFujisHouseMrFujiIThinkThisMayHelpYourQuestText"] = "MR. FUJI: {PLAYER}.\nLa tua ricerca\vdel POKéDEX\nfallira' senza\vamore per i\nPOKéMON. Penso\vche questo ti\naiutera'.",
  ["_MrFujisHouseMrFujiPokeFluteExplanationText"] = "Al suono del\nFLAUTO POKéMON,\vquelli\naddormentati si\vsveglieranno.\nFunziona con\vtutti i POKéMON\ndormienti.",
