  ["_MrPsychicsHouseMrPsychicYouWantedThisText"] = "...Aspetta! Non\ndire una parola!\vLo volevi!",
  ["_MtMoon1FBewareZubatSign"] = "Attenzione! ZUBAT\né un\vsucchiasangue!",
  ["_MtMoon1FCooltrainerF1AfterBattleText"] = "Come si esce da\nqui?",
  ["_MtMoon1FCooltrainerF1BattleText"] = "Wow! Qui dentro é\nmolto piu' grande\vdi quanto\ncredessi!",
  ["_MtMoon1FCooltrainerF1EndBattleText"] = "Oh!\nHo perso!",
  ["_MtMoon1FCooltrainerF2AfterBattleText"] = "Ho sentito che ci\nsono fossili\vmolto rari qui.",
  ["_MtMoon1FCooltrainerF2BattleText"] = "Cosa? Aspetto i\nmiei amici qui.",
  ["_MtMoon1FCooltrainerF2EndBattleText"] = "Ho\nperso?",
  ["_MtMoon1FHikerAfterBattleText"] = "I ragazzi come te\nnon dovrebbero\vstare qui!",
  ["_MtMoon1FHikerBattleText"] = "UAU! Mi hai\nspaventato! Ah,\vsei solo un\nragazzo!",
  ["_MtMoon1FHikerEndBattleText"] = "\nAcciderboli!\vSpaventato di\nnuovo!",
  ["_MtMoon1FSuperNerdAfterBattleText"] = "Devo trovare\nPOKéMON piu'\vforti.",
  ["_MtMoon1FSuperNerdBattleText"] = "Cosa! Non\nprendermi alle\vspalle!",
  ["_MtMoon1FSuperNerdEndBattleText"] = "Il mio\nPOKéMON non\vbasta!",
  ["_MtMoon1FYoungster1AfterBattleText"] = "Sono venuto qui\nper fare il bullo\vcon le ragazze.",
  ["_MtMoon1FYoungster1BattleText"] = "Sei venuto anche\ntu a esplorare?",
  ["_MtMoon1FYoungster1EndBattleText"] = "Perdere é\nuno schifo!",
  ["_MtMoon1FYoungster2AfterBattleText"] = "Li ho visti! Sono\nsicuro siano del\vTEAM ROCKET!",
  ["_MtMoon1FYoungster2BattleText"] = "Uomini sospetti\nnella grotta. E\vtu?",
  ["_MtMoon1FYoungster2EndBattleText"] = "Mi hai\npreso!",
  ["_MtMoon1FYoungster3AfterBattleText"] = "ZUBAT é tosto! Ma\npuo' essere utile\vse ne catturi uno.",
  ["_MtMoon1FYoungster3BattleText"] = "Attraversa la\ngrotta per\varrivare a\nCELESTOPOLI!",
  ["_MtMoon1FYoungster3EndBattleText"] = "Ho perso.",
  ["_MtMoonB2FDomeFossilYouWantText"] = "Vuoi il Fossile\nDome?",
  ["_MtMoonB2FHelixFossilYouWantText"] = "Vuoi il Fossile\nHelix?",
  ["_MtMoonB2FReceivedFossilText"] = "{PLAYER} ottiene\n{RAM:wStringBuffer}!",
  ["_MtMoonB2FRocket1AfterBattleText"] = "Mi hai fatto\narrabbiare! Il\vTEAM ti mettera'\nal bando!",
  ["_MtMoonB2FRocket1BattleText"] = "Il TEAM ROCKET\ntrovera' i\vfossili, li\nrivendera' per\vfare soldi!",
  ["_MtMoonB2FRocket1EndBattleText"] = "Argh! Ora\nsono furioso!",
  ["_MtMoonB2FRocket2AfterBattleText"] = "Mannaggia! I miei\nsoci non la\vpasseranno liscia!",
  ["_MtMoonB2FRocket2BattleText"] = "Noi del TEAM\nROCKET siamo\vgangster POKéMON!",
  ["_MtMoonB2FRocket2EndBattleText"] = "Ho\nrovinato tutto!",
  ["_MtMoonB2FRocket3AfterBattleText"] = "Se trovi un\nfossile, dammelo\ve sparisci!",
  ["_MtMoonB2FRocket3BattleText"] = "Facciamo un affare\ngrosso qui!\vSparisci,\nmoccioso!",
  ["_MtMoonB2FRocket3EndBattleText"] = "Vedo che\nsei bravo.",
  ["_MtMoonB2FRocket4AfterBattleText"] = "I POKéMON vivevano\nqui molto prima\vdell'uomo.",
  ["_MtMoonB2FRocket4BattleText"] = "I bambini non\ndovrebbero\vseccare gli\nadulti!",
  ["_MtMoonB2FRocket4EndBattleText"] = "Che\nrabbia!",
  ["_MtMoonB2FSuperNerdOkIllShareText"] = "Va bene! Lo\ndivideremo!",
  ["_MtMoonB2FSuperNerdThenThisIsMineText"] = "D'accordo. Allora\nquesto é mio!",
  ["_MtMoonB2FSuperNerdTheresAPokemonLabText"] = "Lontano, all'ISOLA\nCANNELLA, c'é un\vLABORATORIO\nPOKéMON. Studiano\vla rigenerazione\ndei fossili.",
  ["_MtMoonB2FSuperNerdTheyreBothMineText"] = "Ehi, ferma! Li ho\ntrovati io! Sono\ventrambi miei!",
  ["_MtMoonB2FYouHaveNoRoomText"] = "Senti, non hai\nspazio per\vquesto.",
  ["_MtMoonB2fSuperNerdEachTakeOneText"] = "Ne prendiamo uno a\ntesta! Niente\vingordigia!",
  ["_MtMoonPokecenterBenchGuyText"] = "Se hai troppi\nPOKéMON, puoi\vdepositarli al PC!",
  ["_MtMoonPokecenterGentlemanText"] = "Il TEAM ROCKET\nattacca i\vcittadini di\nCELESTOPOLI... Il\vTEAM ROCKET é\nsempre in prima\vpagina!",
  ["_MtMoonPokecenterMagikarpSalesmanIGotADealText"] = "UOMO: Salve! Ho un\naffare proprio\vper te! Ti do un\nmagnifico\vMAGIKARP per soli\n¥500! Che ne\vdici?",
  ["_MtMoonPokecenterMagikarpSalesmanNoMoneyText"] = "Ti servono piu'\nsoldi di cosi'!",
  ["_MtMoonPokecenterMagikarpSalesmanNoRefundsText"] = "UOMO: Be', io non\nfaccio rimborsi!",
  ["_MtMoonPokecenterMagikarpSalesmanNoText"] = "No? Lo faccio solo\ncome favore per\vte!",
  ["_MtMoonPokecenterYoungsterText"] = "Ho 6 POKé BALL\npronte alla\vcintura. Al\nmassimo puoi\vportare 6 POKéMON.",
  ["_MultiHitText"] = "Colpisce il nemico\n{NUM:wPlayerNumHits,\v1, 1} volte!",
  ["_Museum1FGamblerText"] = "Questo é un\nmagnifico\vfossile!",
  ["_Museum1FOldAmberText"] = "L'AMBRA é lucida e\ndorata!",
  ["_Museum1FScientist1AmberIsFossilizedTreeSapText"] = "L'AMBRA é linfa\nd'albero fossile.",
  ["_Museum1FScientist1ComeAgainText"] = "Torna presto!",
  ["_Museum1FScientist1DoYouKnowWhatAmberIsText"] = "Non puoi\nintrufolarti dal\vretro! Oh,\ninsomma! Sai\vcos'é l'AMBRA?",
  ["_Museum1FScientist1DontHaveEnoughMoneyText"] = "Non hai abbastanza\nsoldi.",
  ["_Museum1FScientist1GoToOtherSideText"] = "Prego, passa\ndall'altra parte!",
  ["_Museum1FScientist1TakePlentyOfTimeText"] = "Prenditi tutto il\ntempo per\vvederlo!",
  ["_Museum1FScientist1ThankYouText"] = "Ecco, ¥50! Grazie!",
  ["_Museum1FScientist1TheresALabSomewhereText"] = "C'é un laboratorio\nda qualche parte\vche cerca di\nresuscitare\vPOKéMON antichi\ndall'AMBRA.",
  ["_Museum1FScientist1WouldYouLikeToComeInText"] = "Il biglietto costa\n¥50 per i\vbambini. Vuoi\nentrare?",
  ["_Museum1FScientist2GetTheOldAmberCheckText"] = "Ssh! Fai\nanalizzare\vl'AMBRA ANTICA!",
  ["_Museum1FScientist2ReceivedOldAmberText"] = "{PLAYER} riceve\nAMBRA ANTICA!",
  ["_Museum1FScientist2TakeThisToAPokemonLabText"] = "Ssh! Credo che\nquesto pezzo di\vAMBRA contenga DNA\ndi POKéMON!\vSarebbe fantastico\nresuscitare un\vPOKéMON da esso!\nMa i miei\vcolleghi mi\nignorano! Percio'\vho un favore da\nchiederti:\vportalo a un\nLABORATORIO\vPOKéMON!",
  ["_Museum1FScientist2YouDontHaveSpaceText"] = "Non hai spazio per\nquesto!",
  ["_Museum1FScientist3Text"] = "Siamo fieri di due\nfossili di\vrarissimi POKéMON\npreistorici!",
  ["_Museum2FBrunetteGirlText"] = "Voglio un PIKACHU!\né cosi' carino!\vHo chiesto a papa'\ndi catturarmene\vuno!",
  ["_Museum2FGrampsText"] = "20 luglio 1969! Il\n1° allunaggio! Ho\vcomprato una\ntelevisione a\vcolori per\nvederlo!",
  ["_Museum2FHikerText"] = "Si', un PIKACHU\narrivera' presto!",
  ["_Museum2FMoonStoneSignText"] = "Meteorite caduto\nnel MONTE LUNA.\v(PIETRALUNARE?)",
  ["_Museum2FScientistText"] = "Abbiamo una mostra\nspaziale in\vcorso.",
  ["_Museum2FSpaceShuttleSignText"] = "NAVETTA SPAZIALE\nCOLUMBIA",
  ["_Museum2FYoungsterText"] = "PIETRALUNARE? Cosa\nc'é di cosi'\vspeciale?",
  ["_MustRechargeText"] = "{USER}\ndeve ricaricarsi!",
  ["_NameRatersHouseNameRaterATrulyImpeccableNameText"] = "{RAM:wNameBuffer}, eh? é\nun nome davvero\vimpeccabile! Abbi\ncura di\v{RAM:wNameBuffer}!",
  ["_NameRatersHouseNameRaterComeAnyTimeYouLikeText"] = "Va bene! Torna\nquando vuoi!",
  ["_NameRatersHouseNameRaterGiveItANiceNameText"] = "{RAM:wNameBuffer}, eh? é\nun soprannome\vdecente! Ma vuoi\nche gli dia un\vnome piu' carino?\nChe ne pensi?",
  ["_NameRatersHouseNameRaterPokemonHasBeenRenamedText"] = "Ok! Questo POKéMON\nora si chiama\v{RAM:wBuffer}! é un\nnome migliore di\vprima!",
  ["_NameRatersHouseNameRaterWantMeToRateText"] = "Salve, salve! Sono\nil GIUDICE\vONORARIO! Vuoi che\nvaluti i\vsoprannomi dei\ntuoi POKéMON?",
  ["_NameRatersHouseNameRaterWhatShouldWeNameItText"] = "Va bene! Come lo\nchiamiamo?",
  ["_NameRatersHouseNameRaterWhichPokemonText"] = "Quale POKéMON deve\nessere esaminato?",
  ["_NeedYourPokemonText"] = "Ok. Ci serve il\ntuo POKéMON.",
  ["_NewBadgeRequiredText"] = "No! Serve una\nnuova MEDAGLIA.",
  ["_NewBicycleText"] = "Una nuova e\nlucente\vBICICLETTA!",
  ["_NoCyclingAllowedHereText"] = "Qui non si puo'\nusare la bici.",
  ["_NoEffectText"] = "Non ha effetto!",
  ["_NoMonText"] = "Cosa? Non ci sono\nPOKéMON qui!",
  ["_NoMoreRoomForItemText"] = "Spazio esaurito\nper gli\vstrumenti!",
  ["_NoMovesLeftText"] = "{RAM:wBattleMonNick} non ha\npiu' mosse!",
  ["_NoNibbleText"] = "Neanche\nun'abboccata!",
  ["_NoRoomToStoreText"] = "Nessun spazio per\ndepositare\vstrumenti.",
  ["_NoRunningText"] = "No! Non si puo'\nfuggire da una\vlotta fra\nallenatori!",
  ["_NoSurfingHereText"] = "Non si puo' USARE\nSURF su\v{RAM:wNameBuffer} qui!",
  ["_NoTrade1Text"] = "Uffa! Vabbé...",
  ["_NoTrade2Text"] = "Be', se non lo\nvuoi tu...",
  ["_NoTrade3Text"] = "Che peccato.",
  ["_NoWillText"] = "Manca la voglia di\ncombattere!",
  ["_NotEnoughCoinsSlotMachineText"] = "Gettoni\ninsufficienti!",
  ["_NotHealthyEnoughText"] = "Non é abbastanza\nsalutare.",
  ["_NotThisTimeText"] = "Non questa volta!",
  ["_NotVeryEffectiveText"] = "Non é molto\nefficace...",
  ["_NothingHappenedText"] = "Non succede nulla!",
  ["_NothingHereText"] = "Sembra che non ci\nsia nulla.",
  ["_NothingStoredText"] = "Non c'é nulla\ndepositato.",
  ["_NothingToCutText"] = "Non c'é nulla da\nTAGLIARE!",
  ["_NothingToDepositText"] = "Non hai nulla da\ndepositare.",
  ["_OHKOText"] = "KO in un colpo!",
  ["_OKExclamationText"] = "OK!",
  ["_OakLabEmailText"] = "C'é un messaggio\ndi posta qui! ...\vChiamata a tutti\ngli allenatori di\vPOKéMON! I\nmigliori della\vLEGA POKéMON sono\npronti a sfidare\vchiunque! Porta i\ntuoi migliori\vPOKéMON e scopri\nil tuo livello!\vSEDE LEGA POKéMON\nALTOPIANO INDACO\vPS: PROF. OAK,\npassa a trovarci!\v...",
  ["_OakSpeechText1"] = "Salve! Benvenuto\nnel mondo dei\vPOKéMON! Mi chiamo\nOAK! Per tutti\vsono il PROF.\nPOKéMON!",
  ["_OakSpeechText2A"] = "Questo mondo é\ninabitato da\vcreature dette\nPOKéMON!",
  ["_OakSpeechText2B"] = "Per alcuni i\nPOKéMON sono\vanimali domestici.\nAltri li usano\vper lottare. Io...\nStudio i POKéMON\vcome professione.",
  ["_OakSpeechText3"] = "{PLAYER}! La tua\nleggenda sta per\viniziare! Un mondo\ndi sogni e\vavventure ti\nattende con i\vPOKéMON! Andiamo!",
  ["_OaksAideComeBackText"] = "Oh, capisco.\nQuando avrai\v{NUM:hOaksAideRequirement,\n1, 3} specie,\vtorna a prendere\n{RAM:wOaksAideRewardItemName}.",
  ["_OaksAideGotItemText"] = "{PLAYER} ottiene\n{RAM:wOaksAideRewardItemName}!",
  ["_OaksAideHereYouGoText"] = "Ottimo! Hai\ncatturato\v{NUM:hOaksAideNumMonsOwned,\n1, 3} specie di\vPOKéMON!\nComplimenti! Ecco\va te!",
  ["_OaksAideHiText"] = "Ciao! Ti ricordi\ndi me? Sono\vl'AIUTO del PROF.\nOAK! Se hai\vcatturato\n{NUM:hOaksAideRequirement,\v1, 3} specie di\nPOKéMON, dovrei\vdarti {RAM:wOaksAideRewardItemName}!\nAllora, {PLAYER}!\vHai catturato\nalmeno\v{NUM:hOaksAideRequirement,\n1, 3} specie?",
  ["_OaksAideNoRoomText"] = "Oh! Vedo che non\nhai alcuno spazio\vper {RAM:wOaksAideRewardItemName}.",
  ["_OaksAideUhOhText"] = "Vediamo... Oh no!\nHai catturato\vsolo\n{NUM:hOaksAideNumMonsOwned,\v1, 3} specie! Te\nne servono\v{NUM:hOaksAideRequirement,\n1, 3} per avere\v{RAM:wOaksAideRewardItemName}.",
  ["_OaksLabGirlText"] = "Il PROF. OAK é la\nmassima autorita'\vsui POKéMON! Molto\nallenatori lo\vstimano molto!",
  ["_OaksLabGivePokeballsExplanationText"] = "Quando appare un\nPOKéMON\vselvatico, é tutto\nvalido. Lancia\vuna POKé BALL e\nprova a\vcatturarlo! Non\nfunziona sempre,\vpero'. Un POKéMON\nin salute puo'\vfuggire. Ci vuole\nfortuna!",
  ["_OaksLabLastMonText"] = "Questo é l'ultimo\nPOKéMON di OAK!",
  ["_OaksLabMonEnergeticText"] = "Questo POKéMON é\ndavvero pieno di\venergia!",
  ["_OaksLabOak1ComeSeeMeSometimesText"] = "OAK: Vieni a\ntrovarmi a volte.\vVoglio sapere come\nprocede il tuo\vPOKéDEX.",
  ["_OaksLabOak1DeliverParcelText"] = "OAK: Oh, {PLAYER}!\nCome sta il mio\vvecchio POKéMON?\nBe', sembra\vproprio che ti\npiaccia. Devi\vavere un taleento\ncome allenatore!\vCosa? Hai qualcosa\nper me? {PLAYER}\vconsegna il PACCO\ndi OAK.",
  ["_OaksLabOak1HowIsYourPokedexComingText"] = "OAK: Che bello\nvederti! Come va\vil POKéDEX? Fammi\ndare un'occhiata!",
  ["_OaksLabOak1ParcelThanksText"] = "Ah! é la POKé BALL\npersonalizzata\vche ho ordinato!\nGrazie!",
  ["_OaksLabOak1PokemonAroundTheWorldText"] = "I POKéMON di tutto\nil mondo ti\vattendono,\n{PLAYER}!",
  ["_OaksLabOak1RaiseYourYoungPokemonText"] = "OAK: {PLAYER},\ncresci il tuo\vgiovane POKéMON\nfacendolo\vlottare!",
  ["_OaksLabOak1ReceivedPokeballsText"] = "OAK: Non puoi\navere dati\vdettagliati\nvedendoli e\vbasta. Devi\ncatturarli! Usa\vquesti per i\nPOKéMON\vselvatici. {PLAYER}\nriceve 5 POKé\vBALL!",
  ["_OaksLabOak1WhichPokemonDoYouWantText"] = "OAK: Dunque,\n{PLAYER}, quale\vPOKéMON vuoi?",
  ["_OaksLabOak1YourPokemonCanFightText"] = "OAK: Se appare un\nPOKéMON\vselvatico, il tuo\npuo' lottare\vcontro di esso!",
  ["_OaksLabOak2Text"] = "?",
  ["_OaksLabOakBePatientText"] = "OAK: Pazienza!\nAnche {RIVAL} ne\vavra' uno!",
  ["_OaksLabOakChooseMonText"] = "OAK: {RIVAL}?\nLasciami\vpensare... Ah, é\nvero, ti avevo\vdetto di venire!\nAspetta! Ecco,\v{PLAYER}! Ci sono 3\nPOKéMON! Haha!\vSono dentro le\nPOKé BALL. Ero un\vserio allenatore\nda giovane! Alla\vmia eta' me ne\nrestano 3, ma uno\vé tuo! Scegli!",
  ["_OaksLabOakDontGoAwayYetText"] = "OAK: Ehi! Non te\nne andare ancora!",
  ["_OaksLabOakGotPokedexText"] = "OAK: {PLAYER} e\n{RIVAL}! Prendete\vquesti! {PLAYER}\nriceve il POKéDEX\vda OAK!",
  ["_OaksLabOakIHaveARequestText"] = "OAK: Ah, giusto!\nHo una richiesta\vper voi due.",
  ["_OaksLabOakMyInventionPokedexText"] = "Sulla scrivania\nc'é la mia\vinvenzione, il\nPOKéDEX! Registra\vin automatico i\ndati dei POKéMON\vvisti o catturati!\né un'enciclopedia\vhi-tech!",
  ["_OaksLabOakThatWasMyDreamText"] = "Creare una guida\ncompleta di tutti\vi POKéMON...\nQuesto era il\vsogno mio! Ma sono\ntroppo vecchio!\vVoglio che voi due\nrealizziate il\vmio sogno! Forza,\nmuovetevi! Questa\vé una grande\nimpresa!",
  ["_OaksLabPokedexText"] = "é un'enciclopedia,\nma le pagine sono\vbianche!",
  ["_OaksLabReceivedMonText"] = "{PLAYER} riceve un\n{RAM:wNameBuffer}!",
  ["_OaksLabRivalAmIGreatOrWhatText"] = "{RIVAL}: Si'! Non\nsono fantastico?",
  ["_OaksLabRivalFedUpWithWaitingText"] = "{RIVAL}: Nonno!\nSono stufo di\vaspettare!",
  ["_OaksLabRivalGoAheadAndChooseText"] = "{RIVAL}: Heh, non\nho bisogno di\vfare l'avido come\nte! Scegli pure,\v{PLAYER}!",
  ["_OaksLabRivalGrampsIsntAroundText"] = "{RIVAL}: Ehi\n{PLAYER}! Il nonno\vnon c'é!",
  ["_OaksLabRivalGrampsText"] = "{RIVAL}: Nonno!",
  ["_OaksLabRivalIPickedTheWrongPokemonText"] = "COSA?\nIncredibile! Ho\vscelto il POKéMON\nsbagliato!",
  ["_OaksLabRivalIllTakeThisOneText"] = "{RIVAL}: Prendero'\nquesto, allora!",
  ["_OaksLabRivalIllTakeYouOnText"] = "{RIVAL}: Aspetta\n{PLAYER}! Vediamo\vi nostri POKéMON!\nForza, ti sfido!",
  ["_OaksLabRivalLeaveItAllToMeText"] = "{RIVAL}: D'accordo\nnonno! Faccio io!\v{PLAYER}, odio\ndirlo, ma non mi\vservi! Lo so!\nPrestero' una\vMAPPA CITTA' da\nmia sorella! Le\vdiro' di non\ndartela, {PLAYER}!\vAhahah!",
  ["_OaksLabRivalMyPokemonLooksStrongerText"] = "{RIVAL}: Il mio\nPOKéMON sembra\vmolto piu' forte.",
  ["_OaksLabRivalReceivedMonText"] = "{RIVAL} riceve un\n{RAM:wNameBuffer}!",
  ["_OaksLabRivalSmellYouLaterText"] = "{RIVAL}: Ok! Faro'\nlottare il mio\vPOKéMON per\nrinforzarlo!\v{PLAYER}! Nonno! A\npresto!",
  ["_OaksLabRivalWhatAboutMeText"] = "{RIVAL}: Ehi!\nNonno! E io?",
  ["_OaksLabRivalWhatDidYouCallMeForText"] = "{RIVAL}: Perché mi\nhai chiamato?",
  ["_OaksLabScientistText"] = "Studio i POKéMON\ncome aiuto del\vPROF. OAK.",
  ["_OaksLabThoseArePokeBallsText"] = "Quelle sono POKé\nBALL. Contengono\vPOKéMON!",
  ["_OaksLabYouWantBulbasaurText"] = "Dunque! Vuoi il\nPOKéMON pianta,\vBULBASAUR?",
  ["_OaksLabYouWantCharmanderText"] = "Dunque! Vuoi il\nPOKéMON fuoco,\vCHARMANDER?",
  ["_OaksLabYouWantSquirtleText"] = "Dunque! Vuoi il\nPOKéMON acqua,\vSQUIRTLE?",
  ["_OhFineThenText"] = "Oh, va bene.",
  ["_OlderFileWillBeErasedText"] = "Il vecchio file\nsara' cancellato\vper salvare. OK?",
  ["_OnceReleasedText"] = "Una volta\nliberato,\v{RAM:wStringBuffer} é perso\nper sempre. OK?",
  ["_OneMoreGoSlotMachineText"] = "Un altro giro?",
  ["_OneTwoAndText"] = "1, 2 e...",
  ["_OopsYouDontHaveEnoughRoomText"] = "Ops! Non hai\nabbastanza\vspazio.",
  ["_OutOfCoinsSlotMachineText"] = "Acciderboli!\nGettoni esauriti!",
  ["_OutOfSafariBallsText"] = "PA: Din-don! Le\nSAFARI BALL sono\vfinite!",
  ["_PPIncreasedText"] = "I PP di {RAM:wStringBuffer}\naumentano.",
  ["_PPMaxedOutText"] = "I PP di {RAM:wStringBuffer}\nsono al massimo.",
  ["_PPRestoredText"] = "I PP sono stati\nripristinati.",
  ["_PalletTownFisherText"] = "La tecnologia é\nincredibile! Ora\vpuoi archiviare e\nrichiamare\voggetti e POKéMON\ncome dati via PC!",
  ["_PalletTownGirlText"] = "Allevo anch'io i\nPOKéMON! Quando\vsaranno forti,\npotranno\vproteggermi!",
  ["_PalletTownOakHeyWaitDontGoOutText"] = "OAK: Ehi! Aspetta!\nNon uscire!",
  ["_PalletTownOakItsUnsafeText"] = "OAK: é pericoloso!\nI POKéMON\vselvatici vivono\nnell'erba! Ti\vserve un tuo\nPOKéMON per\vproteggerti. Lo\nso! Vieni con me!",
  ["_PalletTownOaksLabSignText"] = "LABORATORIO DI\nRICERCA POKéMON\vDI OAK",
  ["_PalletTownPlayersHouseSignText"] = "Casa di {PLAYER}",
  ["_PalletTownRivalsHouseSignText"] = "Casa di {RIVAL}",
  ["_PalletTownSignText"] = "BIANCAVILLA Le\nsfumature di un\vnuovo viaggio!",
  ["_ParalyzedMayNotAttackText"] = "{TARGET}\né paralizzato!\vPuo' non\nattaccare!",
  ["_ParlyzHealText"] = "La paralisi di\n{RAM:wNameBuffer}\vsvanisce!",
  ["_PartyMenuBattleText"] = "Quale POKéMON\nmandare in campo?",
  ["_PartyMenuItemUseText"] = "Usare lo strumento\nsu quale POKéMON?",
  ["_PartyMenuNormalText"] = "Scegli un POKéMON.",
  ["_PartyMenuSwapMonText"] = "Spostare il\nPOKéMON dove?",
  ["_PartyMenuUseTMText"] = "Usare la MT su\nquale POKéMON?",
  ["_PewterCityCooltrainerFText"] = "Si dice che i\nCLEFAIRY arrivino\vdalla luna! Sono\napparsi dopo che\vla PIETRALUNARE é\ncaduta sul monte.",
  ["_PewterCityCooltrainerMText"] = "Non ci sono molti\nallenatori seri\vqui! Sono un\nPIGLIAMOSCHE, ma\vBROCK di\nPLUMBEOPOLI é\vdavvero in gamba!",
  ["_PewterCityGymSignText"] = "PALESTRA POKéMON\nDI PLUMBEOLI\vCAPOPALESTRA:\nBROCK Il\vcapopalestra forte\ncome la roccia!",
  ["_PewterCityMuseumSignText"] = "MUSEO DELLA\nSCIENZA DI\vPLUMBEOPOLI",
  ["_PewterCityPokecenterGuyText"] = "Yawn! Quando\nJIGGLYPUFF canta,\vi POKéMON si\naddormentano...\v...Anche io...\nFiiu...",
  ["_PewterCityPoliceNoticeSignText"] = "AVVISO! Dei ladri\nrubano fossili\vPOKéMON al MONTE\nLUNA! Chiamate la\vpolizia per info!",
  ["_PewterCitySignText"] = "PLUMBEOPOLI La\ncitta' dal grigio\vroccioso",
  ["_PewterCitySuperNerd1DidYouCheckOutMuseumText"] = "Hai visitato il\nMUSEO?",
  ["_PewterCitySuperNerd1ItsRightHereText"] = "é proprio qui! Si\npaga per entrare,\vma ne vale la\npena! Ci vediamo!",
  ["_PewterCitySuperNerd1WerentThoseFossilsAmazingText"] = "Non erano\nfantastici i\vfossili del MONTE\nLUNA?",
  ["_PewterCitySuperNerd1YouHaveToGoText"] = "Davvero? Devi\nassolutamente\vandarci!",
  ["_PewterCitySuperNerd2DoYouKnowWhatImDoingText"] = "Psssst! Sai cosa\nsto facendo?",
  ["_PewterCitySuperNerd2ImSprayingRepelText"] = "Spruzzo REPELLENTE\nper tenere i\vPOKéMON lontani\ndal giardino!",
  ["_PewterCitySuperNerd2ThatsRightText"] = "Esatto! é un duro\nlavoro!",
  ["_PewterCityTrainerTipsText"] = "CONSIGLI UTILI\nOgni POKéMON che\vprende parte alla\nlotta guadagna\vESP!",
  ["_PewterCityYoungsterGoTakeOnBrockText"] = "Se hai stoffa, va'\na sfidare BROCK!",
  ["_PewterCityYoungsterYoureATrainerFollowMeText"] = "Sei un allenatore,\nvero? BROCK cerca\vnuovi sfidanti!\nSeguimi!",
  ["_PewterGymBrockBoulderBadgeInfoText"] = "Questa é una\nMEDAGLIA\vufficiale della\nLEGA POKéMON! I\vPOKéMON di chi la\npossiede sono\vpiu' forti! Ora\npuoi usare FLASH\vin ogni momento!",
  ["_PewterGymBrockPostBattleAdviceText"] = "Ci sono allenatori\ndi ogni tipo nel\vmondo! Sembri\nmolto dotato come\vallenatore\nPOKéMON! Vai alla\vPALESTRA di\nCELESTOPOLI a\vtestare le\nabilita'!",
  ["_PewterGymBrockPreBattleText"] = "Io sono BROCK!\nSono il\vCAPOPALESTRA di\nPLUMBEOPOLI!\vCredo in una\ndifesa di roccia\ve nella\ndeterminazione!\vPercio' i miei\nPOKéMON sono\vtutti di tipo\nroccia! Vuoi\vancora sfidarmi?\nBene! Mostrami il\vtuo meglio!",
  ["_PewterGymBrockReceivedBoulderBadgeText"] = "Ti ho\nsottovalutato.\vCome prova della\nvittoria, ecco la\vMEDAGLIA SASSO!\n{PLAYER} riceve la\vMEDAGLIA SASSO!",
  ["_PewterGymBrockWaitTakeThisText"] = "Aspetta! Prendi\nquesto con te!",
  ["_PewterGymCooltrainerMAfterBattleText"] = "Sei forte, ma non\nquanto BROCK!",
  ["_PewterGymCooltrainerMBattleText"] = "Fermati li',\nragazzino! Sei\vancora a anni luce\nda BROCK!",
  ["_MisReadPlaceholder"] = "",
  ["_PewterGymCooltrainerMEndBattleText"] = "\nMaledizione! Anni\vluce mi separano\nda BROCK!",
  ["_PewterGymGuideAdviceText"] = "Il 1° POKéMON in\ncampo é in cima\valla LISTA\nPOKéMON!\vCambiando l'ordine\ndei POKéMON, le\vlotte saranno piu'\nfacili!",
  ["_PewterGymGuideBeginAdviceText"] = "Bene! Diamo inizio\nallo spettacolo!",
  ["_PewterGymGuideFreeServiceText"] = "é un servizio\ngratuito! Diamo\vinizio alle danze!",
  ["_PewterGymGuidePostBattleText"] = "Proprio come\npensavo! Hai\vstoffa da\ncampione!",
  ["_PewterGymGuidePreAdviceText"] = "Ehila'! Si vede\nche hai la stoffa\vdel campione! Non\nsono un\vallenatore, ma so\ncome vincere! Ti\vportero' in alto!",
  ["_PewterGymReceivedTM34Text"] = "{PLAYER} riceve\nMT34!",
  ["_PewterGymTM34NoRoomText"] = "Non hai spazio per\nquesto!",
  ["_PewterMartSuperNerdText"] = "Cose buone possono\ncapitare se\vallevi con\ndiligenza i\vPOKéMON, anche\nquelli deboli!",
  ["_PewterMartYoungsterText"] = "Un vecchio losco\nmi ha fatto\vcomprare uno\nstrano POKéMON\vpesce! E'\ndebolissimo ed é\vcostato ¥500!",
  ["_PewterNidoranHouseLittleBoyText"] = "NIDORAN cuccia!",
  ["_PewterNidoranHouseMiddleAgedManText"] = "Il nostro POKéMON\nviene da uno\vscambio, é duro.\nUn forestiero é\vun POKéMON preso\ntramite scambio.\vCresce in fretta,\nma puo' ignorare\vun allenatore\ninesperto in\vlotta! Se solo\navessimo\vmedaglie...",
  ["_PewterNidoranHouseNidoranText"] = "NIDORAN: Bowbow!",
  ["_PewterPokecenterGentlemanText"] = "Cosa!? Il TEAM\nROCKET é al MONTE\vLUNA? Eh? Sono al\ntelefono!\vSparisci!",
  ["_PewterPokecenterJigglypuffText"] = "JIGGLYPUFF: Puu\npupuu!",
  ["_PewterSpeechHouseGamblerText"] = "I POKéMON imparano\nnuove tecniche\vcrescendo! Ma\nalcune mosse\vvanno insegnate\ndall'allenatore!",
  ["_PewterSpeechHouseYoungsterText"] = "I POKéMON sono\npiu' facili da\vcatturare se\nferiti o\vaddormentati! Ma\nnon é una\vcertezza assoluta!",
  ["_PickUpPayDayMoneyText"] = "{PLAYER} raccoglie\n¥{NUM:wTotalPayDayMoney,\v3 | LEADING_ZEROES\n| LEFT_ALIGN}!",
  ["_PlaySlotMachineText"] = "Una slot machine!\nVuoi giocare?",
  ["_PlayedFluteHadEffectText"] = "{PLAYER} suona il\nFLAUTO POKéMON.",
  ["_PlayedFluteNoEffectText"] = "Suonato il FLAUTO\nPOKéMON. Che\vmotivetto\norecchiabile!",
  ["_PlayerBlackedOutText"] = "{PLAYER} non ha\npiu' POKéMON\vvalidi! {PLAYER} é\nk.o.!",
  ["_PlayerBlackedOutText2"] = "{PLAYER} non ha\npiu' POKéMON\vvalidi! {PLAYER} é\nk.o.!",
  ["_PlayerMon1Text"] = "{RAM:wBattleMonNick}!",
  ["_PlayerMon2Text"] = "{RAM:wBattleMonNick}",
  ["_PlayerMonFaintedText"] = "{RAM:wBattleMonNick} é\nesausto!",
  ["_PleaseWaitText"] = "OK, attendi solo\nun momento.",
  ["_PoisonedText"] = "{TARGET}\né stato\vavvelenato!",
  ["_PokeCenterSignText"] = "Cura i tuoi\nPOKéMON! CENTRO\vPOKéMON",
  ["_PokemartAnythingElseText"] = "Posso fare\nqualcos'altro?",
  ["_PokemartBoughtItemText"] = "Eccolo a te!\nGrazie!",
  ["_PokemartBuyingGreetingText"] = "Prenditi tutto il\ntempo che vuoi.",
  ["_PokemartGreetingText"] = "Salve! Posso\naiutarti?",
  ["_PokemartItemBagEmptyText"] = "Non hai nulla da\nvendere.",
  ["_PokemartItemBagFullText"] = "Non puoi portare\naltri strumenti.",
  ["_PokemartNotEnoughMoneyText"] = "Non hai abbastanza\nsoldi.",
  ["_PokemartTellBuyPriceText"] = "{RAM:wStringBuffer}?\nFaranno\v¥{NUM:hMoney, 3 |\nLEADING_ZEROES |\vLEFT_ALIGN}. Va\nbene?",
  ["_PokemartTellSellPriceText"] = "Posso darti\n¥{NUM:hMoney, 3 |\vLEADING_ZEROES |\nLEFT_ALIGN} per\vquesto.",
  ["_PokemartThankYouText"] = "Grazie!",
  ["_PokemartUnsellableItemText"] = "Non posso dare un\nprezzo a questo.",
  ["_PokemonBooksText"] = "Pieno zeppo di\nlibri sui\vPOKéMON!",
  ["_PokemonCenterFarewellText"] = "Speriamo di\nrivederti presto!",
  ["_PokemonCenterWelcomeText"] = "Benvenuti al\nnostro CENTRO\vPOKéMON!\nRistabiliamo la\vpiena forma dei\ntuoi POKéMON!",
  ["_PokemonFaintedText"] = "{RAM:wNameBuffer} é\nesausto!",
  ["_PokemonFanClubBagFullText"] = "Fai spazio per\nquesto!",
  ["_PokemonFanClubChairFinalText"] = "Salve, {PLAYER}!\nSei tornato per\vparlare dei miei\nPOKéMON? No? Che\vpeccato!",
  ["_PokemonFanClubChairmanIntroText"] = "Sono il presidente\ndel Fan Club! Ho\vraccolto oltre 100\nPOKéMON! Sono\vmolto esigente in\nfatto di POKéMON!\vQuindi... Sei\nvenuto a sentire\vla mia storia?",
  ["_PokemonFanClubChairmanStoryText"] = "Bene! Ascoltate\nallora! Il mio\vRAPIDASH... é...\ncarino...\vadorabile...\nintelligente...\vsplendido...\ngentile... lo\vadoro!\nAbbracciarlo...\vquando riposa...\ncaldo e\vcoccoloso...\nspettacolare...\v...Ops! Guarda\nl'ora! Ti ho\vtrattenuto troppo!\nGrazie\vdell'ascolto!\nPrendi questo!",
  ["_PokemonFanClubExplainBikeVoucherText"] = "Scambialo per una\nBICICLETTA! Non\vtemere, il mio\nFEAROW mi porta\vovunque volando!\nQuindi non mi\vserve la BICI!\nSpero ti piaccia\vandare in bici!",
  ["_PokemonFanClubNoStoryText"] = "Oh. Torna quando\nvorrai ascoltare\vla mia storia!",
  ["_PokemonFanClubPikachuFanBetterText"] = "Uffa! Il mio\nPIKACHU é il\vdoppio piu'\ncarino!",
  ["_PokemonFanClubPikachuFanNormalText"] = "Non ammiri la coda\ndel mio PIKACHU?",
  ["_PokemonFanClubPikachuText"] = "PIKACHU: Chu!\nPikachu!",
  ["_PokemonFanClubReceivedBikeVoucherText"] = "{PLAYER} riceve\n{RAM:wStringBuffer}!",
  ["_PokemonFanClubReceptionistText"] = "Il nostro\npresidente parla\vsempre di POKéMON.",
  ["_PokemonFanClubSeelFanBetterText"] = "Oh cielo! Il mio\nSEEL é molto piu'\vattraente!",
  ["_PokemonFanClubSeelFanNormalText"] = "Adoro il mio SEEL!\nEmette un suono\vquando lo stringo!",
  ["_PokemonFanClubSeelText"] = "SEEL: Kyuoo!",
  ["_PokemonFanClubSign1Text"] = "Ascoltiamo tutti\ncon educazione\vgli altri\nallenatori!",
  ["_PokemonFanClubSign2Text"] = "Se qualcuno si\nvanta, vantati\vpure tu!",
  ["_PokemonFightingFitText"] = "Grazie! I tuoi\nPOKéMON sono in\vforma!",
  ["_PokemonMansion1FScientistAfterBattleText"] = "Una chiave? Non so\ndi cosa tu stia\vparlando.",
  ["_PokemonMansion1FScientistBattleText"] = "Chi sei? Non\ndovrebbe esserci\vnessuno qui.",
  ["_PokemonMansion1FScientistEndBattleText"] = "Ahi!",
  ["_PokemonMansion1FSwitchNotPressedText"] = "Non ancora!",
  ["_PokemonMansion1FSwitchPressedText"] = "Chi non lo\nfarebbe?",
  ["_PokemonMansion1FSwitchText"] = "Un interruttore\nsegreto! Vuoi\vpremerlo?",
  ["_PokemonMansion2FDiary1Text"] = "Diario: 5 luglio\nGuyana, Sud\vAmerica Nuovo\nPOKéMON scoperto\vnel profondo della\ngiungla.",
  ["_PokemonMansion2FDiary2Text"] = "Diario: 10 luglio\nAbbiamo\vbattezzato il\nnuovo POKéMON,\vMEW.",
  ["_PokemonMansion2FSuperNerdAfterBattleText"] = "Gli interruttori\naprono e chiudono\vporte alternate!",
  ["_PokemonMansion2FSuperNerdBattleText"] = "Non riesco a\nuscire! Questo\vvecchio posto é un\nrompicapo!",
  ["_PokemonMansion2FSuperNerdEndBattleText"] = "Oh no!\nIl mio sacco di\voggetti!",
  ["_PokemonMansion2FSwitchNotPressedText"] = "Non ancora!",
  ["_PokemonMansion2FSwitchPressedText"] = "Chi non lo\nfarebbe?",
  ["_PokemonMansion2FSwitchText"] = "Un interruttore\nsegreto! Vuoi\vpremerlo?",
  ["_PokemonMansion3FDiaryText"] = "Diario: 6 feb. MEW\nha partorito.\vAbbiamo chiamato\nil piccolo\vMEWTWO.",
  ["_PokemonMansion3FScientistAfterBattleText"] = "Sei bloccato?\nProva a saltare\vgiu' da li'!",
  ["_PokemonMansion3FScientistBattleText"] = "Il mio mentore\nvisse qui un\vtempo.",
  ["_PokemonMansion3FScientistEndBattleText"] = "Uf!\nTravolgente!",
  ["_PokemonMansion3FSuperNerdAfterBattleText"] = "Chissa' dove é\nandato il mio\vsocio.",
  ["_PokemonMansion3FSuperNerdBattleText"] = "Questo posto é\ncosi' grande!",
  ["_PokemonMansion3FSuperNerdEndBattleText"] = "Ahi!",
  ["_PokemonMansionB1FBurglarAfterBattleText"] = "Puoi trovare roba\nin giro.",
  ["_PokemonMansionB1FBurglarBattleText"] = "Oh no. Dove mi\ntrovo ora?",
  ["_PokemonMansionB1FBurglarEndBattleText"] = "Awooh!",
  ["_PokemonMansionB1FDiaryText"] = "Diario: 1 set.\nMEWTWO é troppo\vpotente. Non siamo\nriusciti a\vfrenare la sua\nindole feroce...",
  ["_PokemonMansionB1FScientistAfterBattleText"] = "Mi piace qui!\nFavorisce i miei\vstudi!",
  ["_PokemonMansionB1FScientistBattleText"] = "Questo posto é\nideale per un\vlab.",
  ["_PokemonMansionB1FScientistEndBattleText"] = "A che\nserviva questo?",
  ["_PokemonSellingGreetingText"] = "Cosa vorresti\nvendere?",
  ["_PokemonStuffText"] = "Wow! Un mucchio di\nroba POKéMON!",
  ["_PokemonTower1FBaldingGuyText"] = "Sono venuto a\npregare per il\vmio CLEFAIRY.\nSniff! Non riesco\va smettere di\npiangere...",
  ["_PokemonTower1FChannelerText"] = "Sono un MEDIUM! Ci\nsono spiriti che\vfanno marachelle!",
  ["_PokemonTower1FGirlText"] = "Il mio\nGROWLITHE...\vPerché sei morto?",
  ["_PokemonTower1FMiddleAgedWomanText"] = "Sei venuto a\nportare rispetto?\vSii benedetto!",
  ["_PokemonTower1FReceptionistText"] = "La TORRE POKéMON\nfu eretta in\vmemoria dei\nPOKéMON deceduti.",
  ["_PokemonTower2FChannelerText"] = "Neanche noi\nidentifichiamo i\vFANTASMI! Uno\nSPETTROSONDA li\vsmaschererebbe.",
  ["_PokemonTower2FRivalDefeatedText"] = "Cosa? Sei\nuna carogna! Ci\vsono andato\npesante anch'io!",
  ["_PokemonTower2FRivalHowsYourDexText"] = "Come va\nil POKéDEX,\vamico? Ho appena\ncatturato un\vCUBONE! Non trovo\nancora il MAROWAK\vadulto! Dubbia ce\nne siano! Be',\vdevo andare! Ho\nmolto da fare! A\vpresto, amico!",
  ["_PokemonTower2FRivalVictoryText"] = "{RIVAL}:\nBeh, quanti\vPOKéMON fifoni\nhai! Rinforzali\vun po' di piu'!",
  ["_PokemonTower2FRivalWhatBringsYouHereText"] = "{RIVAL}: Ehi\n{PLAYER}! Cosa ci\vfai qui? I tuoi\nPOKéMON non\vsembrano morti!\nPosso almeno\vfarli svenire!\nForza, amico!",
  ["_PokemonTower3FChanneler1AfterBattleText"] = "I FANTASMI si\nriconoscono con\vlo SPETTROSONDA.",
  ["_PokemonTower3FChanneler1BattleText"] = "Urrg... Awaa...\nHuhu... graa..",
  ["_PokemonTower3FChanneler1EndBattleText"] = "Hwa! Sono\nsalva!",
  ["_PokemonTower3FChanneler2AfterBattleText"] = "Scusa! Ero\nposseduta!",
  ["_PokemonTower3FChanneler2BattleText"] = "Kekeke... Kwaaah!",
  ["_PokemonTower3FChanneler2EndBattleText"] = "Mhm? Che\nsto facendo?",
  ["_PokemonTower3FChanneler3AfterBattleText"] = "Anche i miei amici\nerano posseduti!",
  ["_PokemonTower3FChanneler3BattleText"] = "Vattene! Spirito\nmalvagio!",
  ["_PokemonTower3FChanneler3EndBattleText"] = "Uf! Lo\nspirito é via!",
  ["_PokemonTower4FChanneler1AfterBattleText"] = "Devo aver\nsognato...",
  ["_PokemonTower4FChanneler1BattleText"] = "FANTASMA! No!\nKwaaah!",
  ["_PokemonTower4FChanneler1EndBattleText"] = "Dov'é il\nFANTASMA?",
  ["_PokemonTower4FChanneler2AfterBattleText"] = "Non scopriamo\nl'identita' dei\vFANTASMI.",
  ["_PokemonTower4FChanneler2BattleText"] = "Maledetto con me!\nKwaaah!",
  ["_PokemonTower4FChanneler2EndBattleText"] = "Cosa!",
  ["_PokemonTower4FChanneler3AfterBattleText"] = "Che le anime dei\nPOKéMON riposino\vin pace...",
  ["_PokemonTower4FChanneler3BattleText"] = "Huhuhu... Non\nbattermi!",
  ["_PokemonTower4FChanneler3EndBattleText"] = "Eh? Chi?\nCosa?",
  ["_PokemonTower5FChanneler1Text"] = "Vieni, bimbo! Ho\nsigillato lo\vspazio con magia!\nPuoi riposare\vqui!",
  ["_PokemonTower5FChanneler2AfterBattleText"] = "Ero sotto\npossessione!",
  ["_PokemonTower5FChanneler2BattleText"] = "Dammi... la tua...\nanima...",
  ["_PokemonTower5FChanneler2EndBattleText"] = "Gasp!",
  ["_PokemonTower5FChanneler3AfterBattleText"] = "Ero posseduta!",
  ["_PokemonTower5FChanneler3BattleText"] = "Tu... unisciti...\na noi...",
  ["_PokemonTower5FChanneler3EndBattleText"] = "Che\nincubo!",
  ["_PokemonTower5FChanneler4AfterBattleText"] = "Ho ripreso i\nsensi!",
  ["_PokemonTower5FChanneler4BattleText"] = "Zombi!",
  ["_PokemonTower5FChanneler4EndBattleText"] = "Ah?",
  ["_PokemonTower5FChanneler5AfterBattleText"] = "Caddi nel male\nnonostante\vl'addestramento!",
  ["_PokemonTower5FChanneler5BattleText"] = "Urgah... Urff....",
  ["_PokemonTower5FChanneler5EndBattleText"] = "Whoo!",
  ["_PokemonTower5FPurifiedZoneText"] = "Entrato in zona\nprotetta e pura!\vI POKéMON di\n{PLAYER} sono\vcurati!",
  ["_PokemonTower6FBeGoneText"] = "Viatene...\nIntrusi...",
  ["_PokemonTower6FChanneler1AfterBattleText"] = "Mi sento anemica e\ndebole...",
  ["_PokemonTower6FChanneler1BattleText"] = "Dammi... il tuo...\nsangue...",
  ["_PokemonTower6FChanneler1EndBattleText"] = "Gemito!",
  ["_PokemonTower6FChanneler2AfterBattleText"] = "I capelli non sono\ncaduti! Era uno\vspirito malvagio!",
  ["_PokemonTower6FChanneler2BattleText"] = "Urff... Kwaah!",
  ["_PokemonTower6FChanneler2EndBattleText"] = "Qualcosa é\ncaduto!",
  ["_PokemonTower6FChanneler3AfterBattleText"] = "Che succede qui?",
  ["_PokemonTower6FChanneler3BattleText"] = "Ke..ke...ke...\nke..ke...ke!!",
  ["_PokemonTower6FChanneler3EndBattleText"] = "Keee!",
  ["_PokemonTower6FGhostWasCubonesMotherText"] = "Il FANTASMA era\nl'anima\virrequieta della\nmadre!",
  ["_PokemonTower6FSoulWasCalmedText"] = "L'anima della\nmadre é calmata.\vé partita per\nl'aldila'!",
  ["_PokemonTower7FMrFujiRescueText"] = "MR. FUJI: Eh? Sei\nvenuto a\vsalvarmi? Grazie.\nMa sono venuto di\vmia spontanea\nvolonta'. Per\vcalmare l'anima\ndella madre di\vCUBONE. Penso che\nlo spirito sia\vandato\nnell'aldila'. Ti\vringrazio per il\npensiero! Seguimi\va casa, alla CASA\nPOKéMON ai piedi\vdella torre.",
  ["_PokemonTower7FRocket1AfterBattleText"] = "Non lo\ndimentichero'!",
  ["_PokemonTower7FRocket1BattleText"] = "Che vuoi? Perché\nsei qui?",
  ["_PokemonTower7FRocket1EndBattleText"] = "Mi\narrendo!",
  ["_PokemonTower7FRocket2AfterBattleText"] = "I POKéMON servono\nsolo a fare\vsoldi! Non\nimpicciarti!",
  ["_PokemonTower7FRocket2BattleText"] = "Questo vecchietto\nsi é lamentato\vper i POKéMON\ninutili!\vDiscutiamo da\nadulti noi!",
  ["_PokemonTower7FRocket2EndBattleText"] = "Ti prego!\nBasta!",
  ["_PokemonTower7FRocket3AfterBattleText"] = "Non la passerai\nliscia!",
  ["_PokemonTower7FRocket3BattleText"] = "Non salverai\nnessuno,\vmoccioso!",
  ["_PokemonTower7FRocket3EndBattleText"] = "Non\nsfidare i ROCKET!",
  ["_PoofText"] = "Puff!",
  ["_PotionText"] = "{RAM:wNameBuffer}\nrecupera\v{NUM:wHPBarHPDifference,\n2, 3}!",
  ["_PowerPlantVoltorbBattleText"] = "Bzzzt!",
  ["_PowerPlantZapdosBattleText"] = "Gyaoo!",
  ["_PushStartText"] = "Premi START per\naprire il MENU!",
  ["_RaisePPWhichTechniqueText"] = "Aumentare i PP di\nquale mossa?",
  ["_RanAwayScaredText"] = "{TARGET}\né fuggito per la\vpaura!",
  ["_RanFromBattleText"] = "{USER}\nfugge dalla\vlotta!",
  ["_RareCandyText"] = "{RAM:wNameBuffer} sale al\nlivello\v{NUM:wCurEnemyLevel,\n1, 3}!",
  ["_RedBedroomSNESText"] = "{PLAYER} gioca al\nSuper NES!\v...Bene! é ora di\nandare!",
  ["_RedsHouse1FMomLookingGreatText"] = "MAMMA: Oh bene! Tu\ne i POKéMON state\vbenissimo! Badate\na voi!",
  ["_RedsHouse1FMomWakeUpText"] = "MAMMA: Giusto.\nTutti i ragazzi\vlasciano casa. Lo\nhan detto in TV.\vIl PROF. OAK, qui\naccanto, ti\vcerca.",
  ["_RedsHouse1FMomYouShouldRestText"] = "MAMMA: {PLAYER}!\nDovresti riposare\vun attimo.",
  ["_RedsHouse1FTVStandByMeMovieText"] = "C'é un film in TV.\nQuattro ragazzi\vcamminano sui\nbinari. Meglio\vandare anch'io.",
  ["_RedsHouse1FTVWrongSideText"] = "Ops, lato\nsbagliato.",
  ["_ReflectGainedArmorText"] = "{USER}\nottiene uno\vscudo!",
  ["_RegainedHealthText"] = "{USER}\nrecupera salute!",
  ["_ReleaseWhichMonText"] = "Quale POKéMON\nliberare?",
