  ["_RequireCoinCaseText"] = "Serve un\nSALVADANAIO!",
  ["_RestorePPWhichTechniqueText"] = "Ripristinare i PP\ndi quale mossa?",
  ["_ReviveText"] = "{RAM:wNameBuffer} é\nrivitalizzato!",
  ["_Rival1WinText"] = "{RIVAL}:\nSi'! Non sono\vfantastico?",
  ["_RivalDefeatedText"] = "NO! Non\npuo' essere! Hai\vbattuto il meglio!\nDopo tanto lavoro\vper la LEGA? Il\nmio regno é gia'\vterminato? Non é\ngiusto!",
  ["_RivalVictoryText"] = "Ahahah!\nHo vinto, ho\vvinto! Sono troppo\nforte per te,\v{PLAYER}! Sei stato\nbravo ad arrivare\vfin qui, io sono\nil genio! Bel\vtentativo, ma non\nvali nulla!\vAhahah!",
  ["_RockTunnel1FCooltrainerF1AfterBattleText"] = "Ho visto un MACHOP\nin questo tunnel!",
  ["_RockTunnel1FCooltrainerF1BattleText"] = "Eek! Non fare\nscherzi nel buio!",
  ["_RockTunnel1FCooltrainerF1EndBattleText"] = "Era\ntroppo buio!",
  ["_RockTunnel1FCooltrainerF2AfterBattleText"] = "Sembravi carino e\ninnocuo!",
  ["_RockTunnel1FCooltrainerF2BattleText"] = "Sono venuto fin\nqui per i\vPOKéMON!",
  ["_RockTunnel1FCooltrainerF2EndBattleText"] = "Non\nho piu' POKéMON!",
  ["_RockTunnel1FCooltrainerF3AfterBattleText"] = "Uf! Ora sono tutto\nsudato!",
  ["_RockTunnel1FCooltrainerF3BattleText"] = "Hai dei POKéMON!\nIniziamo!",
  ["_RockTunnel1FCooltrainerF3EndBattleText"] = "\nGiochi duro!",
  ["_RockTunnel1FHiker1AfterBattleText"] = "Attento a ONIX!\nPuo' stritolarti!",
  ["_RockTunnel1FHiker1BattleText"] = "Questo tunnel é\nmolto lungo,\vragazzo!",
  ["_RockTunnel1FHiker1EndBattleText"] = "Doh!\nHai vinto!",
  ["_RockTunnel1FHiker2AfterBattleText"] = "Quel POKéMON\ndormiente al\vPERCORSO mi ha\ncostretto a una\vdeviazione.",
  ["_RockTunnel1FHiker2BattleText"] = "Mhm. Forse mi sono\nperso...",
  ["_RockTunnel1FHiker2EndBattleText"] = "Calma!\nChe sto facendo?\vDov'é l'uscita?",
  ["_RockTunnel1FHiker3AfterBattleText"] = "Hai abbastanza\ntalento per\vscalare!",
  ["_RockTunnel1FHiker3BattleText"] = "I forestieri come\nte devono\vmostrarmi\nrispetto!",
  ["_RockTunnel1FHiker3EndBattleText"] = "Mi\narrendo!",
  ["_RockTunnel1FSignText"] = "TUNNEL ROCCIOSO\nCELESTOPOLI\vLAVANDONIA",
  ["_RockTunnel1FSuperNerdAfterBattleText"] = "Vabbé, prendero'\nun ZUBAT strada\vfacendo!",
  ["_RockTunnel1FSuperNerdBattleText"] = "Lotta POKéMON!\nPronti, via!",
  ["_RockTunnel1FSuperNerdEndBattleText"] = "Game\nover!",
  ["_RockTunnelB1FCooltrainerF1AfterBattleText"] = "Voglio andare a\ncasa!",
  ["_RockTunnelB1FCooltrainerF1BattleText"] = "Gli escursionisti\nlasciano rametti\vcome segnavia.",
  ["_RockTunnelB1FCooltrainerF1EndBattleText"] = "\nOhhh! Ho fatto\vdel mio meglio!",
  ["_RockTunnelB1FCooltrainerF2AfterBattleText"] = "Amo i piccoli\nPOKéMON, i grandi\vfanno paura!",
  ["_RockTunnelB1FCooltrainerF2BattleText"] = "Non vengo spesso,\nma lottero' con\vte.",
  ["_RockTunnelB1FCooltrainerF2EndBattleText"] = "Oh!\nHo perso!",
  ["_RockTunnelB1FHiker1AfterBattleText"] = "Punto sulla forza\nperché odio\vpensare!",
  ["_RockTunnelB1FHiker1BattleText"] = "Ahahah! Puoi\nbattere la mia\vforza?",
  ["_RockTunnelB1FHiker1EndBattleText"] = "Ops!\nBattuto!",
  ["_RockTunnelB1FHiker2AfterBattleText"] = "Tra i monti trovi\nspesso POKéMON di\vtipo roccia.",
  ["_RockTunnelB1FHiker2BattleText"] = "Le mie tecniche ti\nfaranno piangere!",
  ["_RockTunnelB1FHiker2EndBattleText"] = "Mi\narrendo! Sei un\vtecnico migliore!",
  ["_RockTunnelB1FHiker3AfterBattleText"] = "Crescero' il mio\nPOKéMON per\vbattere il tuo,\nragazzo!",
  ["_RockTunnelB1FHiker3BattleText"] = "Colpiscimi con il\ntuo meglio!",
  ["_RockTunnelB1FHiker3EndBattleText"] = "Colpo\npartito!",
  ["_RockTunnelB1FSuperNerd1AfterBattleText"] = "Quando finisci il\nPOKéDEX, posso\vaverlo?",
  ["_RockTunnelB1FSuperNerd1BattleText"] = "Hai un POKéDEX? Ne\nvoglio uno!",
  ["_RockTunnelB1FSuperNerd1EndBattleText"] = "\nAccidenti! Che\vinvidia!",
  ["_RockTunnelB1FSuperNerd2AfterBattleText"] = "Alcuni si vestono\nda POKéMON per\vdivertimento.",
  ["_RockTunnelB1FSuperNerd2BattleText"] = "Conosci i\ncosplayer di\vPOKéMON?",
  ["_RockTunnelB1FSuperNerd2EndBattleText"] = "Be',\nquesto é tutto.",
  ["_RockTunnelB1FSuperNerd3AfterBattleText"] = "Sono un artista,\nnon un lottatore.",
  ["_RockTunnelB1FSuperNerd3BattleText"] = "Disegno POKéMON\nquando sono a\vcasa.",
  ["_RockTunnelB1FSuperNerd3EndBattleText"] = "Uf!\nSono esausto!",
  ["_RockTunnelPokecenterFisherText"] = "Ho venduto una\nPEPITA per ¥5000!",
  ["_RockTunnelPokecenterGentlemanText"] = "I tipi elementali\ndei POKéMON li\vrendono forti con\nalcuni e deboli\vcon altri!",
  ["_RockTunnelPokecenterGuyText"] = "Ho sentito che i\nFANTASMI\vinfestano\nLAVANDONIA!",
  ["_RocketHide3AfterBattleText3"] = "Vai pure avanti!\nMa ti serve la\vCHIAVE ASCENSORE!",
  ["_RocketHideout3BattleText"] = "Ci é arrivata voce\nche stavi\varrivando!",
  ["_RocketHideout3EndBattleText3"] = "Cosa? Ho\nperso? No!",
  ["_RocketHideoutB1FRocket1AfterBattleText"] = "Stai criticando il\nTEAM ROCKET?",
  ["_RocketHideoutB1FRocket1BattleText"] = "Chi sei? Come sei\narrivato qui?",
  ["_RocketHideoutB1FRocket1EndBattleText"] = "Ahi!\nBattuto!",
  ["_RocketHideoutB1FRocket2AfterBattleText"] = "Non la passerai\nliscia, moccioso!",
  ["_RocketHideoutB1FRocket2BattleText"] = "Ti sei introdotto\nnella nostra\vbase?",
  ["_RocketHideoutB1FRocket2EndBattleText"] = "Bruciato!",
  ["_RocketHideoutB1FRocket3AfterBattleText"] = "La SPETTROSONDA?\nNon so dove sia!",
  ["_RocketHideoutB1FRocket3BattleText"] = "Allarme intruso!",
  ["_RocketHideoutB1FRocket3EndBattleText"] = "Non ci\nriesco!",
  ["_RocketHideoutB1FRocket4AfterBattleText"] = "OK, parlero'!\nPrendi\vl'ascensore per il\nCAPO!",
  ["_RocketHideoutB1FRocket4BattleText"] = "Perché sei venuto\nqui?",
  ["_RocketHideoutB1FRocket4EndBattleText"] = "Questo non\nva!",
  ["_RocketHideoutB1FRocket5AfterBattleText"] = "Oh no, quella\nlotta ha aperto\vla porta!",
  ["_RocketHideoutB1FRocket5BattleText"] = "Ti sei perso,\npiccolo ratto?",
  ["_RocketHideoutB1FRocket5EndBattleText"] = "Perché...?",
  ["_RocketHideoutB2FRocketAfterBattleText"] = "La base ROCKET ha\n4 piani\vinterrati.\nArriverai dal\vCAPO?",
  ["_RocketHideoutB2FRocketBattleText"] = "Il CAPO dice che\nvedi i FANTASMI\vcon lo\nSPETTROSONDA!",
  ["_RocketHideoutB2FRocketEndBattleText"] = "Mi\narrendo!",
  ["_RocketHideoutB3FRocket1AfterBattleText"] = "SPETTROSONDA? La\nmacchina rubata.\vé qui da qualche\nparte.",
  ["_RocketHideoutB3FRocket1BattleText"] = "Smetti di\nintrometterti\vnegli affari del\nROCKET!",
  ["_RocketHideoutB3FRocket1EndBattleText"] = "Oof!\nAtterrato!",
  ["_RocketHideoutB4FGiovanniHopeWeMeetAgainText"] = "Vedo che cresci i\nPOKéMON con cura.\vUn bambino come te\nnon capirebbe\vcosa voglio fare.\nMi faccio da\vparte stavolta!\nSpero ci\vriverremo...",
  ["_RocketHideoutB4FGiovanniImpressedYouGotHereText"] = "Dunque! Devo dire\nche sono colpito\vche tu sia qui!",
  ["_RocketHideoutB4FGiovanniWhatCannotBeText"] = "COSA! Non puo'\nessere!",
  ["_RocketHideoutB4FRocket1AfterBattleText"] = "Ce l'hai con il\nTEAM ROCKET?",
  ["_RocketHideoutB4FRocket1BattleText"] = "Ti conosco! Hai\nrovinato i piani\val MONTE LUNA!",
  ["_RocketHideoutB4FRocket1EndBattleText"] = "Bruciato\ndi nuovo!",
  ["_RocketHideoutB4FRocket2AfterBattleText"] = "CAPO! Scusa se ho\nfallito!",
  ["_RocketHideoutB4FRocket2BattleText"] = "Come fai a non\nvedere la\vbellezza del\nnostro male?",
  ["_RocketHideoutB4FRocket2EndBattleText"] = "Ayaya!",
  ["_RocketHideoutB4FRocket3AfterBattleText"] = "Oh no! Ho perso la\nCHIAVE ASCENSORE!",
  ["_RocketHideoutB4FRocket3BattleText"] = "L'ascensore non\nva? Chi ha la\vCHIAVE ASCENSORE?",
  ["_RocketHideoutB4FRocket3EndBattleText"] = "No!",
  ["_RocketHideoutElevatorAppearsToNeedKeyText"] = "Sembra che serva\nuna chiave.",







  ["_RoseText"] = "rose!",
  ["_Route10CooltrainerF1AfterBattleText"] = "Ho notato dei\nPOKéMANIAC che\vgironzolavano.",
  ["_Route10CooltrainerF1BattleText"] = "Sono stata in una\nPALESTRA POKéMON\vqualche volta. Ma\nho sempre perso.",
  ["_Route10CooltrainerF1EndBattleText"] = "Oh!\nDi nuovo al\vtappeto!",
  ["_Route10CooltrainerF2AfterBattleText"] = "I POKéMON qui sono\ncosi' paffuti!\vDovrebbe essercene\nuno rosa con un\vmotivo floreale!",
  ["_Route10CooltrainerF2BattleText"] = "Mi sento un po'\nsvienevole per\vquesta dura\nescursione.",
  ["_Route10CooltrainerF2EndBattleText"] = "Non\nce la faccio!",
  ["_Route10Hiker1AfterBattleText"] = "E-et-ciu'!\nEt-ciu'! Sniff!\vTirch!",
  ["_Route10Hiker1BattleText"] = "Ah-ahah-ah-ah!",
  ["_Route10Hiker1EndBattleText"] = "Ah-aha!\nNon sto ridendo!\vHo il raffreddore!\nE-et-ciu'!",
  ["_Route10Hiker2AfterBattleText"] = "Mi sento gonfio\ndell'aria di\vmonte!",
  ["_Route10Hiker2BattleText"] = "Ah! Quest'aria di\nmonte é\vdeliziosa!",
  ["_Route10Hiker2EndBattleText"] = "Questo\nmi ha schiarito\vle idee!",
  ["_Route10PowerPlantSignText"] = "CENTRALE ELETTRICA",
  ["_Route10RockTunnelSignText"] = "DIGRAPUNTO",
  ["_Route10SuperNerd1AfterBattleText"] = "Ho altri POKéMON\nrari a casa!",
  ["_Route10SuperNerd1BattleText"] = "Wow, sei un\nPOKéMANIAC anche\vtu? Vuoi vedere la\nmia collezione?",
  ["_Route10SuperNerd1EndBattleText"] = "Uhm.\nNon sono\varrabbiato!",
  ["_Route10SuperNerd2AfterBattleText"] = "Mi stai antipatico\nperché mi hai\vbattuto!",
  ["_Route10SuperNerd2BattleText"] = "Ehi ragazzo, vuoi\nvedere i miei\vPOKéMON?",
  ["_Route10SuperNerd2EndBattleText"] = "Oh no!\nI miei POKéMON!",
  ["_Route11DiglettsCaveSignText"] = "GROTTA DIGLETT",
  ["_Route11Gambler1AfterBattleText"] = "I POKéMON sono\nvita! E vivere\vsignifica\nazzardare!",
  ["_Route11Gambler1BattleText"] = "Vinci, perdi o\npareggi!",
  ["_Route11Gambler1EndBattleText"] = "Atcha!\nNon é andata come\vvolevo!",
  ["_Route11Gambler2AfterBattleText"] = "Non puoi essere un\ncovardo nel mondo\vdei POKéMON!",
  ["_Route11Gambler2BattleText"] = "Competizione! Non\nne tengo mai\vabbastanza!",
  ["_Route11Gambler2EndBattleText"] = "Avevo\nuna possibilita'!",
  ["_Route11Gambler3AfterBattleText"] = "Colpo di fortuna!\nSolo fortuna!",
  ["_Route11Gambler3BattleText"] = "Fwahaha! Non ho\nmai perso!",
  ["_Route11Gambler3EndBattleText"] = "La mia\nprima sconfitta!",
  ["_Route11Gambler4AfterBattleText"] = "é solo fortuna.\nColpo di fortuna.",
  ["_Route11Gambler4BattleText"] = "Non avevo mai\nvinto prima...",
  ["_Route11Gambler4EndBattleText"] = "Me lo\nsapevo...",
  ["_Route11Gate1FGuardText"] = "Quando catturi\ntanti POKéMON,\vnon é difficile\ntrovare i nomi? A\vLAVANDONIA c'é un\nesperto di\vnomignoli POKéMON.\nTi aiutera' anche\va ribattezzarli!",
  ["_Route11Gate2FLeftBinocularsNoSnorlaxText"] = "Hai guardato nei\nbinocoli. C'é una\vvista stupenda!",
  ["_Route11Gate2FLeftBinocularsSnorlaxText"] = "Hai guardato nei\nbinocoli. Un\vgrosso POKéMON\ndorme sulla\vstrada!",
  ["_Route11Gate2FOaksAideItemfinderDescriptionText"] = "Ci sono oggetti a\nterra che non si\vpossono vedere.\nCERCASP_ e' in\vgrado di rilevarli\nnelle vicinanze.\vNon individua il\npunto esatto,\vdevi cercarli tu!",
  ["_Route11Gate2FRightBinocularsText"] = "Hai guardato nei\nbinocoli. L'unico\vmodo per andare da\nCELESTOPOLI a\vLAVANDONIA é\npassare per il\vDIGRAPUNTO.",
  ["_Route11SuperNerd1AfterBattleText"] = "Fai girare la\nvoce: risparmia\venergia!",
  ["_Route11SuperNerd1BattleText"] = "Attento! Sto\nposando dei cavi!",
  ["_Route11SuperNerd1EndBattleText"] = "é stata\nun'esperienza\velettrizzante!",
  ["_Route11SuperNerd2AfterBattleText"] = "Beh, é ora di\ntornare al\vlavoro.",
  ["_Route11SuperNerd2BattleText"] = "Attento ai fili\nscoperti!",
  ["_Route11SuperNerd2EndBattleText"] = "Urca!\nSei una\vscintilla!",
  ["_Route11Youngster1AfterBattleText"] = "Ce l'ho messa\ntutta! Non ho\vrimpianti!",
  ["_Route11Youngster1BattleText"] = "Andiamo, ma non\nbarare!",
  ["_Route11Youngster1EndBattleText"] = "Eh? Non é\ngiusto!",
  ["_Route11Youngster2AfterBattleText5"] = "Che vuoi? Lasciami\nin pace!",
  ["_Route11Youngster2BattleText"] = "Sono appena\ndiventato un\vallenatore! Ma\ncredo di poter\vvincere!",
  ["_Route11Youngster2EndBattleText"] = "I miei\nPOKéMON no!",
  ["_Route11Youngster3AfterBattleText"] = "C'é un grosso\nPOKéMON che\vscende dalle\nmontagne. é\vforte, se riesci a\nprenderlo.",
  ["_Route11Youngster3BattleText"] = "Sono il migliore\ndella mia classe!",
  ["_Route11Youngster3EndBattleText"] = "\nAcciderboli! Devo\vrendere i miei\nPOKéMON piu'\vforti!",
  ["_Route11Youngster4AfterBattleText"] = "Faro' meglio a\ncercarne di piu'\vforti!",
  ["_Route11Youngster4BattleText"] = "I miei POKéMON\ndovrebbero essere\vpronti!",
  ["_Route11Youngster4EndBattleText"] = "Troppo\ngiovane per\vfarlo!",
  ["_Route12CooltrainerMAfterBattleText"] = "Pensa che avrei\npotuto evolvere i\vmiei POKéMON con\nuna PIETRALUNARE!",
  ["_Route12CooltrainerMBattleText"] = "Hai trovato una\nPIETRALUNARE?",
  ["_Route12CooltrainerMEndBattleText"] = "Ahi!",
  ["_Route12Fisher1AfterBattleText"] = "Resisti! Ho la\nlenza impigliata!",
  ["_Route12Fisher1BattleText"] = "Evviva! Ha\nabboccato,\vproprio qui!",
  ["_Route12Fisher1EndBattleText"] = "Tch!\nSolo un\vpesciolino!",
  ["_Route12Fisher2AfterBattleText"] = "Con un AMO\nmigliore potrei\vcatturare POKéMON\nmigliori!",
  ["_Route12Fisher2BattleText"] = "Pazienza! La pesca\nrichiede molta\vattesa!",
  ["_Route12Fisher2EndBattleText"] = "Quello\né scappato!",
  ["_Route12Fisher3AfterBattleText"] = "Mi hai battuto coi\nPOKéMON, ma io ci\vsaccio con la\npesca!",
  ["_Route12Fisher3BattleText"] = "Il DRITTO DELLA\nPESCA contro il\vBIMBO POKéMON!",
  ["_Route12Fisher3EndBattleText"] = "Troppo\nforte!",
  ["_Route12Fisher4AfterBattleText"] = "Va bene lo stesso.\nPerdere non mi\vscoccia piu' di\ntanto.",
  ["_Route12Fisher4BattleText"] = "Preferirei\nlavorare!",
  ["_Route12Fisher4EndBattleText"] = "Non é\ncosi' semplice...",
  ["_Route12Fisher5AfterBattleText"] = "Pesco MAGIKARP in\ncontinuazione, ma\vsono debolissimi!",
  ["_Route12Fisher5BattleText"] = "Non sai mai cosa\npuoi pescare!",
  ["_Route12Fisher5EndBattleText"] = "\nScappato!",
  ["_Route12Gate1FGuardText"] = "C'é un punto di\nosservazione al\vpiano superiore.",
  ["_Route12Gate2FBrunetteGirlReceivedTM39Text"] = "{PLAYER} riceve\nMT39!",
  ["_Route12Gate2FBrunetteGirlTM39ExplanationText"] = "MT39 contiene\nPIrossino. é\vmolto precisa,\nusala nelle lotte\vche non puoi\npermetterti di\vperdere.",
  ["_Route12Gate2FBrunetteGirlTM39NoRoomText"] = "Non hai abbastanza\nspazio per\vquesto.",
  ["_Route12Gate2FBrunetteGirlYouCanHaveThisText"] = "Le ceneri del mio\nPOKéMON sono\vnella TORRE\nPOKéMON. Tieni\vquesta MT. Non mi\nserve piu'...",
  ["_Route12Gate2FLeftBinocularsText"] = "Hai guardato nei\nbinocoli. Un\vpescatore!",
  ["_Route12Gate2FRightBinocularsText"] = "Hai guardato nei\nbinocoli. é la\vTORRE POKéMON!",
  ["_Route12SignText"] = "PERCORSO 12 Nord\nper LAVANDONIA",
  ["_Route12SnorlaxCalmedDownText"] = "SNORLAX si é\ncalmato! Con un\vgrande sbadiglio é\ntornato sui\vmonti!",
  ["_Route12SnorlaxText"] = "Un POKéMON\ndormiente blocca\vla via!",
  ["_Route12SnorlaxWokeUpText"] = "SNORLAX si é\nsvegliato! Ha\vsferrato un\nattacco furioso!",
  ["_Route12SportFishingSignText"] = "AREA DI PESCA\nSPORTIVA",
  ["_Route12SuperNerdAfterBattleText"] = "L'acqua é\nconduttrice di\velettricita',\ndovresti friggere\vi POKéMON marini!",
  ["_Route12SuperNerdBattleText"] = "L'elettricita' é\nla mia\vspecialita'!",
  ["_Route12SuperNerdEndBattleText"] = "Spento!",
  ["_Route12SuperRodHouseFishingGuruDoYouLikeToFishText"] = "Sono il fratello\ndel GURU\vPESCATORE! Adoro\npescare! Ti piace\vpescare?",
  ["_Route12SuperRodHouseFishingGuruFishingWayOfLifeText"] = "La pesca é uno\nstile di vita!\vDai mari ai fiumi,\nesci e prendi il\vpesce grosso!",
  ["_Route12SuperRodHouseFishingGuruNoRoomText"] = "Oh no! Avevo un\nregalo per te, ma\vnon hai abbastanza\nspazio!",
  ["_Route12SuperRodHouseFishingGuruReceivedSuperRodText"] = "Magnifico! Mi\npiace il tuo\vstile! Prendi\nquesto e pesca,\vgiovanotto!\n{PLAYER} riceve\v{RAM:wStringBuffer}!",
  ["_Route12SuperRodHouseFishingGuruThatsDisappointingText"] = "Oh... Che\ndelusione...",
  ["_Route12SuperRodHouseFishingGuruTryFishingText"] = "Ciao, {PLAYER}! Usa\nil SUPERAMO in\vqualsiasi acqua!\nPotrai pescare\vdiversi tipi di\nPOKéMON. Prova a\vpescare dovunque\ntu possa!",
  ["_Route13Beauty1AfterBattleText"] = "Chissa' se sono\npiu' forti i\vPOKéMON maschi o\nfemmine?",
  ["_Route13Beauty1BattleText"] = "Certo, giochero'\ncon te!",
  ["_Route13Beauty1EndBattleText"] = "Oh! Brutto\ncavernicolo!",
  ["_Route13Beauty2AfterBattleText"] = "Non so nulla di\nPOKéMON. Mi\vpiacciono solo\nquelli fighi!",
  ["_Route13Beauty2BattleText"] = "Vuoi POKéMONIzzare\ncon me?",
  ["_Route13Beauty2EndBattleText"] = "é gia'\nfinito?",
  ["_Route13BikerAfterBattleText"] = "Sparisci!",
  ["_Route13BikerBattleText"] = "Che guardi?",
  ["_Route13BikerEndBattleText"] = "\nAccidenti! Marce\vsgranate!",
  ["_Route13CooltrainerF1AfterBattleText"] = "Voglio diventare\nun bravo\vallenatore. Mi\nallenero' duro.",
  ["_Route13CooltrainerF1BattleText"] = "Dicono che me la\ncavaimo per la\vmia eta'!",
  ["_Route13CooltrainerF1EndBattleText"] = "Ohh!\nHo perso!",
  ["_Route13CooltrainerF2AfterBattleText"] = "So che hai preso\nquelle MEDAGLIE\vdai CAPIPALESTRA.",
  ["_Route13CooltrainerF2BattleText"] = "Wow! Che figate le\ntue MEDAGLIE!",
  ["_Route13CooltrainerF2EndBattleText"] = "Non\nbasta!",
  ["_Route13CooltrainerF3AfterBattleText"] = "Devi far lottare i\nPOKéMON per\vrenderli piu'\nforti!",
  ["_Route13CooltrainerF3BattleText"] = "I miei cari\nPOKéMON vogliono\vfare la tua\nconoscenza.",
  ["_Route13CooltrainerF3EndBattleText"] = "Wow!\nHai vinto alla\vgrande!",
  ["_Route13CooltrainerF4AfterBattleText"] = "CALCIO ha\naumentato la\vVELOCITA' dei miei\nPOKéMON.",
  ["_Route13CooltrainerF4BattleText"] = "Ho trovato CALCIO\nin una grotta.",
  ["_Route13CooltrainerF4EndBattleText"] = "Che\nsbaglio!",
  ["_Route13CooltrainerM1AfterBattleText"] = "I miei POKéMON\nsembrano felici,\vnonostante abbiano\nperso.",
  ["_Route13CooltrainerM1BattleText"] = "I miei POKéMON\nvolatili vogliono\vfare a botte!",
  ["_Route13CooltrainerM1EndBattleText"] = "La\nmia combo alata\vha perso?",
  ["_Route13CooltrainerM2AfterBattleText"] = "Sono esausto.\nCredo che volero'\va casa.",
  ["_Route13CooltrainerM2BattleText"] = "Il vento spira\ndalla mia parte!",
  ["_Route13CooltrainerM2EndBattleText"] = "Il\nvento é cambiato!",
  ["_Route13CooltrainerM3AfterBattleText"] = "Vorrei volare come\nPIDGEY e\vPIDGEOTTO...",
  ["_Route13CooltrainerM3BattleText"] = "Io scelgo sempre i\nPOKéMON volatili!",
  ["_Route13CooltrainerM3EndBattleText"] = "\nEnergia esaurita!",
  ["_Route13SignText"] = "PERCORSO 13 Nord\nper PONTE\vSILENZIO",
  ["_Route13TrainerTips1Text"] = "CONSIGLI AGLI\nALLENATORI\vGuarda a sinistra\ndi quel palo!",
  ["_Route13TrainerTips2Text"] = "CONSIGLI AGLI\nALLENATORI\vUsa SELECT per\ninvertire gli\voggetti nello\nzaino!",
  ["_Route14Biker1AfterBattleText"] = "Che c'é, che c'é?\nChe cosa vuoi?",
  ["_Route14Biker1BattleText"] = "Forza, forza.\nAndiamo, andiamo,\vandiamo!",
  ["_Route14Biker1EndBattleText"] = "Argh!\nPerso! Sparisci!",
  ["_Route14Biker2AfterBattleText"] = "Allevare POKéMON é\nuna noia mortale.",
  ["_Route14Biker2BattleText"] = "Perfetto! Devo far\npassare il tempo!",
  ["_Route14Biker2EndBattleText"] = "Cosa?\nTu!?",
  ["_Route14Biker3AfterBattleText"] = "é forte aver reso\ni tuoi POKéMON\vcosi' potenti! La\nforza comanda! E\vlo sai!",
  ["_Route14Biker3BattleText"] = "Gareggiamo qui\nperché c'é piu'\vspazio!",
  ["_Route14Biker3EndBattleText"] = "Spazzati\nvia!",
  ["_Route14Biker4AfterBattleText"] = "Chissa' chi\nvincerebbe tra te\ve me, uno contro\nuno!",
  ["_Route14Biker4BattleText"] = "Lotta POKéMON? Che\nfigata! Rissai!",
  ["_Route14Biker4EndBattleText"] = "Spazzato\nvia!",
  ["_Route14CooltrainerM1AfterBattleText"] = "Hai delle MN,\nvero? I POKéMON\vnon possono mai\ndimenticare\vquelle mosse.",
  ["_Route14CooltrainerM1BattleText"] = "Devi usare le MT\nper insegnare\vmosse forti ai\nPOKéMON!",
  ["_Route14CooltrainerM1EndBattleText"] = "Non\nbasta!",
  ["_Route14CooltrainerM2AfterBattleText"] = "Devono imparare\nmosse migliori.",
  ["_Route14CooltrainerM2BattleText"] = "I miei POKéMON\nvolatili sono\vpronti per la\nbattaglia.",
  ["_Route14CooltrainerM2EndBattleText"] = "Non\nancora pronti!",
  ["_Route14CooltrainerM3AfterBattleText"] = "Insegna ai POKéMON\nmosse dello\vstesso tipo per\nrenderli piu'\vpotenti.",
  ["_Route14CooltrainerM3BattleText"] = "Le MT sono in\nvendita a\vAZZURROPOLI! Ma\npochi hanno le\vMN!",
  ["_Route14CooltrainerM3EndBattleText"] = "Ahi,\nche sfortuna!",
  ["_Route14CooltrainerM4AfterBattleText"] = "I POKéMON volatili\nsono il mio\vamore!",
  ["_Route14CooltrainerM4BattleText"] = "Hai insegnato ai\ntuoi POKéMON\vvolatili come\nusare VOLO?",
  ["_Route14CooltrainerM4EndBattleText"] = "\nAbbattuto in\vfiamme!",
  ["_Route14CooltrainerM5AfterBattleText"] = "I 3 POKéMON\nleggendari sono\vtutti rapaci.",
  ["_Route14CooltrainerM5BattleText"] = "Hai mai sentito\nparlare dei\vPOKéMON\nleggendari?",
  ["_Route14CooltrainerM5EndBattleText"] = "\nPerché? Perché ho\vperso?",
  ["_Route14CooltrainerM6AfterBattleText"] = "Vincere o perdere,\nalla fine non\vconta nulla!",
  ["_Route14CooltrainerM6BattleText"] = "Non ne ho voglia,\nma OK! Andiamo!",
  ["_Route14CooltrainerM6EndBattleText"] = "Lo\nsapevo!",
  ["_Route14SignText"] = "PERCORSO 14 Ovest\nper FUCSIAPOLI",
  ["_Route15Beauty1AfterBattleText"] = "Ti perdono! Posso\nincassare!",
  ["_Route15Beauty1BattleText"] = "Oh, che carino che\nsei!",
  ["_Route15Beauty1EndBattleText"] = "Sembravi\ncosi' carino!",
  ["_Route15Beauty2AfterBattleText"] = "Mi piace tornare a\ncasa per stare\vcon i miei\nPOKéMON!",
  ["_Route15Beauty2BattleText"] = "Allevo POKéMON\nperché vivo da\vsola!",
  ["_Route15Beauty2EndBattleText"] = "Non l'avevo\nchiesto!",
  ["_Route15Biker1AfterBattleText"] = "Si vive una volta\nsola, percio'\vfaccio il\nfuorilegge! IL\vTEAM ROCKET\nCOMANDA!",
  ["_Route15Biker1BattleText"] = "Ehi ragazzo!\nForza! Li ho\vappena presi!",
  ["_Route15Biker1EndBattleText"] = "Perché\nno?",
  ["_Route15Biker2AfterBattleText"] = "Stavo solo\nscherzando sui\vsoldi!",
  ["_Route15Biker2BattleText"] = "Sborsa tutti i\ntuoi soldi quando\vperdi con me,\npivello!",
  ["_Route15Biker2EndBattleText"] = "Non puo'\nessere vero!",
  ["_Route15CooltrainerF1AfterBattleText"] = "Non puoi cambiare\nil soprannome dei\vPOKéMON scambiati.\nSolo l'Allenatore\vOriginale puo'.",
  ["_Route15CooltrainerF1BattleText"] = "Fammi provare il\nPOKéMON che ho\vappena scambiato!",
  ["_Route15CooltrainerF1EndBattleText"] = "Non\nbasta!",
  ["_Route15CooltrainerF2AfterBattleText"] = "Ho paura dei\nCENTAURI , sono\vcosi' brutti e\ncattivi!",
  ["_Route15CooltrainerF2BattleText"] = "Tu hai una faccia\ngentile, credo di\vpoterti battere!",
  ["_Route15CooltrainerF2EndBattleText"] = "No,\nsbagliato!",
  ["_Route15CooltrainerF3AfterBattleText"] = "Scambio POKéMON\ncon i miei amici!",
  ["_Route15CooltrainerF3BattleText"] = "Che c'é di figo?\nScambiare\vPOKéMON!",
  ["_Route15CooltrainerF3EndBattleText"] = "Ho\ndetto scambio!",
  ["_Route15CooltrainerF4AfterBattleText"] = "Vado ad allenarmi\ncon persone meno\vforti.",
  ["_Route15CooltrainerF4BattleText"] = "Vuoi giocare con i\nmiei POKéMON?",
  ["_Route15CooltrainerF4EndBattleText"] = "Ero\ntroppo\vimpaziente!",
  ["_Route15CooltrainerM1AfterBattleText"] = "Forse non sono\nportato per le\vlotte.",
  ["_Route15CooltrainerM1BattleText"] = "Quando fischio,\nposso chiamare i\vPOKéMON volatili!",
  ["_Route15CooltrainerM1EndBattleText"] = "Ahi!\nChe tragico!",
  ["_Route15CooltrainerM2AfterBattleText"] = "Sapevi che mosse\ncome TERREMOTO\vnon hanno alcun\neffetto sui\vvolatili?",
  ["_Route15CooltrainerM2BattleText"] = "Hmm? I miei\nvolatili tremano!\vTu ci sai fare,\neh?",
  ["_Route15CooltrainerM2EndBattleText"] = "\nProprio come\vpensavo!",
  ["_Route15Gate1FGuardText"] = "Stai completando\nil POKéDEX?\vL'AIUTANTE DEL\nPROF. OAK é\vpassato di qui.",
  ["_Route15Gate2FBinocularsText"] = "Hai guardato nei\nbinocoli. Sembra\vuna piccola isola!",
  ["_Route15Gate2FOaksAideExpAllText"] = "CONDPIENA da'\nPunti ESP a tutti\vi POKéMON con te,\nanche se non\vlottano. Tuttavia,\nriduce la\vquantita' di ESP\nper ciascun\vPOKéMON. Se non ti\nserve, deponila\vtramite PC.",
  ["_Route15SignText"] = "PERCORSO 15 Ovest\nper FUCSIAPOLI",
  ["_Route15UpstairsBinocularsText"] = "Hai guardato nei\nbinocoli... Un\vgrosso uccello\nlucente vola\vverso il mare.",
  ["_Route16Biker1AfterBattleText"] = "Ci piace\nciondolare qui,\vche c'é?",
  ["_Route16Biker1BattleText"] = "Che cosa vuoi?",
  ["_Route16Biker1EndBattleText"] = "Non\nosare ridere!",
  ["_Route16Biker2AfterBattleText"] = "Lascia stare, chi\nvuole la tua\vBICI!",
  ["_Route16Biker2BattleText"] = "Che bella BICI!\nFatti sotto!",
  ["_Route16Biker2EndBattleText"] = "Fuori\ncombattimento!",
  ["_Route16Biker3AfterBattleText"] = "Odio perdere!\nSparisci dalla\vmia vista!",
  ["_Route16Biker3BattleText"] = "Vieni fuori a\ngiocare,\vtopolino!",
  ["_Route16Biker3EndBattleText"] = "Brutto\nratto!",
  ["_Route16Biker4AfterBattleText"] = "Puoi arrivare a\nFUCSIAPOLI da\vAZZURROPOLI usando\nla strada\vcostiera.",
  ["_Route16Biker4EndBattleText"] = "Kaboom!",
  ["_Route16Biker5AfterBattleText"] = "Mi piacciono i\nPOKéMON feroci!\vFanno a pezzi i\nnemici!",
  ["_Route16Biker5BattleText"] = "Ho una fame da\nlupi e sono\vcattivo!",
  ["_Route16Biker5EndBattleText"] = "Male,\nmale, male!",
  ["_Route16Biker6AfterBattleText"] = "Mi piace molestare\nla gente con i\vmiei feroci\nPOKéMON!",
  ["_Route16Biker6BattleText"] = "Certo, vengo!",
  ["_Route16Biker6EndBattleText"] = "Non\nfarmi arrabbiare!",
  ["_Route16CyclingRoadSignText"] = "Goditi la discesa!\nPISTA CICLABILE",
  ["_Route16FlyHouseBrunetteGirlHM02ExplanationText"] = "MN02 contiene\nVOLO. Ti\vriportera' in\nqualsiasi citta'.\vSfruttala al\nmeglio!",
  ["_Route16FlyHouseBrunetteGirlHM02NoRoomText"] = "Non hai abbastanza\nspazio per\vquesto.",
  ["_Route16FlyHouseBrunetteGirlReceivedHM02Text"] = "{PLAYER} riceve\nMN02!",
  ["_Route16FlyHouseBrunetteGirlText"] = "Oh, hai trovato il\nmio rifugio\vsegreto! Ti prego,\nnon dire a\vnessuno che sono\nqui. Ti faro' un\vregalo per farti\nperdonare!",
  ["_Route16FlyHouseFearowText"] = "FEAROW: Kyueen!",
  ["_Route16Gate1FGamblerText"] = "Come sei entrato?\nBuon impegno!",
  ["_Route16Gate1FGuardCyclingRoadExplanationText"] = "La PISTA CICLABILE\né una discesa sul\vmare. é una corsa\nfantastica.",
  ["_Route16Gate1FGuardNoPedestriansAllowedText"] = "I pedoni non sono\nammessi sulla\vPISTA CICLABILE!",
  ["_Route16Gate1FGuardWaitUpText"] = "Ehi tu! Aspetta,\nper favore!",
  ["_Route16Gate2FLeftBinocularsText"] = "Hai guardato nei\nbinocoli. é il\vCENTRO\nCOMMERCIALE!",
  ["_Route16Gate2FLittleBoyText"] = "Vado a fare un\ngiro con la mia\vragazza!",
  ["_Route16Gate2FLittleGirlText"] = "Andiamo a fare un\ngiro insieme!",
  ["_Route16Gate2FRightBinocularsText"] = "Hai guardato nei\nbinocoli. C'é un\vlungo sentiero\nsull'acqua!",
  ["_Route16SignText"] = "PERCORSO 16\nAZZURROPOLI\vFUCSIAPOLI",
  ["_Route16SnorlaxReturnedToMountainsText"] = "Con un grande\nsbadiglio,\vSNORLAX é tornato\nsui monti!",
  ["_Route16SnorlaxWokeUpText"] = "SNORLAX si é\nsvegliato! Ha\vsferrato un\nattacco furioso!",
  ["_Route16Text7"] = "Un POKéMON\ndormiente blocca\vla via!",
  ["_Route16biker4BattleText"] = "Ehi, mi hai appena\nurtato!",
  ["_Route17Biker10AfterBattleText"] = "Mi devo riposare!",
  ["_Route17Biker10BattleText"] = "Vattene ragazzo!\nSono distrutto!",
  ["_Route17Biker10EndBattleText"] = "Sei\nsoddisfatto?",
  ["_Route17Biker1AfterBattleText"] = "Ci sono begli\noggetti giu'\vsulla PISTA\nCICLABILE!",
  ["_Route17Biker1BattleText"] = "Non ci sono soldi\na battere i\vragazzini!",
  ["_Route17Biker1EndBattleText"] = "Spento\nfuori!",
  ["_Route17Biker2AfterBattleText"] = "Potrei\nscaraventarti\vfuori di qui con\nuna panciata!",
  ["_Route17Biker2BattleText"] = "Che vuoi, pivello?",
  ["_Route17Biker2EndBattleText"] = "Urca!",
  ["_Route17Biker3AfterBattleText"] = "Adoro correre in\ndiscesa!",
  ["_Route17Biker3BattleText"] = "Vai a FUCSIAPOLI?",
  ["_Route17Biker3EndBattleText"] = "\nSchiantato e\vbruciato!",
  ["_Route17Biker4AfterBattleText"] = "Cerchi avventure?",
  ["_Route17Biker4BattleText"] = "Siamo CENTAURI!\nStelle della\vstrada!",
  ["_Route17Biker4EndBattleText"] = "Fumato!",
  ["_Route17Biker5AfterBattleText"] = "Ho preso il mio\nVOLTORB alla\vCENTRALE\nABANDONATA.",
  ["_Route17Biker5BattleText"] = "Lascia che VOLTORB\nti fulmini!",
  ["_Route17Biker5EndBattleText"] = "Messo al\ntappeto!",
  ["_Route17Biker6AfterBattleText"] = "Forse alcuni\nPOKéMON hanno\vbisogno di PIETRE\nper evolversi.",
  ["_Route17Biker6BattleText"] = "I miei POKéMON non\nsi evolvono!\vPerché?",
  ["_Route17Biker6EndBattleText"] = "Ma\nguarda te!",
  ["_Route17Biker7AfterBattleText"] = "Scommetto che ho\nperso peso qui!",
  ["_Route17Biker7BattleText"] = "Ho bisogno di un\npo' di esercizio!",
  ["_Route17Biker7EndBattleText"] = "Uff! Bel\nallenamento!",
  ["_Route17Biker8AfterBattleText"] = "Preparati a\nlottare per le\vtue idee!",
  ["_Route17Biker8BattleText"] = "Fai il ribelle!",
  ["_Route17Biker8EndBattleText"] = "Aaaargh!",
  ["_Route17Biker9AfterBattleText"] = "La discesa rende\ndifficile\vsterzare!",
  ["_Route17Biker9BattleText"] = "Bella BICI! Come\nsi guida?",
  ["_Route17Biker9EndBattleText"] = "\nAcciderboli!",
  ["_Route17CyclingRoadEndsSignText"] = "PISTA CICLABILE La\npendenza finisce\vqui!",
  ["_Route17NoticeSign1Text"] = "é un avviso!\nAttenzione agli\voggetti scartati!",
  ["_Route17NoticeSign2Text"] = "é un avviso! Non\nbuttare la\vpartita, butta le\nPOKé BALL!",
  ["_Route17SignText"] = "PERCORSO 17\nAZZURROPOLI\vFUCSIAPOLI",
  ["_Route17TrainerTips1Text"] = "CONSIGLI AGLI\nALLENATORI\vTutti iPOKéMON\nsono unici. Anche\vquelli dello\nstesso tipo e\vlivello crescono\ncon ritmi\vdiversi.",
  ["_Route17TrainerTips2Text"] = "CONSIGLI AGLI\nALLENATORI\vPremi il Pulsante\nA o B per restare\vfermo sulla\npendenza.",
  ["_Route18CooltrainerM1AfterBattleText"] = "Vorrei tanto una\nBICI!",
  ["_Route18CooltrainerM1BattleText"] = "Controllo sempre\nogni zona erbosa\vper nuovi POKéMON.",
  ["_Route18CooltrainerM1EndBattleText"] = "Tch!",
  ["_Route18CooltrainerM2AfterBattleText"] = "Nei fine settimana\nraccolgo anche\vPOKéMON marini!",
  ["_Route18CooltrainerM2BattleText"] = "Kurukkoo! Ti piace\nil mio verso da\vuccello?",
  ["_Route18CooltrainerM2EndBattleText"] = "\nDovevo proprio\vscocciarti!",
  ["_Route18CooltrainerM3AfterBattleText"] = "Questo é il mio\nposto preferito\vper la caccia ai\nPOKéMON!",
  ["_Route18CooltrainerM3BattleText"] = "Questo é il mio\nterritorio! Fuori\vdi qui!",
  ["_Route18CooltrainerM3EndBattleText"] = "\nAcciderboli!",
  ["_Route18CyclingRoadSignText"] = "PISTA CICLABILE\nVietato l'accesso\vai pedoni!",
  ["_Route18Gate1FGuardCyclingRoadUphillText"] = "Da qui in poi la\nPISTA CICLABILE é\vtutta in salita.",
  ["_Route18Gate1FGuardExcuseMeText"] = "Ehi tu!",
  ["_Route18Gate1FGuardYouNeedABicycleText"] = "Ti serve una\nBICICLETTA per la\vPISTA CICLABILE!",
  ["_Route18Gate2FLeftBinocularsText"] = "Hai guardato nei\nbinocoli.\vBIANCAVILLA é a\novest!",
  ["_Route18Gate2FRightBinocularsText"] = "Hai guardato nei\nbinocoli. Ci sono\vpersone che\nnuotano!",
  ["_Route18SignText"] = "PERCORSO 18\nAZZURROPOLI\vFUCSIAPOLI",
  ["_Route19CooltrainerM1AfterBattleText"] = "Grazie, ragazzo!\nSono pronto per\vuna nuotata!",
  ["_Route19CooltrainerM1BattleText"] = "Devo scaldarmi\nprima di nuotare!",
  ["_Route19CooltrainerM1EndBattleText"] = "\nTutto riscaldato!",
  ["_Route19CooltrainerM2AfterBattleText"] = "Attenzione ai\nTENTACOOL!",
  ["_Route19CooltrainerM2BattleText"] = "Aspetta! Ti viene\nun attacco\vcardiaco!",
  ["_Route19CooltrainerM2EndBattleText"] = "Ooh!\nChe gelido!",
  ["_Route19SignText"] = "PERCORSO MARINO 19\nFUCSIAPOLI ISOLE\vSPUMA",
  ["_Route19Swimmer1AfterBattleText"] = "Posso battere i\nPOKéMON a nuoto!",
  ["_Route19Swimmer1BattleText"] = "Adoro nuotare! E\ntu?",
  ["_Route19Swimmer1EndBattleText"] = "Tuffo a\npancia!",
  ["_Route19Swimmer2AfterBattleText"] = "Vedo un paio di\nisole!",
  ["_Route19Swimmer2BattleText"] = "Cosa c'é oltre\nl'orizzonte?",
  ["_Route19Swimmer2EndBattleText"] = "Glub!",
  ["_Route19Swimmer3AfterBattleText"] = "Devi pescare per\ntrovare POKéMON\vmarini!",
  ["_Route19Swimmer3BattleText"] = "Ho provato ad\nimmergermi per i\vPOKéMON, ma nulla!",
  ["_Route19Swimmer3EndBattleText"] = "Aiuto!",
  ["_Route19Swimmer4AfterBattleText"] = "Guardo il mare per\ndimenticare!",
  ["_Route19Swimmer4BattleText"] = "Guardo il mare per\ndimenticare!",
  ["_Route19Swimmer4EndBattleText"] = "Ooh!\nChe trauma!",
  ["_Route19Swimmer5AfterBattleText"] = "C'é ancora molta\nstrada per le\vISOLE SPUMA.",
  ["_Route19Swimmer5BattleText"] = "Oh, adoro il tuo\nmezzo! Posso\vaverlo se vinco?",
  ["_Route19Swimmer5EndBattleText"] = "Oh! Ho\nperso!",
  ["_Route19Swimmer6AfterBattleText"] = "Il mio ragazzo\nvoleva nuotare\vfino alle ISOLE\nSPUMA.",
  ["_Route19Swimmer6BattleText"] = "Nuotare é\nfantastico! Le\vscottature no!",
  ["_Route19Swimmer6EndBattleText"] = "Che\nshock!",
  ["_Route19Swimmer7AfterBattleText"] = "Ho un crampo!\nGlub, glub...",
  ["_Route19Swimmer7BattleText"] = "Queste acque sono\ntraditrici!",
  ["_Route19Swimmer7EndBattleText"] = "Ooh!\nPericoloso!",
  ["_Route19Swimmer8AfterBattleText"] = "LAPRAS é cosi'\ngrande, ti terra'\vsicuramente\nasciutto.",
  ["_Route19Swimmer8BattleText"] = "Ho nuotato fino\nqui, ma sono\vstanco.",
  ["_Route19Swimmer8EndBattleText"] = "Sono\nesausto...",
  ["_Route1SignText"] = "PERCORSO 1\nBIANCAVILLA\vSMERALDOPOLI",
  ["_Route1Youngster1AlsoGotPokeballsText"] = "Abbiamo anche\ndelle POKé BALL\vper catturare\nPOKéMON!",
  ["_Route1Youngster1GotPotionText"] = "{PLAYER} riceve\n{RAM:wStringBuffer}!",
  ["_Route1Youngster1MartSampleText"] = "Ciao! Lavoro in un\nPOKé MARKET. é un\vnegozio utile,\nvisitalo a\vSMERALDOPOLI. Sai\nche c'é? Ti do'\vun campione!\nEccolo!",
  ["_Route1Youngster1NoRoomText"] = "Hai troppa roba\ncon te!",
  ["_Route1Youngster2Text"] = "Vedi quei\ndislivelli lungo\vla strada? é un\npo' spaventoso,\vma puoi saltare\ngiu'. Puoi\vtornare a\nBIANCAVILLA piu'\vrapidamente in\nquel modo.",
  ["_Route20CooltrainerMAfterBattleText"] = "I miei uccelli non\npossono portarmi\vindietro con VOLO!",
  ["_Route20CooltrainerMBattleText"] = "Sono arrivato qui\nin sella al mio\vPOKéMON volatile!",
  ["_Route20CooltrainerMEndBattleText"] = "Oh\nno!",
  ["_Route20SeafoamIslandsSignText"] = "ISOLE SPUMA",
  ["_Route20Swimmer1AfterBattleText"] = "Vorrei tanto\ncavalcare i\vPOKéMON.",
  ["_Route20Swimmer1BattleText"] = "Qui l'acqua é\nbassa.",
  ["_Route20Swimmer1EndBattleText"] = "Splash!",
  ["_Route20Swimmer2AfterBattleText"] = "C'é un'enorme\ncaverna sotto\vquest'isola.",
  ["_Route20Swimmer2BattleText"] = "SPUMA é un rifugio\ntranquillo!",
  ["_Route20Swimmer2EndBattleText"] = "Smetti!",
  ["_Route20Swimmer3AfterBattleText"] = "Vuoi galleggiare\ncon me?",
  ["_Route20Swimmer3BattleText"] = "Adoro galleggiare\ninsieme ai pesci!",
  ["_Route20Swimmer3EndBattleText"] = "Ahi!",
  ["_Route20Swimmer4AfterBattleText"] = "Una volta SPUMA\nera un'isola\vsola!",
  ["_Route20Swimmer4BattleText"] = "Sei in vacanza\nanche tu?",
  ["_Route20Swimmer4EndBattleText"] = "Nessuna\npieta'!",
  ["_Route20Swimmer5AfterBattleText"] = "Avrei dovuto\nallenare i\vPOKéMON, non me\nstesso!",
  ["_Route20Swimmer5BattleText"] = "Guarda il mio\nfisico bestiale!",
  ["_Route20Swimmer5EndBattleText"] = "\nImbranato!",
  ["_Route20Swimmer6AfterBattleText"] = "Cavalcare un\nPOKéMON sembra\vproprio forte!",
  ["_Route20Swimmer6BattleText"] = "Perché cavalchi un\nPOKéMON? Non sai\vnuotare?",
  ["_Route20Swimmer6EndBattleText"] = "Ahi!\nSilurato!",
  ["_Route20Swimmer7AfterBattleText"] = "Le mie perle\nverranno piu'\vgrandi dentro\nCLOYSTER?",
  ["_Route20Swimmer7BattleText"] = "Il mio ragazzo mi\nha dato grandi\vperle!",
  ["_Route20Swimmer7EndBattleText"] = "Non\ntoccare le mie\vperle!",
  ["_Route20Swimmer8AfterBattleText"] = "I POKéMON hanno\noccupato una\vvilla abbandonata\na ISOLA CANNELLA!",
  ["_Route20Swimmer8BattleText"] = "Ho nuotato fino a\nqui da ISOLA\vCANNELLA!",
  ["_Route20Swimmer8EndBattleText"] = "Sono\ncosi' deluso!",
  ["_Route20Swimmer9AfterBattleText"] = "CANNELLA é\nun'isola\vvulcanica!",
  ["_Route20Swimmer9BattleText"] = "CANNELLA, a ovest,\nha un LABORATORIO\vper POKéMON.",
  ["_Route20Swimmer9EndBattleText"] = "\nAspetta!",
  ["_Route21Fisher1AfterBattleText"] = "Non riesco a\nprendere niente\vdi buono!",
  ["_Route21Fisher1BattleText"] = "Vuoi sapere se i\npesci abboccano?",
  ["_Route21Fisher1EndBattleText"] = "\nAccidenti!",
  ["_Route21Fisher2AfterBattleText"] = "Sembra che io\npeschi solo\vMAGIKARP!",
  ["_Route21Fisher2BattleText"] = "Ho fatto un grosso\nbottino! Ci\vprovi?",
  ["_Route21Fisher2EndBattleText"] = "\nMaledetti\vMAGIKARP!",
  ["_Route21Fisher3AfterBattleText"] = "Ero solo\narrabbiato perché\vnon riuscivo a\nprendere nulla.",
  ["_Route21Fisher3BattleText"] = "Ehi, non\nspaventare i\vpesci!",
  ["_Route21Fisher3EndBattleText"] = "Scusa!\nNon volevo!",
  ["_Route21Fisher4AfterBattleText"] = "Oh aspetta! Ha\nabboccato!\vEvviva!",
  ["_Route21Fisher4BattleText"] = "Tienimi compagnia\nfinché non prendo\vqualcosa!",
  ["_Route21Fisher4EndBattleText"] = "Questo\nha fatto passare\vil tempo.",
  ["_Route21Swimmer1AfterBattleText"] = "Mi piacciono anche\ni monti!",
  ["_Route21Swimmer1BattleText"] = "Il mare purifica\nil mio corpo e\vl'anima!",
  ["_Route21Swimmer1EndBattleText"] = "Ayah!",
  ["_Route21Swimmer2AfterBattleText"] = "A chi assomiglio?\nA un salvagente\vbucato? Sparisci!",
  ["_Route21Swimmer2BattleText"] = "Cosa c'é che non\nva se nuoto?",
  ["_Route21Swimmer2EndBattleText"] = "Colpo\nbasso!",
  ["_Route21Swimmer3AfterBattleText"] = "Dove hai catturato\ni tuoi POKéMON?",
  ["_Route21Swimmer3BattleText"] = "Ho catturato tutti\ni miei POKéMON in\vmare!",
  ["_Route21Swimmer3EndBattleText"] = "Sub!!\nGiu'!!",
  ["_Route21Swimmer4AfterBattleText"] = "Sono esausto! Ma\nmi restano la\vgara di bici e la\nmaratona!",
  ["_Route21Swimmer4BattleText"] = "Ora sono impegnato\nin un triathlon!",
  ["_Route21Swimmer4EndBattleText"] = "\nAnsimante...\vansimante...",
  ["_Route21Swimmer5AfterBattleText"] = "Sono cotto al\nsole!",
  ["_Route21Swimmer5BattleText"] = "Ahh! Senti il sole\ne il vento!",
  ["_Route21Swimmer5EndBattleText"] = "Ahi! Ho\nperso!",
  ["_Route22GateGuardGoRightAheadText"] = "Oh! Quella é la\nMEDAGLIA SASSO!\vPrendi pure!",
  ["_Route22GateGuardICantLetYouPassText"] = "Le regole sono\nregole. Non posso\vlasciarti passare.",
  ["_Route22GateGuardNoBoulderbadgeText"] = "Solo i veri abili\nallenatori\vpossono passare.\nNon hai ancora la\vMEDAGLIA SASSO!",
  ["_Route22PokemonLeagueSignText"] = "LEGA POKéMON\nIngresso\vPrincipale",
  ["_Route22Rival1DefeatedText"] = "\nAcciderbolina!\vHai avuto solo\nfortuna!",
  ["_Route22Rival1VictoryText"] = "{RIVAL}: Cosa?\nPerché ho 2\vPOKéMON? Dovresti\ncatturarne altri\vanche tu!",
  ["_Route22Rival2DefeatedText"] = "Cosa!?\nSono stato solo\vdisattento!",
  ["_Route22Rival2VictoryText"] = "{RIVAL}: Hahaha!\n{PLAYER}! é il tuo\vmeglio? Non vali\nun tubo, amico!\vVa ad allenarti\nancora! Perdente!",
  ["_Route22RivalAfterBattleText1"] = "Ho\nsentito che la\vLEGA POKéMON ha\nmolti allenatori\vforti! Devo capire\ncome superarli!\vSmettila di\nciondolare e\vdatti una mossa!",
  ["_Route22RivalAfterBattleText2"] = "Questo mi\nha sganciato!\vSono pronto per la\nLEGA POKéMON!\v{PLAYER}, ti serve\npiu' pratica! Ma\vlo sai anche tu!\nMe ne vado. Ci si\vvede!",
  ["_Route22RivalBeforeBattleText1"] = "{RIVAL}: Ehi!\n{PLAYER}! Vai alla\vLEGA POKéMON?\nScordatelo!\vProbabilmente non\nhai MEDAGLIE! La\vguardia non ti\nfara' passare! A\vproposito, i tuoi\nPOKéMON sono\vdiventati piu'\nforti?",
  ["_Route22RivalBeforeBattleText2"] = "{RIVAL}: Cosa?\n{PLAYER}! Che\vsorpresa vederti\nqui! Quindi vai\valla LEGA POKéMON?\nHai raccolto\vanche tutte le\nMEDAGLIE? Forte!\vAllora ti concero'\nper le feste\v{PLAYER} come\nriscaldamento per\vla LEGA! Vieni\navanti!",
  ["_Route23GoRightAheadText"] = "Bene allora!\nPrendi pure!",
  ["_Route23OhThatIsTheBadgeText"] = "Puoi passare solo\nse hai con te\v{RAM:wNameBuffer}! Oh!\nQuella é\v{RAM:wNameBuffer}!",
  ["_Route23VictoryRoadGateSignText"] = "Varco della Via\nVittoria - LEGA\vPOKéMON",
  ["_Route23YouDontHaveTheBadgeYetText"] = "Puoi passare solo\nse hai con te\v{RAM:wNameBuffer}! Non\nhai ancora\v{RAM:wNameBuffer}! Devi\naverla per\vraggiungere la\nLEGA POKéMON!",
  ["_Route24CooltrainerF1AfterBattleText"] = "Ce l'ho messa\ntutta, non ho\vrimpianti!",
  ["_Route24CooltrainerF1BattleText"] = "Sono la n. 4! Ti\nstai stancando?",
  ["_Route24CooltrainerF1EndBattleText"] = "Ho\nperso anche io!",
  ["_Route24CooltrainerF2AfterBattleText"] = "Ce l'ho messa\ntutta, non ho\vrimpianti!",
  ["_Route24CooltrainerF2BattleText"] = "Sono la seconda!\nOra si fa sul\vserio!",
  ["_Route24CooltrainerF2EndBattleText"] = "Come\nho potuto\vperdere?",
  ["_Route24CooltrainerM1DefeatedText"] = "Arrgh! Ci sai\nfare!",
  ["_Route24CooltrainerM1JoinTeamRocketText"] = "A proposito, ti\nandrebbe di\ventrare nel TEAM\nROCKET? Siamo un\vgruppo dedicato al\nmale grazie ai\vPOKéMON! Vuoi\nunirti? Sei\vsicuro? Forza,\nunisciti a noi!\vTi sto dicendo di\nunirti! OK, hai\vbisogno di\nconvinzione! Ti\vfaro' un'offerta\nche non potrai\vrifiutare!",
  ["_Route24CooltrainerM1NoRoomText"] = "Non hai abbastanza\nspazio!",
  ["_Route24CooltrainerM1ReceivedNuggetText"] = "{PLAYER} riceve\n{RAM:wStringBuffer}!",
  ["_Route24CooltrainerM1YouBeatOurContestText"] = " ",
  ["_Route24CooltrainerM1YouCouldBecomeATopLeaderText"] = "Con le tue\ncapacita'\vpotresti diventare\nun capo nel TEAM\vROCKET!",
  ["_Route24CooltrainerM1YouJustEarnedAPrizeText"] = "Hai appena vinto\nun premio\vfavoloso!",
  ["_Route24CooltrainerM2AfterBattleText"] = "Mi sono nascosto\nperché la gente\vsul ponte mi\nspaventava!",
  ["_Route24CooltrainerM2BattleText"] = "Ho visto la tua\nimpresa\vdall'erba!",
  ["_Route24CooltrainerM2EndBattleText"] = "Non\ncredevo!",
  ["_Route24CooltrainerM3AfterBattleText"] = "Ce l'ho messa\ntutta, non ho\vrimpianti!",
  ["_Route24CooltrainerM3BattleText"] = "OK! Sono il n. 5!\nTi faro' a pezzi!",
  ["_Route24CooltrainerM3EndBattleText"] = "\nUrca! Troppo\vforte!",
  ["_Route24Youngster1AfterBattleText"] = "Ce l'ho messa\ntutta, non ho\vrimpianti!",
  ["_Route24Youngster1BattleText"] = "Ecco il n. 3! Non\nsaro' un osso\vfacile!",
  ["_Route24Youngster1EndBattleText"] = "Ahi!\nSchiacciato al\vsuolo!",
  ["_Route24Youngster2AfterBattleText"] = "Ce\nl'ho messa tutta,\vnon ho rimpianti!",
  ["_Route24Youngster2BattleText"] = "\nQuesto é il PONTE\vNUGGET! Batti 5 di\nnoi e vinci un\vpremio favoloso!\nPensi di farcela?",
  ["_Route24Youngster2EndBattleText"] = "\nUrca! Roba forte!",
  ["_Route25BillSignText"] = "VILLA MARINA Qui\nabita BILL",
  ["_Route25CooltrainerF1AfterBattleText"] = "Vorrei che il mio\nragazzo fosse\vbravo come te!",
  ["_Route25CooltrainerF1BattleText"] = "Ciao! Il mio\nragazzo é un\vfigo!",
  ["_Route25CooltrainerF1EndBattleText"] = "Ero\nin cattive\vcondizioni!",
  ["_Route25CooltrainerF2AfterBattleText"] = "Vieni dal MONTE\nLUNA? Posso avere\vun CLEFAIRY?",
  ["_Route25CooltrainerF2BattleText"] = "Il mio amico ha un\nPOKéMON carino.\vChe invidia!",
  ["_Route25CooltrainerF2EndBattleText"] = "Non\nsono cosi'\vinvidiosa!",
  ["_Route25CooltrainerMAfterBattleText"] = "Pazienza. La mia\nragazza mi\vconsolera'.",
  ["_Route25CooltrainerMBattleText"] = "Sono un tipo\nforte. Ho una\vragazza!",
  ["_Route25CooltrainerMEndBattleText"] = "Ahi,\naccidenti...",
  ["_Route25Hiker1AfterBattleText"] = "Acciderboli! Uno\nZUBAT mi ha morso\vlaggiu'.",
  ["_Route25Hiker1BattleText"] = "Vengo giu' dal\nMONTE LUNA, ma\vsono pronto!",
  ["_Route25Hiker1EndBattleText"] = "Ti sei\nimpegnato duro!",
  ["_Route25Hiker2AfterBattleText"] = "Il collezionista\nha moltissimi\vPOKéMON rari.",
  ["_Route25Hiker2BattleText"] = "Vado a trovare un\ncollezionista di\vPOKéMON al capo!",
  ["_Route25Hiker2EndBattleText"] = "Mi hai\npreso.",
  ["_Route25Hiker3AfterBattleText"] = "Il sentiero in\nbasso é una\vscorciatoia per\nCELESTOPOLI.",
  ["_Route25Hiker3BattleText"] = "Vai a trovare\nBILL? Prima\vlottiamo!",
  ["_Route25Hiker3EndBattleText"] = "Ci sai\nproprio fare.",
  ["_Route25Youngster1AfterBattleText"] = "Tutti i POKéMON\nhanno debolezze.\vé meglio allevarne\ndi vari tipi.",
  ["_Route25Youngster1BattleText"] = "Gli allenatori\nlocali vengono\vqui ad allenarsi!",
  ["_Route25Youngster1EndBattleText"] = "Te la cavi.",
  ["_Route25Youngster2AfterBattleText"] = "Sulla M.N. ANNA ho\nvisto allenatori\vdi tutto il mondo.",
  ["_Route25Youngster2BattleText"] = "Mio padre mi ha\nportato a una\vfesta fantastica\nsulla M.N. ANNA a\vARANCIOPOLI!",
  ["_Route25Youngster2EndBattleText"] = "Non sono\narrabbiato!",
  ["_Route25Youngster3AfterBattleText"] = "Se il tuo POKéMON\né confuso o\vdorme,\nsostituiscilo!",
  ["_Route25Youngster3BattleText"] = "Sapevo che avrei\ndovuto lottare\vcon te!",
  ["_Route25Youngster3EndBattleText"] = "Sapevo che\navrei perso!",
  ["_Route2DiglettsCaveSignText"] = "GROTTA DIGLETT",
  ["_Route2GateOaksAideFlashExplanationText"] = "La MN FLASH\nillumina anche i\vsotterranei piu'\nbui.",
  ["_Route2GateYoungsterText"] = "Una volta che un\nPOKéMON impara\vFLASH, puoi\nattraversare la\vGROTTA DIGLETT.",
  ["_Route2SignText"] = "PERCORSO 2\nSMERALDOPOLI\vPLUMBEOPOLI",
  ["_Route2TradeHouseScientistText"] = "Un POKéMON svenuto\nnon puo' lottare.\vMa puo' ancora\nusare mosse come\vTAGLIO!",
  ["_Route3CooltrainerF1AfterBattleText"] = "Smettila di\nfissare se non\vvuoi lottare!",
  ["_Route3CooltrainerF1BattleText"] = "Mi hai guardato,\nvero?",
  ["_Route3CooltrainerF1EndBattleText"] = "Sei\nproprio cattivo!",
  ["_Route3CooltrainerF2AfterBattleText"] = "Evita le lotte non\nfacendoti vedere\vdalla gente!",
  ["_Route3CooltrainerF2BattleText"] = "Quella tua\nocchiata, é cosi'\vintrigante!",
  ["_Route3CooltrainerF2EndBattleText"] = "Sii\ngentile!",
  ["_Route3CooltrainerF3AfterBattleText"] = "Il PERCORSO 4 é ai\npiedi del MONTE\vLUNA.",
  ["_Route3CooltrainerF3BattleText"] = "Eek! Mi hai\ntoccato?",
  ["_Route3CooltrainerF3EndBattleText"] = "\nTutto qui?",
  ["_Route3SignText"] = "PERCORSO 3 MONTE\nLUNA",
  ["_Route3Text1"] = "Uff... Meglio\nriposare un\vpo'... Mh... Quel\ntunnel da\vCELESTOPOLI ti\nsfinisce!",
  ["_Route3Youngster1AfterBattleText"] = "Ci sono altri tipi\ndi POKéMON oltre\va quelli del\nbosco!",
  ["_Route3Youngster1BattleText"] = "Ehi! Ti ho visto\nnel BOSCO\vSMERALDOPOLI!",
  ["_Route3Youngster1EndBattleText"] = "Mi hai\nbattuto di nuovo!",
  ["_Route3Youngster2AfterBattleText"] = "Stai depositando i\nPOKéMON sul PC?\vOgni BOX puo'\ncontenerne 20!",
  ["_Route3Youngster2BattleText"] = "Ciao! Mi piacciono\ni pantaloncini!\vSono comodi e\nfacili da\vindossare!",
  ["_Route3Youngster2EndBattleText"] = "Non ci\nposso credere!",
  ["_Route3Youngster3AfterBattleText"] = "Se\nun BOX POKéMON\vnel PC si riempie,\npassa a un altro!",
  ["_Route3Youngster3BattleText"] = "Sei\nun allenatore?\vLottiamo!",
  ["_Route3Youngster3EndBattleText"] = "Se\navessi avuto\vnuovi POKéMON\navrei vinto!",
  ["_Route3Youngster4AfterBattleText"] = "Indosso sempre\npantaloncini,\vanche in inverno!",
  ["_Route3Youngster4BattleText"] = "Ehi! Non porti i\npantaloncini!",
  ["_Route3Youngster4EndBattleText"] = "Perso!\nPerso! Perso!",
  ["_Route3Youngster5AfterBattleText"] = "I\nPOKéMON allenati\vsono piu' forti di\nquelli selvatici!",
  ["_Route3Youngster5BattleText"] = "Puoi\nlottare contro il\vmio nuovo POKéMON!",
  ["_Route3Youngster5EndBattleText"] = "\nFatto e finito!",
  ["_Route4CooltrainerF1Text"] = "Ahi! Sono\ninciampata su un\vPOKéMON roccioso,\nGEODUDE!",
  ["_Route4CooltrainerF2AfterBattleText"] = "Forse non ci sono\naltri funghi qui.\vCredo di averli\npresi tutti.",
  ["_Route4CooltrainerF2BattleText"] = "Sono venuta a\nprendere il mio\vPOKéMON fungo!",
  ["_Route4CooltrainerF2EndBattleText"] = "Oh!\nIl mio caro\vPOKéMON fungo!",
  ["_Route4MtMoonSignText"] = "MONTE LUNA\nIngresso Tunnel",
  ["_Route4SignText"] = "PERCORSO 4 MONTE\nLUNA CELESTOPOLI",
  ["_Route5UndergroundPathSignText"] = "SOTTERRANEO\nCELESTOPOLI\vARANCIOPOLI",
  ["_Route6CooltrainerAfterBattleText"] = "Sussurro...\nsussurro...",
  ["_Route6CooltrainerF1BattleText"] = "Scusa! Questa é\nuna conversazione\vprivata!",
  ["_Route6CooltrainerF1EndBattleText"] = "Ugh!\nOdio perdere!",
  ["_Route6CooltrainerF2AfterBattleText"] = "Voglio diventare\npiu' forte! Qual\vé il tuo segreto?",
  ["_Route6CooltrainerF2BattleText"] = "Io? Beh, OK.\nGiochiamo!",
  ["_Route6CooltrainerF2EndBattleText"] = "Non\nha funzionato!",
  ["_Route6CooltrainerM1BattleText"] = "Chi c'é? Smettila\ndi origliare!",
  ["_Route6CooltrainerM1EndBattleText"] = "\nProprio non\vriesco a vincere!",
  ["_Route6CooltrainerM2AfterBattleText"] = "Dovrei portare con\nme piu' POKéMON\vper sicurezza.",
  ["_Route6CooltrainerM2BattleText"] = "Mh? Vuoi parlare\ncon me?",
  ["_Route6CooltrainerM2EndBattleText"] = "Non\nho iniziato io!",
  ["_Route6UndergroundPathSignText"] = "SOTTERRANEO\nCELESTOPOLI\vARANCIOPOLI",
  ["_Route6Youngster1AfterBattleText"] = "Mi piacciono gli\ninsetti, torno\vnel BOSCO\nSMERALDOPOLI.",
  ["_Route6Youngster1BattleText"] = "Non ci sono molti\ninsetti qui\vfuori.",
  ["_Route6Youngster1EndBattleText"] = "No!\nScherzi!",
  ["_Route6Youngster2AfterBattleText"] = "I miei POKéMON\nsono deboli? O\vsono scarso io?",
  ["_Route6Youngster2BattleText"] = "Non ti ho mai\nvisto in giro! Ci\vsai fare?",
  ["_Route6Youngster2EndBattleText"] = "Ci sai\nproprio fare!",
  ["_Route7UndergroundPathSignText"] = "SOTTERRANEO\nAZZURROPOLI\vLAVANDONIA",
  ["_Route8CooltrainerF1AfterBattleText"] = "Quando i POKéMON\ncrescono\vdiventano brutti!\nNon dovrebbero\vevolversi!",
  ["_Route8CooltrainerF1BattleText"] = "Mi piace NIDORAN,\npercio' li\vraccolgo!",
  ["_Route8CooltrainerF1EndBattleText"] = "\nPerché? Perché??",
  ["_Route8CooltrainerF2AfterBattleText"] = "Penso che PIDGEY e\nRATTATA siano\vcarini!",
  ["_Route8CooltrainerF2BattleText"] = "MEOWTH é cosi'\ncarino, miao,\vmiao, miao!",
  ["_Route8CooltrainerF2EndBattleText"] = "\nMiao!",
  ["_Route8CooltrainerF3AfterBattleText"] = "La guardia di\nZAFFERANOPOLI non\vci fa passare. é\nproprio cattiva!",
  ["_Route8CooltrainerF3BattleText"] = "Dobbiamo sembrare\nstupiducci a star\vqui cosi'!",
  ["_Route8CooltrainerF3EndBattleText"] = "\nGuarda cosa hai\vfatto!",
  ["_Route8CooltrainerF4AfterBattleText"] = "Ho sentito che\nCLEFAIRY si\vevolve se esposto\na una\vPIETRALUNARE.",
  ["_Route8CooltrainerF4BattleText"] = "Qual é un POKéMON\ncarino, rotondo e\vsoffice?",
  ["_Route8CooltrainerF4EndBattleText"] = "\nFermati! Non\vessere cosi'\ncattivo col mio\vCLEFAIRY!",
  ["_Route8Gambler1AfterBattleText"] = "La dea bendata non\né con me oggi!",
  ["_Route8Gambler1BattleText"] = "Bene! Lanciamo i\ndadi!",
  ["_Route8Gambler1EndBattleText"] = "\nAcciderboli!\vMancato di poco!",
  ["_Route8Gambler2AfterBattleText"] = "Il gioco d'azzardo\ne i POKéMON sono\vcome le ciliegie!\nNon puoi\vsmettere!",
  ["_Route8Gambler2BattleText"] = "Sono un tipo che\nrischia sempre!",
  ["_Route8Gambler2EndBattleText"] = "Mancato\nil grosso colpo!",
  ["_Route8SuperNerd1AfterBattleText"] = "Me la cavo meglio\na scuola che qui!",
  ["_Route8SuperNerd1BattleText"] = "Te la cavi coi\nPOKéMON, ma come\vvani in chimica?",
  ["_Route8SuperNerd1EndBattleText"] = "Ahi!\nCollasso\vnucleare!",
  ["_Route8SuperNerd2AfterBattleText"] = "Vai con GRIMER\nprima... e...\v...e... poi...",
  ["_Route8SuperNerd2BattleText"] = "Ci vuole strategia\nper vincere qui!",
  ["_Route8SuperNerd2EndBattleText"] = "Non ha\nsenso logico!",
  ["_Route8SuperNerd3AfterBattleText"] = "Siamo bloccati qui\na causa dei\vcancelli di\nZAFFERANOPOLI",
  ["_Route8SuperNerd3BattleText"] = "La scuola é\ndivertente, ma\vanche i POKéMON.",
  ["_Route8SuperNerd3EndBattleText"] = "Resto a\nstudiare.",
  ["_Route8UndergroundSignText"] = "SOTTERRANEO\nAZZURROPOLI\vLAVANDONIA",
  ["_Route9CooltrainerF1AfterBattleText"] = "Ti serve luce per\nattraversare quel\vtunnel buio piu'\navanti.",
  ["_Route9CooltrainerF1BattleText"] = "Hai con te dei\nPOKéMON! Sei mio!",
  ["_Route9CooltrainerF1EndBattleText"] = "Mi\nhai ingannato!",
  ["_Route9CooltrainerF2AfterBattleText"] = "Hai talento! In\nbocca al lupo!",
  ["_Route9CooltrainerF2BattleText"] = "Non osare\ncompatirmi!",
  ["_Route9CooltrainerF2EndBattleText"] = "No!\nSei troppo forte!",
  ["_Route9CooltrainerM1AfterBattleText"] = "Continua a\ncamminare!",
  ["_Route9CooltrainerM1BattleText"] = "Chi é quello che\ncammina con quei\vbellissimi\nPOKéMON?",
  ["_Route9CooltrainerM1EndBattleText"] = "\nSpento come una\vlampadina!",
  ["_Route9CooltrainerM2AfterBattleText"] = "Vai alla GROTTA\nDIGLETT anche tu?",
  ["_Route9CooltrainerM2BattleText"] = "Prendo la GROTTA\nDIGLETT per\vandare a\nLAVANDONIA...",
  ["_Route9CooltrainerM2EndBattleText"] = "Non\nsono all'altezza!",
  ["_Route9Hiker1AfterBattleText"] = "Hai avuto fegato a\nvenirmi contro,\veh?",
  ["_Route9Hiker1BattleText"] = "Bwahaha! Ottimo!\nMi annoiavo, eh!",
  ["_Route9Hiker1EndBattleText"] = "Vieni\npure, eh! Oh\vaspetta. Non ho\npiu' POKéMON!",
  ["_Route9Hiker2AfterBattleText"] = "Hahaha! I ragazzi\ndevono essere\vtosti!",
  ["_Route9Hiker2BattleText"] = "Hahaha! Non sei un\nbel peperino!",
  ["_Route9Hiker2EndBattleText"] = "Che\ncos'é?",
  ["_Route9Hiker3AfterBattleText"] = "Hahahaha! Noi\ntipacci ridiamo\vsempre!",
  ["_Route9Hiker3BattleText"] = "Hahahaha! Forza,\namico!",
  ["_Route9Hiker3EndBattleText"] = "\nHahahaha! Mi hai\vbattuto lealmente!",
  ["_Route9SignText"] = "PERCORSO 9\nCELESTOPOLI\vGROTTA DIGLETT",
  ["_Route9Youngster1AfterBattleText"] = "Devo raccogliere\npiu' di qualche\vinsetto per\nfortificarmi...",
  ["_Route9Youngster1BattleText"] = "Mi alzo presto\nogni giorno per\vfar crescere i\nPOKéMON dai\vbozzoli!",
  ["_Route9Youngster1EndBattleText"] = "COSA? Che\ntotale perdita di\vtempo!",
  ["_Route9Youngster2AfterBattleText"] = "Se non ti\npiacciono i\vPOKéMON insetto,\nmi stai\vantipatico!",
  ["_Route9Youngster2BattleText"] = "Vai, mio super\nPOKéMON insetto!",
  ["_Route9Youngster2EndBattleText"] = "I miei\ninsetti...",
  ["_SSAnne1FRoomsCooltrainerFAfterBattleText"] = "Hai ferito il mio\npovero POKéMON!\vPrendo a pretese\nche tu lo curi in\vun CENTRO POKéMON!",
  ["_SSAnne1FRoomsCooltrainerFBattleText"] = "Ho raccolto questi\nPOKéMON in tutto\vil mondo!",
  ["_SSAnne1FRoomsCooltrainerFEndBattleText"] = "Oh\nno! Ho girato il\vmondo per\ntrovarli!",
  ["_SSAnne1FRoomsGentleman1AfterBattleText"] = "Dovresti essere\ngentile con gli\vamici!",
  ["_SSAnne1FRoomsGentleman1BattleText"] = "Viaggio da solo\nnei miei viaggi!\vI POKéMON sono i\nmiei unici amici!",
  ["_SSAnne1FRoomsGentleman1EndBattleText"] = "I miei,\nmiei amici...",
  ["_SSAnne1FRoomsGentleman2AfterBattleText"] = "Voglio essere\nlasciato solo!\vFuori!",
  ["_Route6CooltrainerM2BattleText"] = "Tu, marmocchio!\nCome osi\virrompere!",
  ["_SSAnne1FRoomsGentleman2EndBattleText"] = "Uhm!\nBimbo maleducato!",
  ["_SSAnne1FRoomsGentleman3Text"] = "Ssh! Sono un\nagente di\vPOLIZIA! Sulle\ntracce del TEAM\vROCKET!",
  ["_SSAnne1FRoomsGirl1Text"] = "Cameriere, vorrei\nuna torta di\vciliegie, per\nfavore!",
  ["_SSAnne1FRoomsGirl2Text"] = "Facciamo una\ncrociera intorno\val mondo.",
  ["_SSAnne1FRoomsLittleGirlText"] = "Viaggio sempre con\nWIGGLYTUFF!",
  ["_SSAnne1FRoomsMiddleAgedManText"] = "Una crociera é\nelegante ma\vaccogliente!",
  ["_SSAnne1FRoomsWigglytuffText"] = "WIGGLYTUFF: Puup\npupuu!",
  ["_SSAnne1FRoomsYoungsterAfterBattleText"] = "Diventiamo amici,\nOK? Cosi' potremo\vscambiare POKéMON!",
  ["_SSAnne1FRoomsYoungsterBattleText"] = "Adoro i POKéMON! E\ntu?",
  ["_SSAnne1FRoomsYoungsterEndBattleText"] = "Wow! Sei\nfantastico!",
  ["_SSAnne1FSailorText"] = "I passeggeri sono\nagitati! Potresti\vessere sfidato dai\npiu' annoiati!",
  ["_SSAnne1FWaiterText"] = "Bonjour! Sono il\ncameriere di\vquesta nave! Saro'\nfelice di\vservirti qualsiasi\ncosa desideri!\vAh! Il tipo forte\ne silenzioso!",
  ["_SSAnne2FRivalCutMasterText"] = "{RIVAL}: Ho\nsentito che a\vbordo c'era un\nesperto di\vTAGLIO. Ma era\nsolo un vecchio\vmal di mare!\nComunque TAGLIO é\vmolto utile!\nDovresti andare a\vvederlo! Ci si\nvede!",
  ["_SSAnne2FRivalDefeatedText"] = "Uhm!\nAlmeno stai\vallevando i tuoi\nPOKéMON!",
  ["_SSAnne2FRivalText"] = "{RIVAL}: Bonjour!\n{PLAYER}! Che\vsorpresa vederti\nqui! {PLAYER}, sei\vstato invitato\ndavvero? Come va\vcol tuo POKéDEX?\nIo ne ho gia'\vpresi 40 tipi,\namico! Ce ne sono\vdi ogni tipo\novunque! Cerca\vnelle zone erbose!",
  ["_SSAnne2FRivalVictoryText"] = "{PLAYER}!\nChe hai, il mal\vdi mare? Dovresti\ndarti una mossa,\vamico!",
  ["_SSAnne2FRoomsBeautyText"] = "Sento che molta\ngente ha il mal\vdi mare!",
  ["_SSAnne2FRoomsBrunetteGirlText"] = "Il CAPITANO\nsembrava molto\vmalato e pallido!",
  ["_SSAnne2FRoomsCooltrainerFAfterBattleText"] = "Oh, adoro i tuoi\nforti POKéMON!",
  ["_SSAnne2FRoomsCooltrainerFBattleText"] = "Non ti ho mai\nvisto alla festa.",
  ["_SSAnne2FRoomsCooltrainerFEndBattleText"] = "\nPrendila con\vfilosofia!",
  ["_SSAnne2FRoomsFisherAfterBattleText"] = "La festa? La festa\nsulla nave\vdovrebbe essere\nfinita ormai.",
  ["_SSAnne2FRoomsFisherBattleText"] = "Guarda che cosa ho\npescato!",
  ["_SSAnne2FRoomsFisherEndBattleText"] = "Ho\nfinito le scorte!",
  ["_SSAnne2FRoomsGentleman1AfterBattleText"] = "15 anni fa avrei\nvinto di sicuro!",
  ["_SSAnne2FRoomsGentleman1BattleText"] = "Gareggiare con i\ngiovani mi\vmantiene\ngiovanile.",
  ["_SSAnne2FRoomsGentleman1EndBattleText"] = "Bella\nlotta! Ah, mi\vsento di nuovo\ngiovane!",
  ["_SSAnne2FRoomsGentleman2AfterBattleText"] = "Preferisco POKéMON\nforti e rari.",
  ["_SSAnne2FRoomsGentleman2BattleText"] = "Quale preferisci,\nun POKéMON forte\vo raro?",
  ["_SSAnne2FRoomsGentleman2EndBattleText"] = "Devo\nsalutarti!",
  ["_SSAnne2FRoomsGentleman3Text"] = "In tutti i miei\nviaggi non ho mai\vvisto un POKéMON\ndormire cosi'!\vEra qualcosa di\nsimile!",
  ["_SSAnne2FRoomsGentleman4Text"] = "Ah si', ho visto\nalcuni POKéMON\vtraghettare la\ngente sull'acqua!",
  ["_SSAnne2FRoomsGentleman5Text"] = "Sei stato alla\nZONA SAFARI a\vFUCSIAPOLI?\nC'erano tanti\vtipi rarissimi di\nPOKéMON!!",
  ["_SSAnne2FRoomsGrampsText"] = "I POKéMON possono\nTAGLIARE piccoli\varbusti.",
  ["_SSAnne2FRoomsLittleBoyText"] = "Io e il mio babbo\npensiamo che la\vZONA SAFARI sia\nmagnifica!",
  ["_SSAnne2FWaiterText"] = "Questa nave é una\nnave di lusso per\vallenatori! A ogni\nporto facciamo\vfeste con\ninvitati!",
  ["_SSAnne3FSailorText"] = "Il nostro CAPITANO\né un maestro di\vspada! Insegna\nanche TAGLIO ai\vPOKéMON!",
  ["_SSAnneB1FRoomsFisherAfterBattleText"] = "Volevo fare anche\nte mio\vassistente!",
  ["_SSAnneB1FRoomsFisherBattleText"] = "Salve straniero!\nFermati a\vchiacchierare!\nTutti i miei\vPOKéMON provengono\ndal mare!",
  ["_SSAnneB1FRoomsFisherEndBattleText"] = "\nAcciderboli!\vQuello mi é\nscappato!",
  ["_SSAnneB1FRoomsMachokeText"] = "MACHOKE: Gwoh!\nGoggoh!",
  ["_SSAnneB1FRoomsSailor1AfterBattleText"] = "Haha! Vuoi fare il\nmarinaio,\vcompagno?",
  ["_SSAnneB1FRoomsSailor1BattleText"] = "Sai cosa dicono su\nmarinai e lotte!",
  ["_SSAnneB1FRoomsSailor1EndBattleText"] = "Esatto!\nBel match,\vcompagno!",
  ["_SSAnneB1FRoomsSailor2AfterBattleText"] = "Hai visto il GURU\nPESCATORE a\vARANCIOPOLI?",
  ["_SSAnneB1FRoomsSailor2BattleText"] = "Il mio orgoglio di\nmarinaio é in\vgioco!",
  ["_SSAnneB1FRoomsSailor2EndBattleText"] = "Il tuo\nspirito mi ha\vaffondato!",
  ["_SSAnneB1FRoomsSailor3AfterBattleText"] = "Abbiamo preso\ntutti i POKéMON\vmentre eravamo in\nmare!",
  ["_SSAnneB1FRoomsSailor3BattleText"] = "Anche noi marinai\nabbiamo POKéMON!",
  ["_SSAnneB1FRoomsSailor3EndBattleText"] = "OK, non\nte la cavi male.",
  ["_SSAnneB1FRoomsSailor4AfterBattleText"] = "I POKéMON marini\nvivono in acque\vprofonde. Ti serve\nun AMO!",
  ["_SSAnneB1FRoomsSailor4BattleText"] = "Mi piacciono i\npivelli vispi\vcome te!",
  ["_SSAnneB1FRoomsSailor4EndBattleText"] = "Argh!\nPerso!",
  ["_SSAnneB1FRoomsSailor5AfterBattleText"] = "A volte qualche\nmedusa alla\vderiva finisce\nsulla nave.",
  ["_SSAnneB1FRoomsSailor5BattleText"] = "Compagno,\ncamminerai con\vl'asse se perdi!",
  ["_SSAnneB1FRoomsSailor5EndBattleText"] = "Argh!\nBattuto da un\vragazzino!",
  ["_SSAnneB1FRoomsSuperNerdText"] = "Il mio amico\nMACHOKE é\vfortissimo! Ha\nabbastanza FORZA\vper spostare\ngrandi massi!",
  ["_SSAnneBowCooltrainerMText"] = "Urf. Sto male.\nSono uscito a\vprendere aria.",
  ["_SSAnneBowSailor1Text"] = "Scrofare i ponti é\nun lavoro duro!",
  ["_SSAnneBowSailor2AfterBattleText"] = "Quanti tipi di\nPOKéMON crediti\vche ci siano in\ntutto?",
  ["_SSAnneBowSailor2BattleText"] = "Ehi compagno!\nFacciamo un\vsaltello!",
  ["_SSAnneBowSailor2EndBattleText"] = "Sei\nimpressionante!",
  ["_SSAnneBowSailor3AfterBattleText"] = "Mio padre ha detto\nche ci sono 100\vtipi di POKéMON.\nSecondo me ce ne\vsono di piu'.",
  ["_SSAnneBowSailor3BattleText"] = "Ahoi la'! Hai il\nmal di mare?",
  ["_SSAnneBowSailor3EndBattleText"] = "Sono\nstato solo\vdistratto!",
  ["_SSAnneBowSuperNerdText"] = "La festa é finita.\nLa nave partira'\vpresto.",
  ["_SSAnneCaptainsRoomCaptainHM01NoRoomText"] = "Oh no! Non hai\nabbastanza\vspazio!",
  ["_SSAnneCaptainsRoomCaptainIFeelMuchBetterText"] = "CAPITANO: Uff!\nGrazie! Sto molto\vmeglio! Vuoi\nvedere la mia\vtecnica TAGLIO? Te\nla mostrerei se\vnon stessi male...\nLo so! Prendi\vquesta! Insegnala\nai tuoi POKéMON e\vpotrai TAGLIARE\nogni volta!",
  ["_SSAnneCaptainsRoomCaptainNotSickAnymoreText"] = "CAPITANO: Uff! Ora\nche non sto piu'\vmale, credo sia\nl'ora.",
  ["_SSAnneCaptainsRoomCaptainReceivedHM01Text"] = "{PLAYER} riceve\n{RAM:wStringBuffer}!",
  ["_SSAnneCaptainsRoomRubCaptainsBackText"] = "CAPITANO:\nOoargh... Che\vschifo... Urrp!\nMal di mare...\v{PLAYER} ha\nstrofinato la\vschiena del\nCAPITANO!\vStrofina-strofina...\nStrofina-strofina...",
  ["_SSAnneCaptainsRoomSeasickBookText"] = "Come sconfiggere\nil mal di mare...\vIl CAPITANO sta\nleggendo questo!",
  ["_SSAnneCaptainsRoomTrashText"] = "Che schifo! Non\navrei dovuto\vguardare!",
  ["_SSAnneKitchenCook1Text"] = "Tu, mon petit!\nSiamo occupati\vqui! Fuori dai\npiedi!",
  ["_Route6KitchenCook2Text"] = "Ho visto una\nstrana palla\vnella spazzatura.",
  ["_SSAnneKitchenCook3Text"] = "Sono cosi'\noccupato che ho\vle vertigini!",
  ["_SSAnneKitchenCook4Text"] = "Um-de-hum-de ho...\nSbuccio patate\vtutti i giorni!\nUm-hum...",
  ["_SSAnneKitchenCook5Text"] = "Hai saputo di\nSNORLAX? Fa solo\vuna vita a\nmangiare e\vdormire!",
  ["_SSAnneKitchenCook6Text"] = "Piagnuc...\nSniff... Devo\vsolo pelare\ncipolle...\vPiagnuc...",
  ["_SSAnneKitchenCook7MainCourseIsText"] = "Ehm-ehm! Certo che\nsono lo CHEF! La\vportata principale\né",
  ["_SSTicketNoRoomText"] = "Hai troppa roba,\namico!",
  ["_SSTicketReceivedText"] = "{PLAYER} riceve\n{RAM:wStringBuffer}!",







  ["_SafariZoneAngryText"] = "{RAM:wEnemyMonNick}\nselvatico é\varrabbiato!",
  ["_SafariZoneCenterRestHouseGirlText"] = "SARA: Dove sara'\nandato il mio\vragazzo ERIK?",
  ["_SafariZoneCenterRestHouseScientistText"] = "Sto catturando\nPOKéMON da\vportare a casa\ncome regali!",
  ["_SafariZoneCenterRestHouseSignText"] = "AREA DI RIPOSO",
  ["_SafariZoneCenterTrainerTipsSignText"] = "CONSIGLI UTILI\nPremi il Pulsante\vSTART per vedere\nil tempo residuo!",
  ["_SafariZoneEastRestHouseRockerText"] = "Ho catturato un\nCHANSEY! Ne é\vvalsa la pena!",
  ["_SafariZoneEastRestHouseScientistText"] = "Quanti ne hai\ncatturati? Sono\vdistrutto dal\nlavoro!",
  ["_SafariZoneEastRestHouseSignText"] = "AREA DI RIPOSO",
  ["_SafariZoneEastRestHouseSilphWorkerMText"] = "Uff! Sono stanco\ndi tutto questo\vsvago!",
  ["_SafariZoneEastSignText"] = "AREA CENTRALE\nNORD: AREA 2",
  ["_SafariZoneEastTrainerTipsText"] = "CONSIGLI UTILI Il\ntempo rimasto\vdiminuisce solo\nmentre cammini!",
  ["_SafariZoneEatingText"] = "{RAM:wEnemyMonNick}\nselvatico sta\vmangiando!",
  ["_SafariZoneGateSafariZoneWorker1CallYouOnThePAText"] = "Ti chiameremo con\nl'altoparlante se\vfinisce il tempo o\nle SAFARI BALL!",
  ["_SafariZoneGateSafariZoneWorker1GoodHaulComeAgainText"] = "é stato un buon\nbottino? Torna a\vtrovarci!",
  ["_SafariZoneGateSafariZoneWorker1GoodLuckText"] = "Buona fortuna!",
  ["_SafariZoneGateSafariZoneWorker1LeavingEarlyText"] = "Te ne vai gia'?",
  ["_SafariZoneGateSafariZoneWorker1NotEnoughMoneyText"] = "Ops! Non hai\nabbastanza soldi!",
  ["_SafariZoneGateSafariZoneWorker1PleaseComeAgainText"] = "OK! Torna a\ntrovarci presto!",
  ["_SafariZoneGateSafariZoneWorker1ReturnSafariBallsText"] = "Restituisci le\nSAFARI BALL che\vti sono rimaste.",
  ["_SafariZoneGateSafariZoneWorker1Text"] = "Benvenuto nella\nZONA SAFARI!",
  ["_SafariZoneGateSafariZoneWorker1ThatllBe500PleaseText"] = "Costano 500\nPokémon-dollari!\vQui usiamo solo\nSAFARI BALL.\v{PLAYER} riceve 30\nSAFARI BALL!",
  ["_SafariZoneGateSafariZoneWorker1WouldYouLikeToJoinText"] = "Per soli 500\nPokémon-dollari\vpuoi catturare\ntutti i POKéMON\vche vuoi! Vuoi\npartecipare alla\vcaccia?",
  ["_SafariZoneGateSafariZoneWorker2FirstTimeHereText"] = "Ciao! é la tua\nprima volta qui?",
  ["_SafariZoneGateSafariZoneWorker2SafariZoneExplanationText"] = "La ZONA SAFARI ha\n4 zone diverse.\vIn ogni zona ci\nsono POKéMON\vdifferenti. Usate\nle SAFARI BALL\vper catturarli! Se\nfiniscono tempo o\vSAFARI BALL, la\npartita é finita!\vPrima di partire,\napri un POKéMON\vBOX vuoto per fare\nspazio ai nuovi!",
  ["_SafariZoneGateSafariZoneWorker2YoureARegularHereText"] = "Spiacente, tu sei\nun cliente\vabituale!",
  ["_SafariZoneNorthRestHouseGentlemanText"] = "Il mio EEVEE si é\nevoluto in\vFLAREON! Ma quello\ndi un amico é\vdiventato un\nVAPOREON! Chissa'\vperché?",
  ["_SafariZoneNorthRestHouseSafariZoneWorkerText"] = "Vai nella parte\npiu' profonda\vdella ZONA SAFARI.\nVinci rai un\vpremio!",
  ["_SafariZoneNorthRestHouseScientistText"] = "Puoi tenere ogni\noggetto trovato\vper terra qui. Ma\nfinira' il tempo\vse provi a prender\nli tutti insieme!",
  ["_SafariZoneNorthRestHouseSignText"] = "AREA DI RIPOSO",
  ["_SafariZoneNorthSignText"] = "AREA 2",
  ["_SafariZoneNorthTrainerTips1Text"] = "CONSIGLI UTILI La\nCASA SEGRETA é\vancora piu'\navanti!",
  ["_SafariZoneNorthTrainerTips2Text"] = "CONSIGLI UTILI I\nPOKéMON si\vnascondono\nnell'erba!\vCammina a zig-zag\nnell'erba alta\vper farli uscire.",
  ["_SafariZoneNorthTrainerTips3Text"] = "CONSIGLI UTILI\nVinci una MN\vgratis trovando la\nCASA SEGRETA!",
  ["_SafariZoneSecretHouseFishingGuruHM03ExplanationText"] = "La MN03 é SURF! I\nPOKéMON potranno\vtraghettarti\nsull'acqua!\vQuesta MN non si\nrompe! Puoi\vusarla tutte le\nvolte che vuoi!\vSei fortunatissimo\na vincere questo\vfavoloso premio!",
  ["_SafariZoneSecretHouseFishingGuruHM03NoRoomText"] = "Non hai abbastanza\nspazio per questo\vfavoloso premio!",
  ["_SafariZoneSecretHouseFishingGuruReceivedHM03Text"] = "{PLAYER} riceve\n{RAM:wStringBuffer}!",
  ["_SafariZoneSecretHouseFishingGuruYouHaveWonText"] = "Ah! Finalmente!\nSei il primo ad\varrivare alla CASA\nSEGRETA! Temevo\vche nessuno circa\navrebbe vinto il\vnostro premio.\nCongratulazioni!\vHai vinto!",
  ["_SafariZoneWestFindWardensTeethSignText"] = "AVVISO RICHIESTA\nCercate i DENTI\vD'ORO smarriti dal\nGUARDIANO SAFARI.\vDevono essere da\nqueste parti.\vRicompensa\nofferta!\vContattare:\nGUARDIA",
  ["_SafariZoneWestRestHouseCooltrainerMText"] = "Usare l'ESCA rende\ni POKéMON piu'\vfacili da\npigliare.",
  ["_SafariZoneWestRestHouseScientistText"] = "Lanciare SASSI ai\nPOKéMON li fa\vscappare, ma sono\npiu' facili da\vcatturare.",
  ["_SafariZoneWestRestHouseSignText"] = "AREA DI RIPOSO",
  ["_SafariZoneWestRestHouseSilphWorkerFText"] = "Ho camminato\nmolto, ma non ho\vvisto POKéMON che\nvolevo.",
  ["_SafariZoneWestSignText"] = "AREA 3 EST: AREA\nCENTRALE",
  ["_SafariZoneWestTrainerTipsText"] = "CONSIGLI UTILI\nCampagna esplo\vrazione zone! Alla\nricerca della\vCASA SEGRETA!",
  ["_SaffronCityFightingDojoSignText"] = "DOJO LOTTA",
  ["_SaffronCityGentlemanText"] = "Sono volato qui\ncol mio PIDGEOT\vleggendo della\nSILPH. é gia'\vfinita? Mi sono\nperso tutta la\vcronaca.",
  ["_SaffronCityGymSignText"] = "PALESTRA POKéMON\nDI ZAFFERANOPOLI\vCAPOPALESTRA:\nSABRINA La\vmaestra dei\nPokémon Psico!",
  ["_SaffronCityMrPsychicsHouseSignText"] = "CASA DEL SIG. PSI",
  ["_SaffronCityPidgeotText"] = "PIDGEOT: Bi bibii!",
  ["_SaffronCityPokecenterGuyText1"] = "Sarebbe bello se i\nSUPERQUATTRO\vvenissero a dare\nuna lezione al\vTEAM ROCKET!",
  ["_SaffronCityPokecenterGuyText2"] = "Il TEAM ROCKET é\nscomparso!\vPossiamo uscire in\nsicurezza!\vFantastico!",
  ["_SaffronCityRockerText"] = "Ho visto il CAPO\ndel ROCKET\vscappare\ndall'edificio\vSILPH.",
  ["_SaffronCityRocket1Text"] = "Che vuoi?\nSparisci!",
  ["_SaffronCityRocket2Text"] = "Il CAPO ha detto\nche prendera'\vquesta citta'!",
  ["_SaffronCityRocket3Text"] = "Togliti di mezzo!",
  ["_SaffronCityRocket4Text"] = "ZAFFERANOPOLI\nappartiene al\vTEAM ROCKET!",
  ["_SaffronCityRocket5Text"] = "Essere malvagi mi\nfa sentire vivo!",
  ["_SaffronCityRocket6Text"] = "Ahi! Guarda dove\nmetti i piedi!",
  ["_SaffronCityRocket7Text"] = "Con la SILPH sotto\ncontrollo, possia\vmo sfruttare i\nPOKéMON del\vmondo!",
  ["_SaffronCityRocket8Text"] = "Sono una guardia.\nNon lascio pas\vsare bambini",
  ["_SaffronCityRocket9Text"] = "... Ronf... Ha! Si\nsta facendo un\vpisolino!",
  ["_SaffronCityScientistText"] = "Hai battuto il\nTEAM ROCKET da\vsolo? Incredibile!",
  ["_SaffronCitySignText"] = "ZAFFERANOPOLI\nSplendente e\vd'oro Terra del\nCommercio",
  ["_SaffronCitySilphCoLatestProductSignText"] = "L'ultimo prodotto\ndella SILPH!\vUscita da\ndefinire...",
  ["_SaffronCitySilphCoSignText"] = "SOCIETA' SILPH\nEDIFICIO UFFICI",
  ["_SaffronCitySilphWorkerFText"] = "La gente dovrebbe\ntornare a frotte\va ZAFFERANOPOLI\nora.",
  ["_SaffronCitySilphWorkerMText"] = "Si'! Il TEAM\nROCKET é andato\vvia! é sicuro\nuscire di nuovo!",
  ["_SaffronCityTrainerTips1Text"] = "CONSIGLI UTILI\nCURA TOTALE cura\vtutti i problemi\ncome sonno e\vustioni. Costa un\npo' di piu', ma é\vmolto piu' comodo.",
  ["_SaffronCityTrainerTips2Text"] = "CONSIGLI UTILI Le\nnuove SUPER BALL\voffrono una\nmiglior cattura.\vProvale su quei\nPOKéMON difficili\vda catturare.",
  ["_SaffronGateGuardGeeImThirstyText"] = "Sono di guardia.\nUffa, ho una\vsete! Aspetta un\nattimo, la strada\vé chiusa.",
  ["_SaffronGateGuardImParchedText"] = "Ehi, ragazzo! Ho\nla gola secca!\v... Eh? Posso bere\nquesta bibita?\vOh, grazie!",
  ["_SaffronGateGuardThanksForTheDrinkText"] = "Ciao, grazie per\nle bevande\vfresche!",
  ["_SaffronGateGuardYouCanGoOnThroughText"] = "... Glub glub...\n... Gulp... Se\vvuoi andare a\nZAFFERANOPOLI...\v... Puoi passare.\nLo condividero'\vcon le altre\nguardie!",
  ["_SaffronGymChanneler1AfterBattleText"] = "In una lotta tra\nuguali, vince chi\vha la volonta'\npiu' forte! Se\vvuoi battere\nSABRINA, pensa\vsolo a vincere!",
  ["_SaffronGymChanneler1BattleText"] = "SABRINA é piu'\ngiovane di me, ma\vla rispetto!",
  ["_SaffronGymChanneler1EndBattleText"] = "Non basta!",
  ["_SaffronGymChanneler2AfterBattleText"] = "Devo insegnare\ntecniche migliori\vai miei POKéMON!",
  ["_SaffronGymChanneler2BattleText"] = "I POKéMON assomi\ngliono ai propri\vallenatori. I tuoi\nPOKéMON devono\vessere tosti!",
  ["_SaffronGymChanneler2EndBattleText"] = "Lo sapevo!",
  ["_SaffronGymChanneler3AfterBattleText"] = "Sapevo che sarebbe\nsuccesso tutto\vquesto.",
  ["_SaffronGymChanneler3BattleText"] = "Io e te, i nostri\nPOKéMON\vlotteranno!",
  ["_SaffronGymChanneler3EndBattleText"] = "Ho perso\nal termine!",
  ["_SaffronGymGuideBeatSabrinaText"] = "Poteri psichici,\neh? Se li avessi\vio, farei un sacco\ndi soldi alle\vslot!",
  ["_SaffronGymGuideChampInMakingText"] = "Ehila'! Campione!\nI POKéMON di\vSABRINA usano la\nmente anziché la\vforza! I POKéMON\nLotta sono deboli\vcontro i POKéMON\npsico! Vengono\vstesi prima di\npoter sferrare un\vpugno!",
  ["_SaffronGymSabrinaMarshBadgeInfoText"] = "La MEDAGLIA PALUDE\nubbidisce ai\vPOKéMON fino al Lv\n70! I POKéMON\vpiu' forti\ndiventano\vselvaggi e ti\nignorano! Non far\vcrescere troppo i\ntuoi POKéMON!\vAspetta, prendi\nquesta MT!",
  ["_SaffronGymSabrinaPostBattleAdviceText"] = "Ognuno ha poteri\npsichici! La\vgente non se ne\nrende conto!",
  ["_SaffronGymSabrinaReceivedMarshBadgeText"] = "Sono scioccata! Ma\nuna sconfitta é\vuna sconfitta.\nAmmetto di non\vaver studiato\nabbastanza! Hai\vvinto la MEDAGLIA\nPALUDE!",
  ["_SaffronGymSabrinaReceivedTM46Text"] = "{PLAYER} riceve la\nMT46!",
  ["_SaffronGymSabrinaTM46NoRoomText"] = "Il tuo zaino é\ncormo di roba!",
  ["_SaffronGymSabrinaText"] = "Avevo previsto la\ntua venuta! Ho\vpoteri psichici da\nquando ero\vpiccola. Ho\niniziato piegando\vi cucchiai con la\nmente. Odio\vlottare, ma se lo\ndesideri, ti\vmostrero' i\npoteri!",
  ["_SaffronGymYoungster1AfterBattleText"] = "I POKéMON psico\ntemono solo\vspettri e insetti!",
  ["_SaffronGymYoungster1BattleText"] = "Il nostro potere\ninvisibile ti\vspaventa?",
  ["_SaffronGymYoungster1EndBattleText"] = "Non l'avevo\nprevisto!",
  ["_SaffronGymYoungster2AfterBattleText"] = "SABRINA ha appena\nsteso il MAESTRO\vDI KARATE qui\naccanto!",
  ["_SaffronGymYoungster2BattleText"] = "Sai che la forza\nnuda e cruda non\vbasta!",
  ["_SaffronGymYoungster2EndBattleText"] = "Non ci\nposso credere!",
  ["_SaffronGymYoungster3AfterBattleText"] = "C'erano 2 palestre\nPOKéMON a\vZAFFERANOPOLI. Il\nDOJO qui vicino\vha perso lo status\nquando li abbiamo\vstroncati!",
  ["_SaffronGymYoungster3BattleText"] = "SABRINA é giovane,\nma é anche la\vnostra CAPO! Non\narriverai a lei\vfacilmente!",
  ["_SaffronGymYoungster3EndBattleText"] = "Ho perso la\nconcentrazione!",
  ["_SaffronGymYoungster4AfterBattleText"] = "Esatto! Ho usato\nla telepatia per\vleggerti la mente!",
  ["_SaffronGymYoungster4BattleText"] = "La palestra di\nZAFFERANOPOLI é\vfamosa per i suoi\npsico! Vuoi\vvedere SABRINA! Lo\nso!",
  ["_SaffronGymYoungster4EndBattleText"] = "Arrrgh!",
  ["_SaffronMartCooltrainerFText"] = "IL REVITALIZ. é\ncostoso, ma\vrimette in sesto i\nPOKéMON!",
  ["_SaffronMartSuperNerdText"] = "Il REPELL MAX dura\npiu' del SUPER\vREP per tenere\nlontani i POKéMON\vpiu' deboli!",
  ["_SaffronPidgeyHouseBrunetteGirlText"] = "Grazie per aver\nscritto. Spero di\vvederti presto!\nEhi! Non guardare\vla mia lettera!",
  ["_SaffronPidgeyHousePaperText"] = "Mi hanno regalato\nuna PROTEINA.\vServe per aumen\ntare la potenza\vdelle mosse!",
  ["_SaffronPidgeyHousePidgeyText"] = "PIDGEY: Kurukkoo!",
  ["_SaffronPidgeyHouseYoungsterText"] = "A mia figlia piace\nmoltissimo\vimitare la gente!\nLa sua passione\vsono le BAMB.\nPOKé!",
  ["_SaffronPokecenterBeautyText"] = "I tassi di cresci\nta dei POKéMON\vvariano da specie\na specie.",
  ["_SaffronPokecenterGentlemanText"] = "La SILPH é molto\nfamosa. Ecco\vperché ha attirato\nil TEAM ROCKET!",
  ["_SaveOptionText"] = "L'opzione SALVA é\nnel MENU.",
  ["_SavingEnergyText"] = "{USER}\nsta accumulando\venergia!",
  ["_ScaredText"] = "{RAM:wBattleMonNick} ha\ntroppa paura per\vmuoversi!",
  ["_SeafoamIslandsB4FArticunoBattleText"] = "Gyaoo!",
  ["_SeafoamIslandsB4FBouldersSignText"] = "I massi potreb\nbero deviare il\vflusso d'acqua!",
  ["_SeafoamIslandsB4FDangerSignText"] = "PERICOLO Corrente\nforte!",
  ["_SentToBoxText"] = "Non c'é piu' posto\nper i POKéMON!\v{RAM:wBoxMonNicks} é stato\nspedito al BOX\vPOKéMON {RAM:wStringBuffer}\nsul PC!",
  ["_ShallWeHealYourPokemonText"] = "Vuoi curare i tuoi\nPOKéMON?",
  ["_ShroudedInMistText"] = "{USER}\né avvolto nella\vnebbia!",
  ["_SilphCo10FGiovanniILostAgainText"] = "Arrgh!! Ho perso\ndi nuovo!?",
  ["_SilphCo10FPorygonText"] = "Il monitor ha un\nPOKéMON sopra!",
  ["_SilphCo10FRocketAfterBattleText"] = "Bel tentativo, ma\nla sala riunio ni\vé un piano su!",
  ["_SilphCo10FRocketBattleText"] = "Benvenuto al 10°\npiano! Che\vpiacere averti qui\ncon me!",
  ["_SilphCo10FRocketEndBattleText"] = "Sono\nstupito!",
  ["_SilphCo10FScientistAfterBattleText"] = "Sei soddisfatto di\navermi battuto?\vAllora torna a\ncasa!",
  ["_SilphCo10FScientistBattleText"] = "Basta con questi\ngiochi sciocchi!",
  ["_SilphCo10FScientistEndBattleText"] = "Nessun\ncontinua rimasto!",
  ["_SilphCo10FSilphWorkerFImScaredText"] = "Waaaaa! Ho paura!",
  ["_SilphCo10FSilphWorkerFQuietAboutMyCryingText"] = "Ti prego, sta'\nzitto sul mio\vpianto!",
  ["_SilphCo11FBeautyText"] = "SEGRETARIA: Grazie\nper averci\vliberato tutti!\nAmmiriamo molto\vil tuo coraggio.",
  ["_SilphCo11FGiovanniText"] = "Ah {PLAYER}! Ci\nrincontriamo! Il\vPRESIDENTE ed io\nstiamo parlando\vdi affari. Non\nficcare il naso\vnelle cose dei\ngrandi... O\vproverai il\ndolore!",
  ["_SilphCo11FGiovanniYouRuinedOurPlansText"] = "Accidenti! Hai\nrovinato i nostri\vpiani SILPH! Ma il\nTEAM ROCKET non\vcadra' mai!\n{PLAYER}! Ricorda\vche i POKéMON sono\ndel TEAM ROCKET!\vDevo andare, ma\ntornero'!",
  ["_SilphCo11FRocket1AfterBattleText"] = "Vuoi vedere il mio\nCAPO, eh?",
  ["_SilphCo11FRocket1BattleText"] = "Fermati li'! Non\nmuoverti!",
  ["_SilphCo11FRocket1EndBattleText"] = "Non... Ti\nprego!",
  ["_SilphCo11FRocket2AfterBattleText"] = "Attento, al mio\nCAPO piacciono i\vPOKéMON tosti!",
  ["_SilphCo11FRocket2BattleText"] = "Alt! Hai un appun\ntamento col CAPO?",
  ["_SilphCo11FRocket2EndBattleText"] = "Gaah!\nDistrutto!",
  ["_SilphCo11FSilphPresidentMasterBallDescriptionText"] = "PRESIDENTE: Non\npuoi comprarla da\vnessuna parte! é\nla nostra MASTER\vBALL segreta!\nCatturera' qual\vsiasi POKéMON\nsenza fallire!\vPero' tieni il\nsegreto sull'uso.",
  ["_SilphCo11FSilphPresidentNoRoomText"] = "Non hai posto per\nquesto.",
  ["_SilphCo11FSilphPresidentReceivedMasterBallText"] = "{PLAYER} riceve\n{RAM:wStringBuffer}!",
  ["_SilphCo11FSilphPresidentText"] = "PRESIDENTE: Grazie\nper aver salvato\vla SILPH! Non\ndimentichero' che\vci hai salvati nel\npericolo! Devo\vringraziarti in\nqualche modo!\vEssendo ricco,\nposso darti\vtutto! Ecco, forse\nquesto andra'\vbene!",
  ["_SilphCo1FLinkReceptionistText"] = "Benvenuto! Il\nPRESIDENTE é\vall'11° piano\nnella sala\vriunioni!",
  ["_SilphCo2FRocket1AfterBattleText"] = "Le piastrelle a\nforma di rombo\vsono\nteletrasporti!\vSono hi-tech!",
  ["_SilphCo2FRocket1BattleText"] = "I bambini non\npossono entrare!",
  ["_SilphCo2FRocket1EndBattleText"] = "Duro!",
  ["_SilphCo2FRocket2AfterBattleText"] = "La SILPH si unira'\nal TEAM ROCKET!",
  ["_SilphCo2FRocket2BattleText"] = "Ehi tu! Che fai\nqui?",
  ["_SilphCo2FRocket2EndBattleText"] = "Ho\ntoppato!",
  ["_SilphCo2FScientist1AfterBattleText"] = "Lavoro per SILPH e\nTEAM ROCKET!",
  ["_SilphCo2FScientist1BattleText"] = "Aiuto! Lavoro alla\nSILPH.",
  ["_SilphCo2FScientist1EndBattleText"] = "Come\nfacevi a sapere\vche ero ROCKET?",
  ["_SilphCo2FScientist2AfterBattleText"] = "Sai risolvere il\nlabirinto qui?",
  ["_SilphCo2FScientist2BattleText"] = "Zona vietata! Vai\na casa!",
  ["_SilphCo2FScientist2EndBattleText"] = "Sei\nbravo.",
  ["_SilphCo2FSilphWorkerFReceivedTM36Text"] = "{PLAYER} riceve\n{RAM:wStringBuffer}!",
  ["_SilphCo2FSilphWorkerFTM36ExplanationText"] = "La MT36 é\nAUTODISTRUZIONE!\vé forte, ma il\nPOKéMON va K.O.!\vFai attenzione.",
  ["_SilphCo2FSilphWorkerFTM36NoRoomText"] = "Non hai abbastanza\nspazio per\vquesto.",
  ["_SilphCo3FRocketAfterBattleText"] = "Un indizio? Puoi\naprire le porte\vcon una SCHEDA!",
  ["_SilphCo3FRocketBattleText"] = "Smetti di darci\nfastidio,\vmoccioso!",
  ["_SilphCo3FRocketEndBattleText"] = "Mi\narrendo!",
  ["_SilphCo3FScientistAfterBattleText"] = "Uhm... Il TEAM\nROCKET ha detto\vche mi avrebbe\nfatto stu diare i\vPOKéMON!",
  ["_SilphCo3FScientistBattleText"] = "Sostengo il TEAM\nROCKET piu' della\vstessa SILPH!",
  ["_SilphCo3FScientistEndBattleText"] = "Mi hai\nproprio preso!",
  ["_SilphCo3FSilphWorkerMWhatShouldIDoText"] = "Lavoro alla SILPH.\nChe devo fare?",
  ["_SilphCo3FSilphWorkerMYouSavedUsText"] = "{PLAYER}! Tu e i\ntuoi POKéMON ci\vavete salvati!",
  ["_SilphCo4FRocket1AfterBattleText"] = "Fwahahaha! Il mio\nCAPO punta questo\vposto!",
  ["_SilphCo4FRocket1BattleText"] = "Il TEAM ROCKET ha\npreso il comando\vdella SILPH\nS.P.A.!",
  ["_SilphCo4FRocket1EndBattleText"] = "Arrgh!",
  ["_SilphCo4FRocket2AfterBattleText"] = "Meglio avvisare il\nCAPO all'11°\vpiano!",
  ["_SilphCo4FRocket2BattleText"] = "Intruso avvistato!",
  ["_SilphCo4FRocket2EndBattleText"] = "Tu chi\nsei?",
  ["_SilphCo4FScientistAfterBattleText"] = "Le porte sono\nchiuse! Una\vSCHEDA le apre!",
  ["_SilphCo4FScientistBattleText"] = "I miei POKéMON\nsono i miei leali\vsoldati!",
  ["_SilphCo4FScientistEndBattleText"] = "\nAccidenti! Che\vPOKéMON deboli!",
  ["_SilphCo4FSilphWorkerMImHidingText"] = "Sssh! Non vedi che\nmi nascondo?",
  ["_SilphCo4FSilphWorkerMTeamRocketIsGoneText"] = "Eh? Il TEAM ROCKET\né sparito?",
  ["_SilphCo5FPokemonReport1Text"] = "é un RAPPORTO! IL\nLABORATORIO ha\vcreato PORYGON, il\nprimo POKéMON\vvirtuale.",
  ["_SilphCo5FPokemonReport2Text"] = "é un RAPPORTO!\nOltre 160 mosse\vPOKéMON sono state\nconfermate.",
  ["_SilphCo5FPokemonReport3Text"] = "é un RAPPORTO! 4\nPOKéMON si\vevolvono solo con\nlo scambio\vtramite cavo Link.",
  ["_SilphCo5FRockerAfterBattleText"] = "Sei solo al 5°\npiano. La strada\vper il CAPO é\nlunga!",
  ["_SilphCo5FRockerBattleText"] = "Cosa? Non\ndovrebbero\vesserci bambini!",
  ["_SilphCo5FRockerEndBattleText"] = "Oh cielo!",
  ["_SilphCo5FRocket1AfterBattleText"] = "Non é saggio\nattaccare briga\vcol TEAM ROCKET!",
  ["_SilphCo5FRocket1BattleText"] = "Ho sentito che un\nbimbo gironzola.",
  ["_SilphCo5FRocket1EndBattleText"] = "Boom!",
  ["_SilphCo5FRocket2AfterBattleText"] = "A proposito.\nKOFFING si evolve\vin WEEZING!",
  ["_SilphCo5FRocket2BattleText"] = "Rispetta un po' il\nTEAM ROCKET!",
  ["_SilphCo5FRocket2EndBattleText"] = "Cof...\nCof...",
  ["_SilphCo5FScientistAfterBattleText"] = "Lavoravamo alla\nsuper POKé BALL\vche catturava\nqualsiasi cosa!",
  ["_SilphCo5FScientistBattleText"] = "Studiamo le POKé\nBALL su questo\vpiano!",
  ["_SilphCo5FScientistEndBattleText"] = "\nAccidenti!\vDannazione!",
  ["_SilphCo5FSilphWorkerMThatsYouRightText"] = "Il TEAM ROCKET é\nin subbuglio per\vun intruso. Sei\ntu?",
  ["_SilphCo5FSilphWorkerMYoureOurHeroText"] = "Il TEAM ROCKET é\nfuggito! Sei il\vnostro eroe!",
  ["_SilphCo6FRocket1AfterBattleText"] = "Non importa! I\nmiei fratelli mi\vvendicheranno!",
  ["_SilphCo6FRocket1BattleText"] = "Sono uno dei 4\nFRATELLI ROCKET!",
  ["_SilphCo6FRocket1EndBattleText"] = "Fiamma\nspenta!",
  ["_SilphCo6FRocket2AfterBattleText"] = "Chi sta con la\ngiustizia,\vtradisce il male!",
  ["_SilphCo6FRocket2BattleText"] = "Osi tradire il\nTEAM ROCKET?",
  ["_SilphCo6FRocket2EndBattleText"] = "Traditore!",
  ["_SilphCo6FScientistAfterBattleText"] = "FILIALE ESTERNA? é\nin una zona\vdavvero remota!",
  ["_SilphCo6FScientistBattleText"] = "Quel marrano del\nPRESIDENTE! Non\vdoveva man darmi\nin questa filiale\vsperduta!",
  ["_SilphCo6FScientistEndBattleText"] = "\nAccidenti!",
  ["_SilphCo6FSilphWorkerF1HaveToMarryHimText"] = "Mi dispiace tanto\nper lui, lo devo\vsposare!",
  ["_SilphCo6FSilphWorkerF1SuchACowardText"] = "Guardalo! é un\nvero codardo!",
  ["_SilphCo6FSilphWorkerF2TeamRocketConquerWorldText"] = "Il TEAM ROCKET\nvuole conquistare\vil mondo coi\nPOKéMON!",
  ["_SilphCo6FSilphWorkerF2TeamRocketRanText"] = "Il TEAM ROCKET é\nfuggito per colpa\vtua!",
  ["_SilphCo6FSilphWorkerM1BackToWorkText"] = "Bene, é ora di\ntornare al\vlavoro!",
  ["_SilphCo6FSilphWorkerM1TookOverTheBuildingText"] = "I ROCKET sono\nvenuti a occupare\vl'edificio!",
  ["_SilphCo6FSilphWorkerM3TargetedSilphText"] = "Avranno preso di\nmira la SILPH per\vi nostri prodotti.",
  ["_SilphCo6FSilphWorkerM3WorkForSilphText"] = "Vieni a lavorare\nalla SILPH quando\vsarai grande!",
  ["_SilphCo6FSilphWorkerMHelpMePleaseText"] = "Mio Dio, aiuto!\nAiutami ti prego!",
  ["_SilphCo6FSilphWorkerMWeGotEngagedText"] = "Ci siamo\nfidanzati!\vEheheh!",
  ["_SilphCo7FRivalDefeatedText"] = "Oh ho!\nSei pronto per il\vCAPO ROCKET!",
  ["_SilphCo7FRivalGoodLuckToYouText"] = "Beh,\n{PLAYER}! Vado\vavanti e sopra!\nGuardando il mio\vPOKéDEX capisco\nchi é forte e\vcome si evolvono!\nVado alla LEGA\vPOKéMON a\nsconfiggere i\vSUPERQUATTRO!\nDiventero' il\vpiu' forte\nallenatore!\v{PLAYER}, buona\nfortuna! Ci si\vvede!",
  ["_SilphCo7FRivalText"] = "{RIVAL}: Cosa ti\nha trattenuto?",
  ["_SilphCo7FRivalVictoryText"] = "{RIVAL}:\nCome dire? Non\vsei ancora pronto\nper giocare con i\vgrandi!",
  ["_SilphCo7FRivalWaitedHereText"] = "{RIVAL}: Ahahah!\nSapevo che\vsaresti venuto! Il\nTEAM ROCKET ti ha\vrallentato! Ti ho\nvisto a\vZAFFERANOPOLI e ho\nvoluto vedere se\vsei migliorato!",
  ["_SilphCo7FRocket1AfterBattleText"] = "Non troverai il\nmio CAPO girando\va caso!",
  ["_SilphCo7FRocket1BattleText"] = "Oh ho! Sento puzza\ndi topo!",
  ["_SilphCo7FRocket1EndBattleText"] = "Luce\nspenta!",
  ["_SilphCo7FRocket2AfterBattleText"] = "Non importa. I\nmiei fratelli\vrenderanno il\nfavore!",
  ["_SilphCo7FRocket2BattleText"] = "Sono uno dei 4\nFRATELLI ROCKET!",
  ["_SilphCo7FRocket2EndBattleText"] = "Aack!\nFratelli, ho\vperso!",
  ["_SilphCo7FRocket3AfterBattleText"] = "Vattene a casa\nprima che il CAPO\vsi arrabbi!",
  ["_SilphCo7FRocket3BattleText"] = "Un bimbo intruso?\nSarai tu!",
  ["_SilphCo7FRocket3EndBattleText"] = "Va bene!\nHo perso!",
  ["_SilphCo7FScientistAfterBattleText"] = "Nonostante l'eta',\nsei un abile\vallenatore!",
  ["_SilphCo7FScientistBattleText"] = "Eheheh! Mi hai\nscambiato per un\voperaio?",
  ["_SilphCo7FScientistEndBattleText"] = "Ho\nchiuso!",
  ["_SilphCo7FSilphWorkerM1HaveThisPokemonText"] = "Oh! Ciao! Non sei\nun ROCKET! Sei\vvenuto a salvarci?\nGrazie! Voglio\vdarti un POKéMON\nper questo.",
  ["_SilphCo7FSilphWorkerM1IsOurPresidentOkText"] = "Il CAPO del ROCKET\né nella sala! Il\vPRESIDENTE sta\nbene?",
  ["_SilphCo7FSilphWorkerM1LaprasDescriptionText"] = "é un LAPRAS, molto\nintelligente. Era\vnel laboratorio ma\nstara' meglio con\vte! Penso che\nsarai un buon\vallenatore! é un\nottimo nuo tore,\vti dara' un\npassaggio!",
  ["_SilphCo7FSilphWorkerM1SavedText"] = "Salvo alla fine!\nGrazie!",
  ["_SilphCo7FSilphWorkerM2AfterTheMasterBallText"] = "Il TEAM ROCKET\nvoleva la MASTER\vBALL per catturare\nqualsiasi\vPOKéMON!",
  ["_SilphCo7FSilphWorkerM2CancelledMasterBallText"] = "Abbiamo chiuso il\nprogetto MASTER\vBALL per colpa del\nTEAM ROCKET.",
  ["_SilphCo7FSilphWorkerM3ItWouldBeBadText"] = "Sarebbe un guaio\nse il TEAM ROCKET\vprendesse la SILPH\no i nostri\vPOKéMON!",
  ["_SilphCo7FSilphWorkerM3YouChasedOffTeamRocketText"] = "Wow! Hai messo in\nfuga il TEAM\vROCKET da solo?",
  ["_SilphCo7FSilphWorkerM4ItsReallyDangerousHereText"] = "Tu! Qui é peri\ncoloso! Sei\vvenuto a salvarmi?\nNon puoi!",
  ["_SilphCo7FSilphWorkerM4SafeAtLastText"] = "Al sicuro! Oh\ngrazie!",
  ["_SilphCo8FRocket1AfterBattleText"] = "Se non torni\nindietro, chiamo\vrinforzi!",
  ["_SilphCo8FRocket1BattleText"] = "Da qui non\npasserai!",
  ["_SilphCo8FRocket1EndBattleText"] = "Manca la\ngrinta!",
  ["_SilphCo8FRocket2AfterBattleText"] = "Lascio fare ai\nmiei fratelli!",
  ["_SilphCo8FRocket2BattleText"] = "Sono uno dei 4\nFRATELLI ROCKET!",
  ["_SilphCo8FRocket2EndBattleText"] = "Whoo! Oh\nfratelli!",
  ["_SilphCo8FScientistAfterBattleText"] = "Allora, che ne\npensi del labiri\vnto della SILPH?",
  ["_SilphCo8FScientistBattleText"] = "Ci stai creando\nproblemi!",
  ["_SilphCo8FScientistEndBattleText"] = "Eh? Ho\nperso?",
  ["_SilphCo8FSilphWorkerMSilphIsFinishedText"] = "Chissa' se la\nSILPH é finita...",
  ["_SilphCo8FSilphWorkerMThanksForSavingUsText"] = "Grazie per averci\nsalvati!",
  ["_SilphCo9FRocket1AfterBattleText"] = "Se avessi iniziato\nalla tua eta'...",
  ["_SilphCo9FRocket1BattleText"] = "I tuoi POKéMON ti\nadorano, ragazzo!",
  ["_SilphCo9FRocket1EndBattleText"] = "Ghaaah!",
  ["_SilphCo9FRocket2AfterBattleText"] = "I miei fratelli mi\nvendicheranno!",
  ["_SilphCo9FRocket2BattleText"] = "Sono uno dei 4\nFRATELLI ROCKET!",
  ["_SilphCo9FRocket2EndBattleText"] = "Warg!\nFratelli, ho\vperso!",
  ["_SilphCo9FScientistAfterBattleText"] = "Sfruttare i punti\ndeboli funziona!\vPensa ai tipi\nelementali!",
  ["_SilphCo9FScientistBattleText"] = "I tuoi POKéMON\nhanno debolezze!\vLe colpiro'!",
  ["_SilphCo9FScientistEndBattleText"] = "Mi hai\ndistrutto!",
  ["_SkyAttackGlowingText"] = "sta brillando!",
  ["_SoYouWantPrizeText"] = "Quindi vuoi\n{RAM:wNameBuffer}?",
  ["_SorryNeedMoreCoinsText"] = "Spiacente, ti\nservono piu'\vgettoni.",
  ["_StartSlotMachineText"] = "Via!",
  ["_StartedSleepingEffect"] = "{USER}\nsi é\vaddormentato!",
