  ["_SwitchOnText"] = "Interruttore ON!",
  ["_TM21ExplanationText"] = "La MT21 contiene\nMEGAASSORBIMENTO.\vDrena meta' del\ndanno inflitto\vper curare i tuoi!",
  ["_TM24ExplanationText"] = "La MT24 contiene\nFULMINE!\vInsegnalo a un\nPOKéMON elettro!",
  ["_TM34ExplanationText"] = "Una MT contiene\nuna tecnica da\vinsegnare ai\nPOKéMON! Una MT é\vmono uso! Scegli\nbene il POKéMON!\vLa MT34 contiene\nPAZIENZA! Il\vPOKéMON subisce e\nrestituisce il\vdoppio del danno!",
  ["_TM46ExplanationText"] = "La MT46 é PSICO\nONDA! Usa onde\vpsichiche per\ninfliggere danni!",
