  ["_TrainerSentOutText"] = "{RAM:wTrainerName} manda\n{RAM:wEnemyMonNick}!",
  ["_TrainerWantsToFightText"] = "{RAM:wTrainerName}\nvuole lottare!",
  ["_TransformedText"] = "{USER}\nsi é trasformato\vin {RAM:wNameBuffer}!",
  ["_TryingToLearnText"] = "{RAM:wLearnMoveMonName} prova a\nimparare\v{RAM:wStringBuffer}! Ma non\npuo' cono scere\vpiu' di 4 mosse!\nCancellare una\vvecchia mossa per\n{RAM:wStringBuffer}?",
  ["_TurnPageText"] = "Giri pagina?",
  ["_TurnedAwayText"] = "{RAM:wBattleMonNick} si é\ntirato indietro!",
  ["_TurnedOnPC1Text"] = "{PLAYER} accende il\nPC.",
  ["_TurnedOnPC2Text"] = "{PLAYER} accende il\nPC.",
  ["_UnaffectedText"] = "{TARGET}\nnon subisce\veffetti!",
  ["_UndergroundPathRoute6GirlText"] = "La gente perde\nsempre cose in\vquel PASSAGGIO\nSOTTERRANEO.",
  ["_UndergroundPathRoute7CopyUnusedGirlText"] = "Voglio fare acqui\nsti al centro com\vmerciale ma... Ci\nsono troppe facce\vlosche li'.",
  ["_UndergroundPathRoute7CopyUnusedGoesUnderSaffronText"] = "Il PASSAGGIO passa\nsotto\vZAFFERANOPOLI e\nporta a\vLAVANDONIA. Per\nCELESTOPOLI, usa\vl'edificio\ndall'altra parte.",
  ["_UndergroundPathRoute7CopyUnusedMiddleAgedManText"] = "Vuoi fare acquisti\na AZZURROPOLI?\vEsci e vai a\novest!",
  ["_UndergroundPathRoute7CopyUnusedTeamRocketHadAHideoutText"] = "Il TEAM ROCKET\naveva un covo a\vAZZURROPOLI?",
  ["_UndergroundPathRoute7MiddleAgedManText"] = "Ho sentito che un\nPOKéMON\vdormiglione é\napparso a\vAZZURROPOLI.",
  ["_UndergroundPathRoute8GirlText"] = "Il centro\ncommerciale di\vAZZURROPOLI é\nfornitissimo!",
  ["_UnleashedEnergyText"] = "{USER}\nha scatenato\venergia!",
  ["_UnusedBenchGuyText1"] = "Vorrei tanto cat\nturare POKéMON.",
  ["_UnusedBenchGuyText2"] = "Sono stanco di\ntutto questo\vsvago...",
  ["_UnusedBenchGuyText3"] = "Il manager SILPH é\nnascosto nel\vSAFARI.",
  ["_UnveiledGhostText"] = "La SONDA SILPH ha\nsvelato\vl'identita' del\nFANTASMA!",
  ["_UseNextMonText"] = "Usa il prossimo?",
  ["_UsedCutText"] = "{RAM:wNameBuffer} ha\ntranciato con\vTAGLIO!",
  ["_UsedInsteadText"] = "invece,",
  ["_UsedMove1Text"] = "usa",
  ["_UsedMove2Text"] = "usa",
  ["_UsedStrengthText"] = "{RAM:wNameBuffer} usa\nFORZA.",
  ["_VendingMachineText1"] = "Un distributore!\nEcco il menu!",
  ["_VendingMachineText4"] = "Ops, soldi\ninsufficienti!",
  ["_VendingMachineText5"] = "{RAM:wStringBuffer} é\nuscito!",
  ["_VendingMachineText6"] = "Non c'é piu'\nspazio per roba!",
  ["_VendingMachineText7"] = "Non ho sete!",
  ["_VermilionCityBeautyText"] = "Siamo attenti\nall'inquinamento!\vGRIMER si multi\nplica nel fango\vtossico!",
  ["_VermilionCityGambler1DidYouSeeText"] = "Hai visto la M/N\nANNA ormeggiata\val porto?",
  ["_VermilionCityGambler1SSAnneDepartedText"] = "La M/N ANNA é\npartita! Tornera'\vtra circa un anno.",
  ["_VermilionCityGambler2Text"] = "Sto costruendo un\npalazzo qui. Il\vmio POKéMON sta\nspianando il\vsuolo.",
  ["_VermilionCityGymSignText"] = "PALESTRA POKéMON\nDI ARANCIOPOLI\vCAPOPALESTRA:\nLT.SURGE Il\vluogotenente\nfulmineo!",
  ["_VermilionCityHarborSignText"] = "PORTO DI\nARANCIOPOLI",
  ["_VermilionCityMachopStompingTheLandFlatText"] = "Un MACHOP sta\nspianando il\vterreno.",
  ["_VermilionCityMachopText"] = "MACHOP: Guoh!\nGogogoh!",
  ["_VermilionCityNoticeSignText"] = "AVVISO! Il\nPERCORSO 12 é\vbloccato da un\nPOKéMON\vaddormentato.\nDeviazione per il\vTUNNEL ROCCIOSO\nper LAVANDONIA.\vPOLIZIA\nARANCIOPOLI",
  ["_VermilionCityPokemonFanClubSignText"] = "FAN CLUB POKéMON\nBenvenuti fan dei\vPOKéMON!",
  ["_VermilionCitySailor1DoYouHaveATicketText"] = "Benvenuto sulla\nM/N ANNA! Scusa,\vhai un biglietto?",
  ["_VermilionCitySailor1FlashedTicketText"] = "{PLAYER} mostra il\nTICKET. Bene!\vBenvenuto sulla\nM/N ANNA!",
  ["_VermilionCitySailor1ShipSetSailText"] = "La nave é salpata.",
  ["_VermilionCitySailor1WelcomeToSSAnneText"] = "Benvenuto sulla\nM/N ANNA!",
  ["_VermilionCitySailor1YouNeedATicketText"] = "{PLAYER} non ha il\nnecessario\vTICKET. Spiacente!\nServe un\vbiglietto per\nsalire a bordo.",
  ["_VermilionCitySailor2Text"] = "La M/N ANNA é una\nlussuosa nave da\vcrociera.\nVisitiamo\vARANCIOPOLI una\nvolta l'anno.",
  ["_VermilionCitySignText"] = "ARANCIOPOLI Porto\ndei tramonti\vsquisiti",
  ["_VermilionGymGentlemanAfterBattleText"] = "La porta non si\napre? LT.SURGE é\vsempre stato\nprudente!",
  ["_VermilionGymGentlemanBattleText"] = "Ero nell'esercito,\ne LT.SURGE era il\vmio sergente!",
  ["_VermilionGymGentlemanEndBattleText"] = "Basta!\nSei bravissimo!",
  ["_VermilionGymGymGuideBeatLTSurgeText"] = "Uff! Quella lotta\nera\velettrizzante!",
  ["_VermilionGymGymGuideChampInMakingText"] = "Ehila'! Campione!\nLT.SURGE ha un\vsoprannome: il\nFulmine\vAmericano! é un\nesperto di\vPOKéMON elettro! I\nvolatili e\vl'acqua rischiano\nmolto! Attento\vanche alla\nparalisi!\vLT.SURGE é molto\ncauto! Dovrai\vviolare un codice\nper arrivargli!",
  ["_VermilionGymLTSurgePostBattleAdviceText"] = "Un piccolo consi\nglio, ragazzo!\vL'elettricita' é\npotente! Ma é\vinutile con i\nPOKéMON terra!",
  ["_VermilionGymLTSurgePreBattleText"] = "Ehi, ragazzo! Che\nfai qui? Non\vdurerai molto in\ncombattimento! Te\vlo assicuro! I\nPOKéMON elettro\vmi hanno salvato\ndurante la\vguerra! Hanno\nfulminato i miei\vnemici! Faro' lo\nstesso con te!",
  ["_VermilionGymLTSurgeReceivedTM24Text"] = "{PLAYER} riceve\n{RAM:wStringBuffer}!",
  ["_VermilionGymLTSurgeReceivedThunderBadgeText"] = "Urca! Sei davvero\nin gamba,\vragazzo! Prendi la\nMEDAGLIA TUONO!",
  ["_VermilionGymLTSurgeTM24NoRoomText"] = "Ragazzo, fai\nspazio nel tuo\vzaino!",
  ["_VermilionGymLTSurgeThunderBadgeInfoText"] = "La MEDAGLIA TUONO\naccende la\vVELOCITA' del tuo\nPOKéMON! Ti\vpermette anche di\nusare FLASH! Sei\vspeciale! Prendi\nquesto!",
  ["_VermilionGymSailorAfterBattleText"] = "LT.SURGE ha messo\ndue serrature! Un\vindizio! La\nseconda é sem pre\vvicina alla prima\naperta!",
  ["_VermilionGymSailorBattleText"] = "Questo non é un\nposto per\vbambini!",
  ["_VermilionGymSailorEndBattleText"] = "Wow! Che\nsorpresa!",
  ["_VermilionGymSuperNerdAfterBattleText"] = "OK, parlo!\nLT.SURGE ha\vnascosto gli\ninterruttori\vdentro qualcosa!",
  ["_VermilionGymSuperNerdBattleText"] = "Sono un peso\nleggero, ma me la\vcavo con\nl'elettricita'",
  ["_VermilionGymSuperNerdEndBattleText"] = "\nFolgorato!",
  ["_VermilionGymTrashFailTest"] = "No! C'é solo\nspazzatura. Ehi!\vLe serrature\nelettriche sono\vstate azzerate!",
  ["_VermilionGymTrashSuccessText1"] = "Ehi! C'é un\ninterruttore\vsotto la\nspazzatura!\vAttivalo! La 1ª\nserratura si é\vaperta!",
  ["_VermilionGymTrashSuccessText2"] = "Ehi! C'é un altro\ninterruttore\vsotto la\nspazzatura!\vAttivalo!",
  ["_VermilionGymTrashSuccessText3"] = "La 2ª serratura si\né aperta! La\vporta motoriz zata\nsi apre!",
  ["_VermilionGymTrashText"] = "No, c'é solo\nspazzatura qui.",
  ["_VermilionMartCooltrainerFText"] = "I POKéMON possono\nessere buoni o\vcattivi a seconda\ndell'allenatore.",
  ["_VermilionMartCooltrainerMText"] = "Ci sono persone\ncattive che usano\vi POKéMON per\ndelitti. Il TEAM\vROCKET tratta\nPOKéMON rari e\vabbandona quelli\nche non ritiene\vutili.",
  ["_VermilionOldRodHouseFishingGuruDoYouLikeToFishText"] = "Sono il GURU\nPESCATORE! Adoro\vpescare! Ti piace\npescare?",
  ["_VermilionOldRodHouseFishingGuruFishingIsAWayOfLifeText"] = "La pesca é uno\nstile di vita!\vDai mari ai fiumi,\nesci e prendi\vquello grosso!",
  ["_VermilionOldRodHouseFishingGuruHowAreTheFishBitingText"] = "Ciao, {PLAYER}!\nAboccano i pesci?",
  ["_VermilionOldRodHouseFishingGuruNoRoomText"] = "Oh no! Non hai\nspazio per il mio\vdono!",
  ["_VermilionOldRodHouseFishingGuruTakeThisText"] = "Ottimo! Mi piace\nil tuo stile!\vPrendi questo,\ngiovane! {PLAYER}\vriceve un\n{RAM:wStringBuffer}!",
  ["_VermilionOldRodHouseFishingGuruThatsSoDisappointingText"] = "Oh... Che delu\nsione...",
  ["_VermilionPidgeyHouseLetterText"] = "Cara PIPPI, spero\ndi vederti\vpresto. Ho sentito\nche ZAFFERANOPOLI\vha guai col TEAM\nROCKET.\vARANCIOPOLI sembra\nincolume.",
  ["_VermilionPidgeyHousePidgeyText"] = "PIDGEY: Kurukkoo!",
  ["_VermilionPidgeyHouseYoungsterText"] = "Mando il mio\nPIDGEY a portare\vuna lettera a\nZAFFERANOPOLI!",
  ["_VermilionPokecenterFishingGuruText"] = "Anche allo stesso\nlivello, i\vPOKéMON hanno\nabilita' molto\vdiverse. Un\nPOKéMON alleva to\vé piu' forte di\nuno selvatico.",
  ["_VermilionPokecenterGuyText"] = "é vero che un\nlivello piu' alto\vrende piu'\nforte... Ma ogni\vPOKéMON ha punti\ndeboli verso\valtri tipi. Quindi\nnon esiste il\vPOKéMON asso\nassoluto.",
  ["_VermilionPokecenterSailorText"] = "Il mio POKéMON era\navvelenato! é an\vdato K.O. mentre\ncamminavamo!",
  ["_VictoryRoad1FCooltrainerFAfterBattleText"] = "Non volevo per\ndere con nessuno!",
  ["_VictoryRoad1FCooltrainerFBattleText"] = "Chissa' se sei\nall'altezza!",
  ["_VictoryRoad1FCooltrainerFEndBattleText"] = "Ho\nperso!",
  ["_VictoryRoad1FCooltrainerMAfterBattleText"] = "Lo ammetto, sei\npiu' bravo di me!",
  ["_VictoryRoad1FCooltrainerMBattleText"] = "Vedo che vali!\nFammi vedere\vquanto vali!",
  ["_VictoryRoad1FCooltrainerMEndBattleText"] = "Ci\nsperavo...",
  ["_VictoryRoad2FCooltrainerMAfterBattleText"] = "Ti sei meritato la\nVIA VITTORIA!",
  ["_VictoryRoad2FCooltrainerMBattleText"] = "Avanti! Ti concio\nper le feste!",
  ["_VictoryRoad2FCooltrainerMEndBattleText"] = "Mi\nhanno suonato!",
  ["_VictoryRoad2FHikerAfterBattleText"] = "Se ti blocchi,\nprova a spostare\vqualche masso!",
  ["_VictoryRoad2FHikerBattleText"] = "La VIA VITTORIA é\nil test finale\vper gli\nallenatori!",
  ["_VictoryRoad2FHikerEndBattleText"] = "Aiyah!",
  ["_VictoryRoad2FMoltresBattleText"] = "Gyaoo!",
  ["_VictoryRoad2FSuperNerd1AfterBattleText"] = "Anche {RIVAL} é\npassato di qui!",
  ["_VictoryRoad2FSuperNerd1BattleText"] = "Ah, vuoi sfidare i\nSUPERQUATTRO?",
  ["_VictoryRoad2FSuperNerd1EndBattleText"] = "Mi hai\npreso!",
  ["_VictoryRoad2FSuperNerd2AfterBattleText"] = "Posso batterti in\nquanto a\vconoscenza\nPOKéMON!",
  ["_VictoryRoad2FSuperNerd2BattleText"] = "Se passi di qui,\npuoi incontrare i\vSUPERQUATTRO!",
  ["_VictoryRoad2FSuperNerd2EndBattleText"] = "No!\nIncredibile!",
  ["_VictoryRoad2FSuperNerd3AfterBattleText"] = "Molti allenatori\nrinunciano qui.",
  ["_VictoryRoad2FSuperNerd3BattleText"] = "La VIA VITTORIA é\ntroppo dura?",
  ["_VictoryRoad2FSuperNerd3EndBattleText"] = "Ben\nfatto!",
  ["_VictoryRoad3FCooltrainerF1AfterBattleText"] = "Mi hai mostrato\nquanto valgo!",
  ["_VictoryRoad3FCooltrainerF1BattleText"] = "Ti mostrero'\nquanto vali!",
  ["_VictoryRoad3FCooltrainerF1EndBattleText"] = "Sono\nfuriosa!",
  ["_VictoryRoad3FCooltrainerF2AfterBattleText"] = "Lottando duro, si\ndiventa forti!",
  ["_VictoryRoad3FCooltrainerF2BattleText"] = "Gli allenatori\ncerchano rivali\vpiu' forti!",
  ["_VictoryRoad3FCooltrainerF2EndBattleText"] = "Oh!\nChe forza!",
  ["_VictoryRoad3FCooltrainerM1AfterBattleText"] = "Hai battuto\nGIOVANNI del TEAM\vROCKET?",
  ["_VictoryRoad3FCooltrainerM1BattleText"] = "Ho sentito voci di\nun bimbo\vprodigio!",
  ["_VictoryRoad3FCooltrainerM1EndBattleText"] = "Le\nvoci erano vere!",
  ["_VictoryRoad3FCooltrainerM2AfterBattleText"] = "Tutti qui vanno\nalla LEGA\vPOKéMON! Attento!",
  ["_VictoryRoad3FCooltrainerM2BattleText"] = "Solo i prescelti\npassano di qui!",
  ["_VictoryRoad3FCooltrainerM2EndBattleText"] = "Non\nci posso credere!",
  ["_ViridianBlackboardBurnText"] = "Una scottatura\nriduce potenza e\vvelocita' e causa\ndanni continui.\vResta anche dopo\nla lotta. Usa\vANTIBRUCIATURA!",
  ["_ViridianBlackboardFrozenText"] = "Se congelato, un\nPOKéMON resta\vimmobile! Non si\nscongela neppure\vdopo la lotta. Usa\nANTIGELO!",
  ["_ViridianBlackboardPoisonText"] = "Da avvelenato, la\nsalute cala\vsempre. Il veleno\nresta anche dopo\vla lotta. Usa un\nANTIDOTO per\vguarirlo!",
  ["_ViridianBlackboardPrlzText"] = "La paralisi puo'\nfallire le mosse!\vResta anche dopo\nla lotta. Usa\vl'ANTIPARALISI per\ncurarlo!",
  ["_ViridianBlackboardSleepText"] = "Un POKéMON non\nattacca se dorme!\vResta addormentato\nanche dopo la\vlotta. Usa la\nSVEGLIA per\vsvegliarlo!",
  ["_ViridianCityFisherReceivedTM42Text"] = "{PLAYER} riceve la\nMT42!",
  ["_ViridianCityFisherTM42ExplanationText"] = "La MT42 contiene\nSOGNIDORO...\v...Ronf...",
  ["_ViridianCityFisherTM42NoRoomText"] = "Hai gia' troppa\nroba con te.",
  ["_ViridianCityGambler1GymAlwaysClosedText"] = "Questa palestra é\nsempre chiusa.\vChissa' chi é il\nCAPOPALESTRA?",
  ["_ViridianCityGambler1GymLeaderReturnedText"] = "Il CAPOPALESTRA é\ntornato!",
  ["_ViridianCityGirlHasntHadHisCoffeeYetText"] = "Oh nonno! Non\nessere cattivo!\vNon ha ancora\nbevuto il caffé.",
  ["_ViridianCityGirlWhenIGoShopText"] = "Quando vado a\nPLUMBEOPOLI, devo\vfare il sentiero\ndel BOSCO\vSMERALDO.",
  ["_ViridianCityGymLockedText"] = "Le porte della\npalestra sono\vchiuse",
  ["_ViridianCityGymSignText"] = "PALESTRA POKéMON\nDI SMERALDOPOLI\vCAPOPALESTRA: ???",
  ["_ViridianCityOldManHadMyCoffeeNowText"] = "Ahh, ho bevuto il\ncaffé e sto bene!\vOra puoi passare!\nHai fretta?",
  ["_ViridianCityOldManKnowHowToCatchPokemonText"] = "Usi il POKéDEX,\nvedo. Catturando\vun POKéMON si\naggiorna\vautomaticamente.\nChe c'é? Non sai\vcome catturarli?\nTe lo mostro io.",
  ["_ViridianCityOldManSleepyPrivatePropertyText"] = "Non puoi passare!\nQuesta é\vproprieta'\nprivata!",
  ["_ViridianCityOldManTimeIsMoneyText"] = "Il tempo é\ndenaro...\vCammina.",
  ["_ViridianCityOldManYouNeedToTheTargetText"] = "Prima devi indebo\nlire il POKéMON.",
  ["_ViridianCityPokecenterGuyText"] = "I CENTRI POKéMON\ncurano i POKéMON\vstanchi, feriti o\nesausti!",
  ["_ViridianCitySignText"] = "SMERALDOPOLI Il\nVerde Paradiso\vEterno",
  ["_ViridianCityTrainerTips1Text"] = "CONSIGLI UTILI\nCattura POKéMON e\vamplia la tua\ncollezione! Piu'\vne hai, piu' é\nfacile lottare!",
  ["_ViridianCityTrainerTips2Text"] = "CONSIGLI UTILI Le\nmosse dei POKéMON\vdipendono dai\nPUNTI POTERE, PP.\vRipristinali ripo\nsando al CENTRO\vPOKéMON!",
  ["_ViridianCityYoungster1Text"] = "Quelle POKé BALL\nalla cintura! Hai\vdei POKéMON! E'\nbello poterli\vportare e usare\novunque e sempre!",
  ["_ViridianCityYoungster2YouWantToKnowAboutText"] = "Vuoi sapere dei 2\ntipi di POKéMON\vbruco?",
  ["_ViridianForestLeavingSignText"] = "USCITA BOSCO\nSMERALDO\vPLUMBEOPOLI PIU'\nAVANTI",
  ["_ViridianForestNorthGateGrampsText"] = "Hai notato i\ncespugli lungo la\vstrada? Possono\nessere tagliati\vda una mossa\nspeciale.",
  ["_ViridianForestNorthGateSuperNerdText"] = "Molti POKéMON vi\nvono solo nei\vboschi e grotte.\nDevi cercare ovun\vque per trovarli!",
  ["_ViridianForestSouthGateGirlText"] = "Vai al BOSCO\nSMERALDO?\vAttento, é un\nlabirinto!",
  ["_ViridianForestSouthGateLittleGirlText"] = "RATTATA é piccolo,\nma il suo morso é\vferoce! Ne hai\nuno?",
  ["_ViridianForestTrainerTips1Text"] = "CONSIGLI UTILI Se\nvuoi evitare\vlotte, stai\nlontano dall'erba\valta!",
  ["_ViridianForestTrainerTips2Text"] = "CONSIGLI UTILI\nContatta il\vPROF.OAK dal PC\nper far valutare\vil POKéDEX!",
  ["_ViridianForestTrainerTips3Text"] = "CONSIGLI UTILI Non\nrubare POKéMON\valtrui! Cattura\nsolo quelli\vselvatici!",
  ["_ViridianForestTrainerTips4Text"] = "CONSIGLI UTILI\nIndebolisci i\vPOKéMON prima di\ncatturarli! Se\vsani, possono\nfuggire!",
  ["_ViridianForestUseAntidoteSignText"] = "Per il veleno, usa\nl'ANTIDOTO! Nei\vPOKéMON MART!",
  ["_ViridianForestYoungster1Text"] = "Sono\nvenuto qui con\vdegli amici!\nCercano lotte con\vi POKéMON!",
  ["_ViridianForestYoungster2AfterBattleText"] = "Ssh!\nSpaventerai gli\vinsetti!",
  ["_ViridianForestYoungster2BattleText"] = "Ehi!\nHai POKéMON!\vForza, lottiamo!",
  ["_ViridianForestYoungster2EndBattleText"] = "No!\nCATERPIE non ce\vla fa!",
  ["_ViridianForestYoungster3AfterBattleText"] = "\nAccidenti! Ne\vcaturero' di piu'\nforti!",
  ["_ViridianForestYoungster3BattleText"] = "Ehi!\nNon puoi farti\vvalere se sei un\nallenatore!",
  ["_ViridianForestYoungster3EndBattleText"] = "Eh?\nHo finito i\vPOKéMON!",
  ["_ViridianForestYoungster4AfterBattleText"] = "A\nvolte trovi roba\vper terra! Cerco\nquello che ho\vperso io!",
  ["_ViridianForestYoungster4BattleText"] = "Ehi,\naspetta! Tanta\vfretta?",
  ["_ViridianForestYoungster4EndBattleText"] = "Mi\narrendo! Sei\vbravo in questo!",
  ["_ViridianForestYoungster5Text"] = "Ho\nfinito le POKé\vBALL per cattura\nre i POKéMON!\vPortane sempre di\nscorta!",
  ["_ViridianGymCooltrainerM1AfterBattleText"] = "Serve potenza per\nreggere il ritmo\vdel nostro CAPO!",
  ["_ViridianGymCooltrainerM1BattleText"] = "Heh! Ti stara'\nfinendo il fiato!",
  ["_ViridianGymCooltrainerM1EndBattleText"] = "Ho\nesaurito la\vspinta!",
  ["_ViridianGymCooltrainerM2AfterBattleText"] = "Il CAPO mi\nsgridera'!",
  ["_ViridianGymCooltrainerM2BattleText"] = "I veri talenti\nvincono con\vstile!",
  ["_ViridianGymCooltrainerM2EndBattleText"] = "Ho\nperso la presa!",
  ["_ViridianGymCooltrainerM3AfterBattleText"] = "Puoi andare alla\nLEGA POKéMON solo\vbattendo il CAPO!",
  ["_ViridianGymCooltrainerM3BattleText"] = "La palestra fu\nchiusa a lungo,\vma ora il CAPO é\ntornato!",
  ["_ViridianGymCooltrainerM3EndBattleText"] = "Sono\nstato battuto?",
  ["_ViridianGymGiovanniEarthBadgeInfoText"] = "La MEDAGLIA TERRA\nfa' ubbidire i\vPOKéMON di ogni\nlivello! é la\vprova della tua\nmaestria! Con\vessa puoi entrare\nnella LEGA! é il\vmio dono per la\ntua sfida!",
  ["_ViridianGymGiovanniPostBattleAdviceText"] = "Avendo perso, non\nposso guar dare i\vsubordinati! Il\nTEAM ROCKET é\vfinito per sempre!\nDedicchero' la\vmia vita allo\nstudio! Ci\vrivedremo un\ngiorno! Addio!",
  ["_ViridianGymGiovanniPreBattleText"] = "Fwahahaha! Questo\né il mio covo!\vVolevo risurreci\ntare il ROCKET\vqui! Ma mi hai\nripreso! E sia!\vStavolta non mi\ntrattengo!\vAffronterai\nGIOVANNI , il\vpiu' grande!",
  ["_ViridianGymGiovanniReceivedEarthBadgeText"] = "Ha! Una lotta\nintensa! Hai\vvinto! Ecco la\nprova con la\vMEDAGLIA TERRA!",
  ["_ViridianGymGiovanniReceivedTM27Text"] = "{PLAYER} riceve la\nMT27!",
  ["_ViridianGymGiovanniTM27ExplanationText"] = "La MT27 é ABISSO!\nStende i POKéMON\vcon un sol colpo!\nLa feci quando\vgestivo la\npalestra, molto\vtempo fa...",
  ["_ViridianGymGiovanniTM27NoRoomText"] = "Non hai spazio per\nquesto!",
  ["_ViridianGymGuidePostBattleText"] = "Incredibile!\nGIOVANNI era il\vCAPOPALESTRA qui?",
  ["_ViridianGymGuidePreBattleText"] = "Ehila'! Campione!\nNeanche io so chi\vsia il CAPO di\nQUI! Sara' il\vpiu' duro di tutti\ni capi! Ho\vsentito che amano\ni POKéMON di tipo\vterra!",
  ["_ViridianGymHiker1AfterBattleText"] = "Non sono ancora\ndegno!",
  ["_ViridianGymHiker1BattleText"] = "Rrrroar! Mi sto\ninfuriando!",
  ["_ViridianGymHiker1EndBattleText"] = "Wargh!",
  ["_ViridianGymHiker2AfterBattleText"] = "Se i miei POKéMON\nfossero bravi a\vKarate come me...",
  ["_ViridianGymHiker2BattleText"] = "Il karate é la\nforma suprema di\varti marziali!",
  ["_ViridianGymHiker2EndBattleText"] = "Atcho!",
  ["_ViridianGymHiker3AfterBattleText"] = "La LEGA POKéMON?\nTu? Non montarti",
  ["_ViridianGymHiker3BattleText"] = "Sono il RE del\nKARATE! Il tuo\vdestino é qui!",
  ["_ViridianGymHiker3EndBattleText"] = "Ayah!",
  ["_ViridianGymRocker1AfterBattleText"] = "Conosci\nl'identita' del\vnostro CAPO?",
  ["_ViridianGymRocker1BattleText"] = "Io e i POKéMON\nfacciamo musica\vmeravigliosa!",
  ["_ViridianGymRocker1EndBattleText"] = "Siete in\nperfetta armonia!",
  ["_ViridianGymRocker2AfterBattleText"] = "Aspetta! Sono\nstato distratto!",
  ["_ViridianGymRocker2BattleText"] = "I tuoi POKéMON\ntremaranno alla\vmia frusta!",
  ["_ViridianGymRocker2EndBattleText"] = "Ahi!\nFrustata!",
  ["_ViridianMartClerkParcelQuestText"] = "Conosci il PROF.\nOAK, giusto? Il\vsuo ordine é\narrivato. Glielo\vporti? {PLAYER}\nprende il PACCO\vdi OAK!",
  ["_ViridianMartClerkSayHiToOakText"] = "Ok! Salutami il\nPROF.OAK!",
  ["_ViridianMartClerkYouCameFromPalletTownText"] = "Ehi! Vieni da\nBIANCAVILLA?",
  ["_ViridianMartCooltrainerMText"] = "No! Le POZIONI\nsono esaurite.",
  ["_ViridianMartYoungsterText"] = "Questo negozio\nvende molti\vANTIDOTI",
  ["_ViridianNicknameHouseBaldingGuyText"] = "Inventare i nomi é\nbello ma duro. I\vnomi semplici sono\ni piu' facili da\vricordare.",
  ["_ViridianNicknameHouseLittleGirlText"] = "Anche il mio papa'\nadora i POKéMON.",
  ["_ViridianNicknameHouseSpearowText"] = "SPEARY: Tetweet!",
  ["_ViridianNicknameHouseSpearySignText"] = "SPEAROW Nome:\nSPEARY",
  ["_ViridianPokecenterCooltrainerMText"] = "C'é un CENTRO\nPOKéMON in ogni\vcitta' davanti. E\nnon si paga\vassolutamente\nnulla!",
  ["_ViridianPokecenterGentlemanText"] = "Puoi usare quel PC\nnell'angolo. Me\vl'ha detto la\nreception. Che\vcarini!",
  ["_ViridianSchoolBlackboardText1"] = "La lavagna de\nscrive i cambi di\vSTATO dei POKéMON\ndurante la lotta.",
  ["_ViridianSchoolBlackboardText2"] = "Quale voce vuoi\nleggere?",
  ["_ViridianSchoolHouseBrunetteGirlText"] = "Uff! Studio per\nmemorizzare tutti\vi miei appunti.",
  ["_ViridianSchoolHouseCooltrainerFText"] = "Bene! Leggi\nattentamente la\vlavagna!",
  ["_ViridianSchoolNotebookText1"] = "Guarda il qua\nderno! Prima\vpagina... Le POKé\nBALL ser vono per\vcatturare i\nPOKéMON. Si\vportano fino a 6\nPOKéMON. Chi li\valleva e fa\nlottare é un\vallenatore\nPOKéMON.",
  ["_ViridianSchoolNotebookText2"] = "Seconda pagina...\nUn POKéMON sano é\vduro da catturare,\nindeboliscilo!\vVeleno, ustioni e\ndanni aiutano!",
  ["_ViridianSchoolNotebookText3"] = "Terza pagina...\nGli allenatori\vcercano sfide. Si\nlotta sempre in\vpalestra.",
  ["_ViridianSchoolNotebookText4"] = "Quarta pagina...\nL'obiettivo é bat\vtere gli 8 CAPO.\nFallito cio',\vsi\affrontano... I\nSUPERQUATTRO\vdella LEGA\nPOKéMON!",
  ["_ViridianSchoolNotebookText5"] = "RAGAZZA: Ehi! Non\nguardare i miei\vappunti!",
  ["_VitaminNoEffectText"] = "Non avra' alcun\neffetto.",
  ["_VitaminStatRoseText"] = "{RAM:wStringBuffer} di\n{RAM:wNameBuffer} é\vaumentato.",
  ["_WannaTrade1Text"] = "Cerco {RAM:wInGameTradeGiveMonName}!\nVuoi scambiarlo\vcon {RAM:wInGameTradeReceiveMonName}?",
  ["_WannaTrade2Text"] = "Ciao! Vuoi scam\nbiare il tuo\v{RAM:wInGameTradeGiveMonName} per\n{RAM:wInGameTradeReceiveMonName}?",
  ["_WannaTrade3Text"] = "Ciao! Hai un\n{RAM:wInGameTradeGiveMonName}? Vuoi\vscambiarlo per\n{RAM:wInGameTradeReceiveMonName}?",
  ["_WardensHouseDisplayMerchandiseText"] = "Vecchi oggetti\nPOKéMON.",
  ["_WardensHouseDisplayPhotosAndFossilsText"] = "Foto e fossili di\nPOKéMON.",
  ["_WardensHouseWardenGaveTheGoldTeethText"] = "{PLAYER} da' i\nDENTI D'ORO al\vGUARDIANO!",
  ["_WardensHouseWardenGibberish1Text"] = "GUARDIA: Hif fuff\nhefifoo! Ha lof\vha feef ee hafahi\nho. Heff hee\vfwee!",
  ["_WardensHouseWardenGibberish2Text"] = "Ah howhee ho hoo!\nEef ee hafahi ho!",
  ["_WardensHouseWardenGibberish3Text"] = "Ha? He ohay heh ha\nhoo ee haheh!",
  ["_WardensHouseWardenHM04ExplanationText"] = "GUARDIA: La MN04\ninsegna FORZA!\vPermette ai\nPOKéMON di\vspostare i massi\nfuori dalla\vlotta. Ah, hai\ntrovato la CASA\vSEGRETA? Se lo\nfai, vinci una\vMN. Sia la rara MN\nSURF",
  ["_WardensHouseWardenHM04NoRoomText"] = "Il tuo zaino é\npieno zeppo!",
  ["_WardensHouseWardenReceivedHM04Text"] = "{PLAYER} riceve\n{RAM:wStringBuffer}!",
  ["_WardensHouseWardenTeethPoppedInHisTeethText"] = "Il GUARDIANO si é\nmesso i denti!",
  ["_WardensHouseWardenThanksText"] = "GUARDIA: Grazie,\nragazzo! Nessuno\vcapiva una parola.\nNon potevo lavo\vrare cosi'. Prendi\nqualcosa per il\vdisturbo.",
  ["_WarpToLastPokemonCenterText"] = "Vai all'ultimo\nCENTRO POKéMON.",
  ["_WasBlownAwayText"] = "{TARGET}\né stato spazzato\vvia!",
  ["_WasSeededText"] = "{TARGET}\né stato\vparassitato!",
  ["_WhatDoYouWantText"] = "Che cosa vuoi\nfare?",
  ["_WhatGoesAroundComesAroundText"] = "Chi la fa\nl'aspetti!",
  ["_WhatText"] = "Cosa?",
  ["_WhatToDepositText"] = "Che cosa vuoi\ndepositare?",
  ["_WhatToTossText"] = "Che cosa vuoi\nbuttare via?",
  ["_WhatToWithdrawText"] = "Che cosa vuoi\nritirare?",
  ["_WhenYouChangeBoxText"] = "Cambiando BOX, i\ndati saranno\vsalvati. Va bene?",
  ["_WhereWouldYouLikeText"] = "Dove vorresti\nandare?",
  ["_WhichFloorText"] = "Quale piano\npreferisci?",
  ["_WhichMoveToForgetText"] = "Quale mossa deve\nessere\vdimenticata?",
  ["_WhichPrizeText"] = "Quale premio vuoi?",
  ["_WildMonAppearedText"] = "Appare {RAM:wEnemyMonNick}\nselvatico!",
  ["_WildRanText"] = "{RAM:wEnemyMonNick}\nselvatico fugge!",
  ["_WillBeTradedText"] = "{RAM:wNameOfPlayerMonToBeTraded} e\n{RAM:wNameBuffer}\vsaranno scambiati.",
  ["_WithExpAllText"] = "con EXP.TUTTI,",
  ["_WithdrawHowManyText"] = "Quanti?",
  ["_WithdrewItemText"] = "Hai ritirato\n{RAM:wNameBuffer}.",
  ["_WokeUpText"] = "{USER}\nsi é svegliato!",
  ["_WontObeyText"] = "{RAM:wBattleMonNick} non\nobbedisce!",
  ["_WouldYouLikeToSaveText"] = "Vuoi SALVARE il\ngioco?",
  ["_WrongMon1Text"] = "Cosa? Non é\n{RAM:wInGameTradeGiveMonName}!\vTrovane uno e\ntorna qui!",
  ["_WrongMon2Text"] = "Mhm? Questo non é\n{RAM:wInGameTradeGiveMonName}. Pensa\va me se ne trovi\nuno.",
  ["_WrongMon3Text"] = "...Questo non é un\n{RAM:wInGameTradeGiveMonName}. Se ne\vtrovi uno,\nscambialo con me!",
  ["_YeahText"] = "Si'!",
  ["_YourNameIsText"] = "Giusto! Ti chiami\nproprio {PLAYER}!",





  ["MelanieText1"] = "Curo i POKéMON\nferiti. Ho curato\vquesto BULBASAUR\nfino a farlo\vguarire. Ora ha\nbisogno di un\vbravo allenatore.",
  ["MelanieText2"] = "Ho un'idea! Vuoi\nprenderti cura di\vquesto BULBASAUR?",
  ["MelanieText3"] = "Abbi cura di\nBULBASAUR!",
  ["MelanieText4"] = "Come sta il tuo\nBULBASAUR?",
  ["MelanieText5"] = "Oh... Che\npeccato...",
  ["OAK: Look, {PLAYER}! Do\nyou see that ball\non the table?"] = "OAK: Guarda {PLAYER}!\nVedi quella sfera\nsul tavolo?",
  ["SilphCo2FSilphWorkerFPleaseTakeThisText"] = "Aaaaah! No! Aiuto!\nAh, non sei del\vTEAM ROCKET.\nPensavo...\vPerdonami! Prendi\nquesto, ti prego!",
  ["SummerBeachHouseSurfinDudeText1"] = "Uau! Il tuo\nPIKACHU sa usare\vSURF! Allora non\nsono il solo...\vFantastico! Ora\npuoi fare SURF\vinsieme a me! Ti\nva?",
  ["SummerBeachHouseSurfinDudeText2"] = "Vieni a fare SURF\nquando vuoi,\vamico!",
  ["SummerBeachHouseSurfinDudeText3"] = "Vuoi fare SURF?",
  ["SummerBeachHouseSurfinDudeText4"] = "Oggi c'e' una gran\nbella onda!",
  ["_MrPsychicsHouseMrPsychicNoMoreText"] = "...Aumm...",
  ["_MrPsychicsHouseMrPsychicText"] = "...Aspetta! Non\ndire una parola!\vVolevi questo!",
  ["_MtMoonJessieJamesText1"] = "Fermati li'!",
  ["_MtMoonJessieJamesText2"] = "Quel fossile e'\ndel TEAM ROCKET!\vArrenditi subito o\npreparati a\vcombattere!",
  ["_MtMoonJessieJamesText3"] = "Un ragazzino ci ha\nbattuti?",
  ["_MtMoonJessieJamesText4"] = "Il TEAM ROCKET\nparte alla carica\valla velocita'\ndella luce!",
  ["_MtMoonPokecenterMagikarpSalesmanOfferText"] = "UOMO: Salve! Ho\nun'offerta\vspeciale per te!\nTi daro' un\vfantastico\nMAGIKARP per soli\v500¥! Che ne dici?",
  ["_OaksLabChooseMonText"] = "OAK: Eh? {RIVAL}?\nPerche' sei gia'\vqui? Ti avevo\ndetto di venire\vpiu' tardi... Beh,\npazienza! Aspetta\vun attimo. Guarda,\n{PLAYER}! Vedi\vquella sfera sul\ntavolo? Si chiama\vPOKé BALL.\nContiene un\vPOKéMON. Puoi\nprenderla! Forza,\ve' tua!",
  ["_OaksLabOak1GoAheadItsYours"] = "Forza, e' tuo!",
  ["_OaksLabOak1YouShouldTalkToIt"] = "OAK: Dovresti\nparlargli per\vvedere come sta.",
  ["_OaksLabOakGivesText"] = "OAK: {PLAYER},\nquesto e' il\vPOKéMON che ho\ncatturato. Puoi\vtenerlo tu. L'ho\ncatturato da\vpoco, quindi e'\nancora selvatico.",
  ["_OaksLabPikachuDislikesPokeballsText1"] = "OAK: Cosa?",
  ["_OaksLabPikachuDislikesPokeballsText2"] = "OAK: Guarda qui!\nE' strano, ma\vsembra che il tuo\nPIKACHU odi le\vPOKé BALL. Tienilo\nfuori con te. Lo\vrendera' felice!\nPuoi parlargli\vper vedere come\nsta.",
  ["_OaksLabPikachuText"] = "OAK: Forza, e'\ntuo!",
  ["_OaksLabReceivedText"] = "{PLAYER} riceve\n{RAM:wNameBuffer}!",
  ["_OaksLabRivalIllGetABetterPokemonThanYou"] = "{RIVAL}: Uffa!\nPrendero' un\vPOKéMON migliore\ndel tuo!",
  ["_OaksLabRivalTakesText1"] = "{RIVAL}: Non se ne\nparla! {PLAYER},\vio voglio questo!",
  ["_OaksLabRivalTakesText2"] = "{RIVAL} prende il\nPOKéMON!",
  ["_OaksLabRivalTakesText3"] = "OAK: {RIVAL}! Ma\ncosa fai?",
  ["_OaksLabRivalTakesText4"] = "{RIVAL}: Nonno, io\nvoglio questo!",
  ["_OaksLabRivalTakesText5"] = "OAK: Ma io... Ah,\ne va bene. Prendi\vpure quello. Tanto\nvolevo darne uno\vanche a te...\n{PLAYER}, vieni\vqui.",
  ["_OaksLabThatsAPokeball"] = "Questa e' una POKé\nBALL!",
  ["_OfficerJennyText1"] = "Ho appena preso\nquesto SQUIRTLE\vche creava\nproblemi. Ha\vbisogno di un\nbravo allenatore\vche lo educhi.",
  ["_OfficerJennyText2"] = "Hai la MEDAGLIA\nTUONO!? Devi\vessere un bravo\nallenatore! Ho\vpreso questo\nSQUIRTLE che dava\vsempre problemi.\nVorresti\vallenarlo?",
  ["_OfficerJennyText3"] = "OK! Abbi cura di\nSQUIRTLE!",
  ["_OfficerJennyText4"] = "Oh... Che cosa\nfaro' adesso?",
  ["_OfficerJennyText5"] = "Come sta andando\ncon SQUIRTLE?",
  ["_PalletTownOakComeWithMe"] = "Vieni con me!",
  ["_PalletTownOakThatWasCloseText"] = "C'e' mancato poco!\nPOKéMON selvatici\vvivono nell'erba!",
  ["_PalletTownOakWhewText"] = "Uff...",
  ["_PokemonTowerJessieJamesText1"] = "Fermati li'!",
  ["_PokemonTowerJessieJamesText2"] = "Il vecchio laggiu'\nvoleva\vlamentarsi, cosi'\ngli daremo una\vlezione. Arrenditi\nsubito o\vpreparati a\ncombattere!",
  ["_PokemonTowerJessieJamesText3"] = "Te ne pentirai,\nragazzetto!",
  ["_PokemonTowerJessieJamesText4"] = "Sembra che il TEAM\nROCKET decolli di\vnuovo!",
  ["_RocketHideoutJessieJamesText1"] = "Non fare un solo\npasso, moccioso!",
  ["_RocketHideoutJessieJamesText2"] = "Come hai osato\numiliarci sul\vMONTE LUNA?! E'\nora della resa\vdei conti!",
  ["_RocketHideoutJessieJamesText3"] = "Maledetto\nmoccioso!",
  ["_RocketHideoutJessieJamesText4"] = "Sembra che il TEAM\nROCKET decolli di\vnuovo!",
  ["_Route24DamianText1"] = "Non sono bravo ad\nallenare i\vPOKéMON. Penso che\ndovrei liberare\vil mio\nCHARMANDER... Se\vmi prometti che ne\navrai cura, te lo\vregalo. Va bene?",
  ["_Route24DamianText2"] = "Abbi cura del mio\nCHARMANDER!",
  ["_Route24DamianText3"] = "Ah... Allora e'\nmeglio liberarlo.",
  ["_Route24DamianText4"] = "Come sta il mio\nCHARMANDER?",
  ["_SSAnne1FRoomsGentleman2BattleText"] = "Moccioso! Che\nsfacciato!",
  ["_SSAnneKitchenCook2Text"] = "Ho visto una sfera\nmolto strana nel\vcestino.",
  ["_SilphCo7FSilphWorkerM1ThankYouText"] = "Ah! Ehi! Non sei\ndel TEAM ROCKET!\vSei venuto a\nsalvarmi? Grazie\vmille! Voglio che\ntu abbia questo\vPOKéMON per averci\nsalvati.",
  ["_SilphCo9FNurseText"] = "Non arrenderti!",
  ["_SilphCo9FNurseText2"] = "Grazie mille!",
  ["_SilphCo9FNurseYouLookTiredText"] = "Sembri molto\nstanco! Dovresti\vriposarti un po'!",
  ["_SilphCoJessieJamesText1"] = "Fermati li',\nmoccioso!",
  ["_SilphCoJessieJamesText2"] = "Il nostro CAPO e'\nin una riunione!\vNon disturbarlo!",
  ["_SilphCoJessieJamesText3"] = "Come sempre...",
  ["_SilphCoJessieJamesText4"] = "TEAM ROCKET,\npronti a\vdecollare alla\nvelocita' della\vluce! Di nuovo...",
  ["_StoppedEvolvingText"] = "Uh? {RAM:wStringBuffer} ha\nsmesso di\vevolversi!",
  ["_StrengthsAndWeaknessesText"] = "Tutti i tipi di\nPOKéMON hanno\vpunti di forza e\ndi debolezza\vcontro gli altri\ntipi.",
  ["_SummerBeachHousePoster1Text1"] = "Appunti del\nMAESTRO\vSURFISTA... Quando\nentro nel tubo,\vla musica parte a\npalla!",
  ["_SummerBeachHousePoster1Text2"] = "30 anni di onde!\nMAESTRO SURFISTA",
  ["_SummerBeachHousePoster2Text1"] = "CONSIGLI UTILI\nSURF 1 Dopo un\vsalto, allinea la\ntavola con l'onda\vper un effetto\nsuper!",
  ["_SummerBeachHousePoster2Text2"] = "CASA SULLA\nSPIAGGIA ESTIVA\vPOKéMON Benvenuti!",
  ["_SummerBeachHousePoster3Text1"] = "CONSIGLI UTILI\nSURF 2 Fare piu'\vrotazioni in un\nsalto e' troppo\vforte!",
  ["_SummerBeachHousePoster3Text2"] = "Il mare unisce\ntutti i surfisti!",
  ["_SummerBeachHousePrinterText1"] = "E' una specie di\nmacchinario...",
  ["_SummerBeachHousePrinterText2"] = "STAMPANTE DELLA\nCASA SULLA\vSPIAGGIA ESTIVA\nPOKéMON...",
  ["_SummerBeachHousePrinterText3"] = "Mostra i tuoi\nrecord. Vuoi\vSTAMPARE?",
  ["_SummerBeachHousePrinterText4"] = "STAMPANTE DELLA\nCASA SULLA\vSPIAGGIA ESTIVA\nPOKéMON... Mostra\vi tuoi record.\nVuoi STAMPARE?",
  ["_SummerBeachHousePrinterText5"] = "STAMPA completata!",
  ["_SummerBeachHousePrinterText6"] = "Errore di stampa!",
  ["_VermilionGymTrashFailText"] = "No! C'e' solo\nspazzatura qui.\vEhi! Le serrature\nelettroniche si\vsono riattivate!",
  ["_ViridianCityOldManLosingMyTouchText"] = "Non ha funzionato\ncome pensavo. Sto\vperdendo il mio\ntocco... Ho\vfinito anche le\nPOKé BALL. Andro'\va comprarne altre\nal BAZAR.",
  ["_ViridianCityOldManYouNeedToWeakenTheTargetText"] = "Prima di tutto,\ndevi indebolire\vil POKéMON.",
  ["_ViridianForestCooltrainerFAfterBattleText"] = "Ho cercato\ndappertutto, ma\vnon ho trovato\nnessun PIKACHU!",
  ["_ViridianForestCooltrainerFBattleText"] = "Ehi, hai un\nPIKACHU?",
  ["_ViridianForestCooltrainerFEndBattleText"] = "Oh,\nno! Davvero?",
  ["_ViridianForestYoungster5AfterBattleText"] = "\nMETAPOD e' forte\vperche' la sua\nmiglior difesa e'\vl'ATTACCO!",
  ["_ViridianForestYoungster5BattleText"] = "\nSaro' il\vmigliore. Non\npotrai mai\vbattermi!",
  ["_ViridianForestYoungster5EndBattleText"] = "Dopo\ntutto quello che\vho fatto...",
  ["_ViridianForestYoungster6Text"] = "Ho\nfinito le POKé\vBALL per catturare\naltri POKéMON! E'\vsempre meglio\navere qualche\vscorta!",

  ["FanClubChairPrintText1"] = "Ciao, {PLAYER}! Hai\ngia' visto le mie\vfoto di #MON? Le\nho messe in\vcornice e appese\nla' sulla parete.\vAh, gia'! Vuoi che\nti faccia una\vfoto dei tuoi\nPOKéMON",
  ["FanClubChairPrintText2"] = "No? Che delusione",
  ["FanClubChairPrintText3"] = "Ecco fatto",
  ["FanClubChairPrintText4"] = "Possiamo STAMPARE\nin un altro\vmomento",
  ["SSAnneKitchenCook7EelsAuBarbecueText"] = "Spiedini di\nanguilla! Temo\vche gli invitati\nfaranno una\vrivolta",
  ["SSAnneKitchenCook7PrimeBeefSteakText"] = "Bistecca di manzo!\nMa avremo\vabbastanza\nbistecche",
  ["SSAnneKitchenCook7SalmonDuSaladText"] = "Insalata di\nsalmone! Eppure\vgli invitati\nprotesteranno\vperché é di nuovo\npesce",
  ["TMNotebookText"] = "É un volantino\nsulle MT. ... Ci\vsono 50 MT in\ntotale. Esistono\vanche 5 SM che si\npossono usare\vpiu' volte. SILPH\nSPA",
  ["TeachingHMsText"] = "Quando un POKéMON\nimpara una MO, la\vmossa non potra'\npiu' essere\vdimenticata. É\nbene pensarci\vbene prima di\ninsegnare una\vmossa MO",
  ["ViridianCityFisherYouCanHaveThisText"] = "Uffa! De me ne\nsono addormentato\val sole. Ho\nsognato che un\vDROWZEE si\nmangiava i miei\vsogni... Cos'é\nquesto? Da dove\vspunta questa MT?\nChe paura! Tieni,\vprendi questa MT",
  ["_FanClubChairPrintText1"] = "Ciao, {PLAYER}! Hai\ngia' visto le mie\vfoto di #MON? Le\nho messe in\vcornice e appese\nla' sulla parete.\vAh, gia'! Vuoi che\nti faccia una\vfoto dei tuoi\nPOKéMON",
  ["_FanClubChairPrintText2"] = "No? Che delusione",
  ["_FanClubChairPrintText3"] = "Ecco fatto",
  ["_FanClubChairPrintText4"] = "Possiamo STAMPARE\nin un altro\vmomento",
  ["_GameCornerClerkCantAffordTheCoinsText"] = "",
  ["_GameCornerClerkCoinCaseIsFullText"] = "",
  ["_GameCornerClerkDoYouNeedSomeGameCoinsText"] = "",
  ["_GameCornerClerkDontHaveCoinCaseText"] = "",
  ["_GameCornerClerkPleaseComePlaySometimeText"] = "",
  ["_GameCornerClerkThanksHereAre50CoinsText"] = "",
  ["_GameCornerFishingGuru1DontNeedMyCoinsText"] = "",
  ["_GameCornerFishingGuru1Received10CoinsText"] = "",
  ["_GameCornerFishingGuru1WantToPlayText"] = "",
  ["_GameCornerFishingGuru1WinsComeAndGoText"] = "",
  ["_GameCornerFishingGuru2CloselyWatchTheReelsText"] = "",
  ["_GameCornerFishingGuru2Received20CoinsText"] = "",
  ["_GameCornerFishingGuru2ThrowingMeOffText"] = "",
  ["_GameCornerFishingGuru2YouGotYourOwnCoinsText"] = "",
