  ["_GameCornerMiddleAgedMan2Received20CoinsText"] = "",
  ["_GameCornerMiddleAgedMan2WantSomeCoinsText"] = "",
  ["_GameCornerMiddleAgedMan2YouHaveLotsOfCoinsText"] = "",
  ["_OaksLabRivalMyPokemonHasGrownStrongerText"] = "{RIVAL}: Nonno, il\nmio POKéMON é\vcresciuto un\nsacco! Guardati\vquesto",
  ["_PokemonFanClubClefairyFanBetterText"] = "Bah! Il mio\nCLEFAIRY é due\vvolte piu' carino\ndi quel pesce",
  ["_PokemonFanClubClefairyFanNormalText"] = "Non vuoi ammirare\nl'adorabile coda\vdel mio CLEFAIRY",
  ["_PokemonFanClubClefairyFanText"] = "Il passatempo del\nostro PRESIDENTE\vora é fotografare\ni POKéMON. Mi ha\vdato una foto\nSTAMPATA del mio\vCLEFAIRY",
  ["_PokemonFanClubClefairyText"] = "CLEFAIRY: Fiffii",
  ["_PokemonFanClubSeelFanText"] = "Ho bisogno di un\ncavo per\vconnettere e\nSTAMPARE una foto\vdel mio SEEL",
  ["_SSAnneKitchenCook7EelsAuBarbecueText"] = "Spiedini di\nanguilla! Temo\vche gli invitati\nfaranno una\vrivolta",
