  ["_ViridianCityFisherYouCanHaveThisText"] = "Uffa! De me ne\nsono addormentato\val sole. Ho\nsognato che un\vDROWZEE si\nmangiava i miei\vsogni... Cos'é\nquesto? Da dove\vspunta questa MT?\nChe paura! Tieni,\vprendi questa MT",
